const e={한글:{ko:"한글",romanization:"hangeul",en:"Hangul (Korean writing system)",pos:"noun",chapter:"1",ex:{ko:"한글은 배우기 쉬워요.",en:"Hangul is easy to learn.",note:"Topic particle 은 attaches to 한글 — you will learn this particle in Chapter 2"},collocations:["한글을 배우다","한글을 읽다","한글을 쓰다"],nuance:"Say 한글 for the writing system, 한국어 for the language. This chapter is about the writing system first.",explanation:'한글 (hangeul) = "Hangul / Korean writing system". Treat it as a building block that needs a frame: 한글을 읽다 ("to read Hangul") shows how it actually behaves. The grammar lives in the particle or ending beside 한글, so notice that piece as you read, not just the dictionary meaning. Begin from a complete sentence about basic everyday communication and swap just one element to make it yours.',shortExplanation:'한글 means "Hangul / Korean writing system" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Do not treat romanization as Korean spelling. Read the Hangul first, then use romanization only to check."],conjugationTips:[],usagePhrases:[{ko:"한글을 읽다",romanization:"hangeureul ilkda",en:"to read Hangul",note:"what the learner is practicing"},{ko:"한글을 쓰다",romanization:"hangeureul sseuda",en:"to write Hangul",note:"writing practice"},{ko:"한글 글자",romanization:"hangeul geulja",en:"Hangul character",note:"letter/block focus"}],examples:[{ko:"한글은 소리 글자예요.",romanization:"hangeureun sori geuljayeyo.",en:"Hangul is a sound-based writing system.",note:"This is the core sentence of Chapter 1."}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[1]},자음:{ko:"자음",romanization:"jaeum",en:"consonant",pos:"noun",chapter:"1",ex:{ko:"ㄱ은 자음이에요.",en:"ㄱ is a consonant.",note:"이에요 means 'is/am/are' — the simplest Korean copula; perfect for labeling what something is"},collocations:["자음을 배우다","받침 자음","기본 자음"],nuance:"A consonant can sit at the beginning of a block, and some consonants can also sit at the bottom as 받침.",explanation:'자음 (jaeum) means "consonant". Learn it inside a frame, not as a bare word: a useful first chunk is 기본 자음 ("basic consonants"). In Korean the particle or ending next to 자음 signals its job — topic, subject, object, place, time, method, or description — so read the examples for the small piece beside it. Start with one real sentence about basic everyday communication, then change a single part.',shortExplanation:'자음 means "consonant" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Do not read the consonant names as if they were English letter names. Listen and imitate the Korean names."],conjugationTips:[],usagePhrases:[{ko:"기본 자음",romanization:"gibon jaeum",en:"basic consonants",note:"chapter vocabulary"},{ko:"받침 자음",romanization:"batchim jaeum",en:"final consonant",note:"bottom consonant role"}],examples:[{ko:"ㄱ은 자음이에요.",romanization:"geun jaeumieyo.",en:"ㄱ is a consonant.",note:"Use this frame to label letters."}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[1]},모음:{ko:"모음",romanization:"moeum",en:"vowel",pos:"noun",chapter:"1",ex:{ko:"ㅏ는 모음이에요.",en:"ㅏ is a vowel.",note:"는 is the topic marker for vowel-ending words — 모음 ends in ㅁ so it uses 은, but ㅏ alone ends in a vowel, so 는 attaches"},collocations:["모음을 배우다","기본 모음","합성 모음"],nuance:"The visual direction of a vowel helps the learner remember the mouth shape.",explanation:'"vowel" is 모음 (moeum). The word itself is easy; what matters is the company it keeps, like 기본 모음 ("basic vowels"). Watch the particle attached to 모음 in each example — that little marker, not the word, tells you whether it is the topic, the subject, the object, or a place. Copy one full sentence about basic everyday communication first, then vary one word.',shortExplanation:'모음 means "vowel" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Do not put a tall vowel below the consonant; tall vowels sit to the right."],conjugationTips:[],usagePhrases:[{ko:"기본 모음",romanization:"gibon moeum",en:"basic vowels",note:"first vowel set"},{ko:"모음을 읽다",romanization:"moeumeul ilkda",en:"to read vowels",note:"practice action"}],examples:[{ko:"ㅏ는 모음이에요.",romanization:"aneun moeumieyo.",en:"ㅏ is a vowel.",note:"ㅏ is a tall vowel that sits to the right."}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[1]},글자:{ko:"글자",romanization:"geulja",en:"letter / character",pos:"noun",chapter:"1",ex:{ko:"이 글자가 뭐예요?",en:"What is this character?",note:"뭐예요 = 'what is it?' — an essential question frame for asking about unfamiliar characters"},collocations:["글자를 읽다","글자를 쓰다","한글 글자"],nuance:"글자 can mean an individual written unit. In this chapter it usually points to a Hangul block or letter being studied.",explanation:'글자 (geulja) = "letter / character". Treat it as a building block that needs a frame: 이 글자 ("this character") shows how it actually behaves. The grammar lives in the particle or ending beside 글자, so notice that piece as you read, not just the dictionary meaning. Begin from a complete sentence about basic everyday communication and swap just one element to make it yours.',shortExplanation:'글자 means "letter / character" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Do not assume every visible shape equals one English-style letter; a Hangul block can contain two or three letters."],conjugationTips:[],usagePhrases:[{ko:"이 글자",romanization:"i geulja",en:"this character",note:"pointing at a letter"},{ko:"글자를 읽다",romanization:"geuljareul ilkda",en:"to read a character",note:"reading practice"}],examples:[{ko:"이 글자가 뭐예요?",romanization:"i geuljaga mwoyeyo?",en:"What is this character?",note:"A survival question for the first lesson."}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[1]},소리:{ko:"소리",romanization:"sori",en:"sound",pos:"noun",chapter:"1",ex:{ko:"이 글자의 소리가 뭐예요?",en:"What is the sound of this character?",note:"의 is a possessive particle — '글자의 소리' = 'the sound of the character'"},collocations:["소리를 듣다","소리를 내다","같은 소리"],nuance:"소리 points to what you hear, while 글자 points to what you see.",explanation:'소리 (sori) means "sound". Learn it inside a frame, not as a bare word: a useful first chunk is 소리를 듣다 ("to listen to the sound"). In Korean the particle or ending next to 소리 signals its job — topic, subject, object, place, time, method, or description — so read the examples for the small piece beside it. Start with one real sentence about basic everyday communication, then change a single part.',shortExplanation:'소리 means "sound" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Do not read romanization with English habits and call that the sound. Listen to the Korean sound."],conjugationTips:[],usagePhrases:[{ko:"소리를 듣다",romanization:"sorireul deutda",en:"to listen to the sound",note:"audio-first practice"},{ko:"같은 소리",romanization:"gateun sori",en:"the same sound",note:"sound comparison"}],examples:[{ko:"이 글자의 소리가 뭐예요?",romanization:"i geuljaui soriga mwoyeyo?",en:"What is the sound of this character?",note:"Ask this when the shape is new."}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[1]},받침:{ko:"받침",romanization:"batchim",en:"final consonant (bottom of syllable block)",pos:"noun",chapter:"1",ex:{ko:"한에는 받침 ㄴ이 있어요.",en:"한 has the final consonant ㄴ.",note:"한 = ㅎ + ㅏ + ㄴ. The final ㄴ is the 받침."},collocations:["받침이 있다","받침이 없다","받침 ㄴ"],nuance:"받침은 동사 '받치다(아래에서 받쳐 주다, to support from underneath)'에서 나온 명사로, 컵이나 그릇 '아래에' 받쳐 두는 작은 판을 두루 가리켜요. 그래서 핵심 의미는 '무엇의 아래에 두어 받쳐 주는 것'이고, 영어처럼 용도별로 saucer/coaster/trivet으로 쪼개지 않고 한 단어로 폭넓게 써요. 가장 가까운 짝은 '컵받침'인데, 받침이 일반적인 '아래 받치는 것' 전체를 뜻한다면 컵받침은 '컵 전용 받침'으로 범위가 좁아요 — 즉 컵받침은 받침의 한 종류예요. 같은 원리로 냄비받침(trivet)도 만들어져요. 영어 화자가 흔히 하는 실수는 받침을 음식을 담아 먹는 접시로 오해하는 것인데, 받침은 먹는 그릇이 아니라 다른 것을 받쳐 두는 '바닥 판'이에요. 또 한국어 받침은 글자에서 자음이 아래에 받치는 부분(예: '강'의 ㅇ)도 가리키니, 식기 맥락인지 한글 맥락인지 문맥으로 구별하세요.",explanation:'받침 (batchim) = "saucer / coaster (stand under something)". Treat it as a building block that needs a frame: 받침에 놓다 ("to set on the saucer/stand") shows how it actually behaves. The grammar lives in the particle or ending beside 받침, so notice that piece as you read, not just the dictionary meaning. Begin from a complete sentence about ordering food, explaining food restrictions, and asking what to eat together and swap just one element to make it yours.',shortExplanation:'받침 means "saucer / coaster (stand under something)" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Thinking 받침 is a plate you eat from; it's a stand placed underneath something (a cup, a pot), not a serving dish — the word literally comes from 받치다 'to support from below'.","Assuming 받침 only means a cup coaster; it's the general word for 'the thing underneath', so a trivet under a pot is 냄비받침 and a coaster under a cup is 컵받침.","Forgetting that 받침 also means the bottom consonant of a Korean syllable block; in a tableware context it's the physical stand, but learners sometimes mix the two senses."],conjugationTips:[],usagePhrases:[{ko:"받침에 놓다",romanization:"batchime nota",en:"to set on the saucer/stand",note:"에 marks the stand as the surface; 놓다 = to put down"},{ko:"받침을 받치다",romanization:"batchimeul batchida",en:"to place a stand underneath",note:"받치다 = to support from below — the verb the noun comes from"},{ko:"받침이 있다",romanization:"batchimi itda",en:"there is a saucer/stand",note:"있다 expresses existence; 받침 없이 = without a stand"},{ko:"컵받침",romanization:"keopbatchim",en:"cup coaster",note:"받침 compounds: 컵받침 (coaster), 냄비받침 (trivet) — '받침' = the thing underneath"}],examples:[{ko:"받침이 없어요.",romanization:"batchimi eopseoyo.",en:"There's no saucer.",note:"있다/없다 existence; a quick way to point out a missing stand under your cup."},{ko:"뜨거운 컵을 받침에 놓으세요.",romanization:"tteugeoun keobeul batchime noeuseyo.",en:"Put the hot cup on the saucer.",note:"에 marks the destination; the saucer protects the table from the hot cup."},{ko:"받침이 없으면 컵이 미끄러워요.",romanization:"batchimi eopseumyeon keobi mikkeureowoyo.",en:"Without a stand the cup slides around.",note:"-(으)면 = if/when; explains why the 받침 underneath is useful."}],forms:null,irregular:null,level:"A2",cluster:null,chapters:[1]},발음:{ko:"발음",romanization:"bareum",en:"pronunciation",pos:"noun",chapter:"1",ex:{ko:"발음이 어려워요.",en:"The pronunciation is difficult.",note:"A natural comment to make as a beginner — acknowledges that pronunciation takes practice"},collocations:["발음을 연습하다","발음이 좋다","정확한 발음"],nuance:"발음(發音) is Sino-Korean — 發 'to emit/produce' + 音 'sound' — literally 'to produce sound,' i.e. pronunciation, how a word is sounded out. Distinguish it from 억양(抑揚) 'intonation' (the rise and fall of pitch across a sentence) and 발성 'voice production/projection' — 발음 is specifically the articulation of individual sounds and syllables. As a noun it becomes a verb with 하다: 발음하다 'to pronounce.' Collocations: 발음이 좋다/나쁘다/어렵다/정확하다, 발음을 연습하다, 발음 연습 'pronunciation drill,' 받침 발음 'final-consonant pronunciation.' The headline English-speaker pitfall is PARTICLES: 발음 is the SUBJECT of descriptive adjectives, so it's 발음이 좋다/어렵다 (이/가), but the OBJECT of action verbs, so 발음을 연습하다/하다 (을/를). Saying 발음을 좋다 is ungrammatical because 좋다 'to be good' is a stative adjective that can't take a direct object. Also, English 'pronounce' as a verb tempts bare 발음 — you must say 발음하다.",explanation:'발음 (bareum) = "pronunciation". Treat it as a building block that needs a frame: 발음이 좋다 ("to have good pronunciation") shows how it actually behaves. The grammar lives in the particle or ending beside 발음, so notice that piece as you read, not just the dictionary meaning. Begin from a complete sentence about basic everyday communication and swap just one element to make it yours.',shortExplanation:'발음 means "pronunciation" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Saying 발음을 좋다 — descriptive 좋다/어렵다 take 이/가: 발음이 좋다, 발음이 어렵다.","Using bare 발음 for the verb 'pronounce' — say 발음하다 (e.g. 이 글자를 어떻게 발음해요?).","Confusing 발음 (articulation of sounds) with 억양 (sentence intonation) — flat or sing-song pitch is 억양, not 발음."],conjugationTips:[],usagePhrases:[{ko:"발음이 좋다",romanization:"bareumi jota",en:"to have good pronunciation",note:"the quality takes 이/가: 발음이 좋다, NOT 발음을 좋다"},{ko:"발음을 연습하다",romanization:"bareumeul yeonseupada",en:"to practice pronunciation",note:"연습하다 takes the object 을/를; here you act on 발음"},{ko:"발음이 어렵다",romanization:"bareumi eoryeopda",en:"the pronunciation is hard",note:"어렵다 is an adjective describing 발음, so again 이/가"},{ko:"발음이 정확하다",romanization:"bareumi jeonghwakada",en:"to pronounce accurately (lit. pronunciation is exact)",note:"정확하다 = precise/accurate; a common compliment for learners"}],examples:[{ko:"발음이 정말 좋아요.",romanization:"bareumi jeongmal joayo.",en:"Your pronunciation is really good.",note:"발음이 좋다 with 이 — the pronunciation is the subject being good"},{ko:"이 단어는 발음이 어려워요.",romanization:"i daneoneun bareumi eoryeowoyo.",en:"This word is hard to pronounce.",note:"ㅂ-irregular 어렵다 → 어려워요; 발음이 어렵다 keeps 이/가"},{ko:"받침 발음을 매일 연습해요.",romanization:"batchim bareumeul maeil yeonseupaeyo.",en:"I practice the final-consonant sounds every day.",note:"받침 = a syllable-final consonant; 발음을 연습하다 takes 을 because you act on it"}],forms:null,irregular:null,level:"A2",cluster:null,chapters:[1]},쓰다:{ko:"쓰다",romanization:"sseuda",en:"to write / use",pos:"verb",chapter:"1·5",ex:{ko:"이름을 써요.",en:"I write my name.",note:"쓰다 is ㅡ-irregular: the ㅡ drops before 아/어, giving 써요 not 쓰어요"},collocations:["이름을 쓰다","한글을 쓰다","펜으로 쓰다"],nuance:"쓰다 can mean write or use. The object tells the meaning: 이름을 쓰다, 카드를 쓰다.",explanation:`쓰다 (sseuda) = "to write / use". Don't try to memorize all fifteen forms at once; anchor on 써요 plus one useful sentence like 이름을 써요 ("write a name."). After that the endings carry the meaning — 쓰고 싶어요 for what you want, 쓸 수 있어요 for what you can, 못 써요 for what you can't. Keep the stem, change the ending, and one verb gives you a dozen sentences about classroom communication, study plans, and asking for repetition or help.`,shortExplanation:'쓰다 means "to write / use" and is practiced through polite conversation forms.',commonMistakes:["Do not use the dictionary form 쓰다 as a complete polite sentence.","Use 써요 as the default until you know the relationship is casual."],conjugationTips:[{title:"ㄹ / 을 — can & will",body:'To say "can" or the future, attach ㄹ/을 to the stem: a vowel-final stem takes ㄹ and a consonant-final stem takes 을. 쓰다 becomes 쓸 수 있어요 ("can") and 쓸 거예요 ("will"). That is why 가다 → 갈 수 있어요 (not 가을), while 먹다 → 먹을 수 있어요. The same ㄹ/을 choice drives 거예요 and the noun-describing form.'}],usagePhrases:[{ko:"써요",romanization:"sseoyo",en:"I write / use.",note:"Safe polite present form."},{ko:"안 써요",romanization:"an sseoyo",en:"I do not write / use.",note:"Short everyday negative."},{ko:"쓰고 싶어요",romanization:"sseugo sipeoyo",en:"I want to write / use.",note:"Useful for choices and plans."},{ko:"쓸 수 있어요",romanization:"sseul su isseoyo",en:"I can write / use.",note:"Ability or possibility."},{ko:"써야 해요",romanization:"sseoya haeyo",en:"I have to write / use.",note:"Requirement or obligation."},{ko:"이름을 써요",romanization:"ireumeul sseoyo",en:"write a name.",note:"Writing meaning."}],examples:[{ko:"이름을 써 주세요.",romanization:"ireumeul sseo juseyo.",en:"Please write your name.",note:"Form or document."},{ko:"카드 써도 돼요?",romanization:"kadeu sseodo dwaeyo?",en:"Can I use a card?",note:"Payment."},{ko:"펜을 못 써요.",romanization:"peneul mot sseoyo.",en:"I cannot use the pen.",note:"Ability."}],forms:{dictionary:"쓰다",casualPresent:"써",politePresent:"써요",formalPresent:"씁니다",negative:"안 써요",past:"썼어요",future:"쓸 거예요",want:"쓰고 싶어요",can:"쓸 수 있어요",cannot:"못 써요",must:"써야 해요",dontHaveTo:"안 써도 돼요",pleaseDo:"써 주세요",pleaseDont:"쓰지 마세요",shallWe:"쓸까요?"},irregular:null,level:"A1",cluster:null,chapters:[1,5]},"따라 하다":{ko:"따라 하다",romanization:"ttara hada",en:"to repeat / follow along",pos:"verb",chapter:"1",ex:{ko:"저를 따라 하세요.",en:"Please repeat after me.",note:"따라 하세요 is a polite command — very common in language class settings"},collocations:["따라 하다","따라 읽다","따라 쓰다"],nuance:"하다 combines with many nouns: 공부하다, 일하다, 운동하다. It is one of the most important Korean verbs.",explanation:'하다 (hada) means "to do". Start from the polite form 해요 — it is safe with almost anyone, so use it before the dictionary form 하다. A strong first sentence is 숙제를 해요 ("do homework."); once that feels natural, swap the noun, place, or time and reuse the verb everywhere. Korean changes the ending rather than the word, so the same 하다 also becomes 하고 싶어요 (want), 할 수 있어요 (can), and 못 해요 (cannot). Say one true sentence about talking about work, schedules, tasks, and obligations, then bend it.',shortExplanation:'하다 means "to do" and is practiced through polite conversation forms.',commonMistakes:["Do not use the dictionary form 하다 as a complete polite sentence.","Use 해요 as the default until you know the relationship is casual."],conjugationTips:[{title:"ㄹ / 을 — can & will",body:'To say "can" or the future, attach ㄹ/을 to the stem: a vowel-final stem takes ㄹ and a consonant-final stem takes 을. 하다 becomes 할 수 있어요 ("can") and 할 거예요 ("will"). That is why 가다 → 갈 수 있어요 (not 가을), while 먹다 → 먹을 수 있어요. The same ㄹ/을 choice drives 거예요 and the noun-describing form.'}],usagePhrases:[{ko:"해요",romanization:"haeyo",en:"I do.",note:"Safe polite present form."},{ko:"안 해요",romanization:"an haeyo",en:"I do not do.",note:"Short everyday negative."},{ko:"하고 싶어요",romanization:"hago sipeoyo",en:"I want to do.",note:"Useful for choices and plans."},{ko:"할 수 있어요",romanization:"hal su isseoyo",en:"I can do.",note:"Ability or possibility."},{ko:"해야 해요",romanization:"haeya haeyo",en:"I have to do.",note:"Requirement or obligation."},{ko:"숙제를 해요",romanization:"sukjereul haeyo",en:"do homework.",note:"Noun + 하다 pattern."}],examples:[{ko:"지금 해요.",romanization:"jigeum haeyo.",en:"I do it now.",note:"Simple sentence."},{ko:"제가 할 수 있어요.",romanization:"jega hal su isseoyo.",en:"I can do it.",note:"Ability."},{ko:"안 해도 돼요.",romanization:"an haedo dwaeyo.",en:"You do not have to do it.",note:"Very useful permission."}],forms:{dictionary:"하다",casualPresent:"해",politePresent:"해요",formalPresent:"합니다",negative:"안 해요",past:"했어요",future:"할 거예요",want:"하고 싶어요",can:"할 수 있어요",cannot:"못 해요",must:"해야 해요",dontHaveTo:"안 해도 돼요",pleaseDo:"해 주세요",pleaseDont:"하지 마세요",shallWe:"할까요?"},irregular:null,level:"A1",cluster:null,chapters:[1]},천천히:{ko:"천천히",romanization:"cheoncheonhi",en:"slowly",pos:"adverb",chapter:"1·10·24",ex:{ko:"천천히 말해 주세요.",en:"Please speak slowly.",note:"One of the most useful phrases for a beginner — you will say this constantly in your first weeks of Korean"},collocations:["천천히 말하다","천천히 읽다","천천히 쓰다"],nuance:"천천히 is polite and clear for asking someone to slow down.",explanation:'"slowly" is 천천히 (cheoncheonhi). The word itself is easy; what matters is the company it keeps, like 천천히 말해 주세요 ("Please speak slowly."). Watch the particle attached to 천천히 in each example — that little marker, not the word, tells you whether it is the topic, the subject, the object, or a place. Copy one full sentence about classroom communication, study plans, and asking for repetition or help first, then vary one word.',shortExplanation:'천천히 means "slowly" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Do not pronounce it as English syllables; listen to the Korean rhythm."],conjugationTips:[],usagePhrases:[{ko:"천천히 말해 주세요",romanization:"cheoncheonhi malhae juseyo",en:"Please speak slowly.",note:"Survival."},{ko:"천천히 읽어요",romanization:"cheoncheonhi ilgeoyo",en:"I read slowly.",note:"Action."},{ko:"천천히 가요",romanization:"cheoncheonhi gayo",en:"Go slowly.",note:"Movement."},{ko:"조금 천천히 말해 주세요",romanization:"jogeum cheoncheonhi malhae juseyo",en:"Please speak a little slowly.",note:"Soft request."}],examples:[{ko:"천천히 말해 주세요.",romanization:"cheoncheonhi malhae juseyo.",en:"Please speak slowly.",note:"Learner phrase."},{ko:"조금 천천히 읽어 주세요.",romanization:"jogeum cheoncheonhi ilgeo juseyo.",en:"Please read a little slowly.",note:"Classroom."},{ko:"천천히 가세요.",romanization:"cheoncheonhi gaseyo.",en:"Please go slowly / take care.",note:"Polite."}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[1,10,24]},다시:{ko:"다시",romanization:"dasi",en:"again",pos:"adverb",chapter:"1·10·24",ex:{ko:"다시 들어요.",en:"I listen again.",note:"다시 comes before the verb it modifies — Korean adverbs do not change form"},collocations:["다시 듣다","다시 읽다","다시 말하다"],nuance:"다시 is one of the most useful repair words for learners.",explanation:'다시 (dasi) means "again". Learn it inside a frame, not as a bare word: a useful first chunk is 다시 말해 주세요 ("Please say it again."). In Korean the particle or ending next to 다시 signals its job — topic, subject, object, place, time, method, or description — so read the examples for the small piece beside it. Start with one real sentence about classroom communication, study plans, and asking for repetition or help, then change a single part.',shortExplanation:'다시 means "again" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","다시 means again; 더 means more. They are not always the same."],conjugationTips:[],usagePhrases:[{ko:"다시 말해 주세요",romanization:"dasi malhae juseyo",en:"Please say it again.",note:"Request."},{ko:"다시 들어요",romanization:"dasi deureoyo",en:"Listen again.",note:"Classroom."},{ko:"다시 봐요",romanization:"dasi bwayo",en:"Look again / see again.",note:"Review."},{ko:"다시 할게요",romanization:"dasi halgeyo",en:"I will do it again.",note:"Promise."}],examples:[{ko:"다시 말해 주세요.",romanization:"dasi malhae juseyo.",en:"Please say it again.",note:"Classroom."},{ko:"다시 들어요.",romanization:"dasi deureoyo.",en:"Listen again.",note:"Study."},{ko:"내일 다시 볼까요?",romanization:"naeil dasi bolkkayo?",en:"Shall we look again tomorrow?",note:"Suggestion."}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[1,10,24]},알겠어요:{ko:"알겠어요",romanization:"algesseoyo",en:"I understand / I see / okay",pos:"expression",chapter:"1·10",ex:{ko:"네, 알겠어요.",en:"Yes, I understand.",note:"알겠어요 literally means 'I will know it' (future-inference form of 알다) but functions as 'I get it now' — use it as a fixed phrase"},collocations:["네, 알겠어요","잘 알겠어요","알겠습니다"],nuance:"알겠어요 often means “okay, I got it,” not only intellectual understanding.",explanation:'"I understand / okay." — that is 알겠어요 (algesseoyo). It is a fixed expression you use as a chunk, like 알겠어요 ("I understand / okay."). Match it to the right moment and the right listener; the examples show when it fits and what usually comes next.',shortExplanation:'알겠어요 is a practical expression meaning "I understand / okay.".',commonMistakes:["Do not add another polite ending to a phrase that is already complete.","Use the whole expression in the situation shown by the examples."],conjugationTips:[],usagePhrases:[{ko:"알겠어요",romanization:"algesseoyo",en:"I understand / okay.",note:"Polite."},{ko:"네, 알겠어요",romanization:"ne, algesseoyo",en:"Yes, I understand.",note:"Response."},{ko:"잘 알겠어요",romanization:"jal algesseoyo",en:"I understand well.",note:"Stronger."},{ko:"알겠습니다",romanization:"algetseumnida",en:"I understand.",note:"Formal."}],examples:[{ko:"알겠어요.",romanization:"algesseoyo.",en:"I understand.",note:"Basic."},{ko:"네, 알겠습니다.",romanization:"ne, algetseumnida.",en:"Yes, I understand.",note:"Formal."},{ko:"이제 알겠어요.",romanization:"ije algesseoyo.",en:"Now I understand.",note:"Learning."}],forms:null,irregular:null,level:"A1",cluster:{title:"알겠어요 vs 알았어요",rule:"Both mean 'okay, got it', but 알겠어요 is the safe one for accepting instructions from anyone. 알았어요 is the same okay with a shrug — with the wrong tone it lands as 'yeah, yeah, I know', so save it for people you're close to.",members:[{ko:"알겠어요",en:"I understand / okay.",romanization:"algesseoyo",when:"accepting instructions, any listener",hint:"the polite, safe 'got it'",example:{ko:"네, 알겠어요.",en:"Okay, got it."},self:!0},{ko:"알았어요",en:"Okay / I got it / fine — you heard and registered it, but the tone can read as curt.",romanization:"arasseoyo",when:"close friends, casual agreement",hint:"casual 'okay' that can sound impatient",example:{ko:"알았어요, 이따가 전화할게요.",en:"Okay, I'll call you later."},self:!1}]},chapters:[1,10]},모르겠어요:{ko:"모르겠어요",romanization:"moreugesseoyo",en:"I don't know / I'm not sure",pos:"expression",chapter:"1",ex:{ko:"이 글자 모르겠어요.",en:"I don't know this character.",note:"The counterpart to 알겠어요 — equally important to have in your first lesson vocabulary"},collocations:["잘 모르겠어요","아직 모르겠어요"],nuance:"모르다 is the antonym of 알다 'to know', and the -겠- before the polite -어요 ending softens the assertion into 'I can't seem to tell / I'm not certain' rather than a blunt fact. This makes 모르겠어요 notably more humble and polite than 몰라요 — which, without -겠-, can sound curt or even dismissive, like 'I don't know and that's that'. Use 모르겠어요 with customers, teachers, seniors, or anyone you're being careful with; 몰라요 is fine between close friends. Adding 잘 (잘 모르겠어요) counterintuitively intensifies the not-knowing — it does NOT mean 'I know well'; in negative verbs, 잘 boosts the negative, meaning 'I really have no idea'. The -ㄴ지/-ㄹ지 construction embeds questions inside 모르겠어요: 어디인지 모르겠어요, 맞는지 모르겠어요, 언제 오실지 모르겠어요 — this pattern is essential for natural speech. Compare 안 알아요: Korean does not negate 알다 with 안; the dedicated negative is 모르다, making 안 알아요 wrong for 'I don't know'.",explanation:`모르겠어요 (moreugesseoyo) means "I do not know". Say it as one set phrase — for example 모르겠어요 ("I'm not sure"). What matters is the situation and how polite it sounds, so copy it whole from the examples instead of translating word by word.`,shortExplanation:'모르겠어요 is a practical expression meaning "I do not know".',commonMistakes:["Do not add another polite ending to a phrase that is already complete.","Use the whole expression in the situation shown by the examples.",["Reading 잘 모르겠어요 as 'I know it well'.","잘 here intensifies the negative verb, so it means 'I really don't know', the opposite of what 잘 ('well') suggests in English."],["Defaulting to 몰라요 with strangers or superiors.","몰라요 sounds blunt, even cold; the -겠- in 모르겠어요 adds politeness and humility, which is safer in service or formal settings."],["Saying 안 알아요 for 'I don't know'.","Korean does not negate 알다 with 안; the dedicated antonym verb is 모르다. Use 몰라요 / 모르겠어요, never 안 알아요."]],conjugationTips:[],usagePhrases:[{ko:"모르겠어요",romanization:"moreugesseoyo",en:"I'm not sure",note:"Polite, softened 'I don't know'"},{ko:"잘 모르겠어요",romanization:"jal moreugesseoyo",en:"I really don't know",note:"잘 makes it humbler, not 'know well'"},{ko:"아직 모르겠어요",romanization:"ajing moreugesseoyo",en:"I don't know yet",note:"Decision still pending"},{ko:"왜 그런지 모르겠어요",romanization:"wae geureonji moreugesseoyo",en:"I don't know why",note:"-ㄴ지 embeds the question"}],examples:[{ko:"글쎄요, 잘 모르겠어요.",romanization:"geulsseyo, jal moreugesseoyo.",en:"Hmm, I'm really not sure.",note:"글쎄요 is the standard hesitation cushion before admitting uncertainty — together with 잘 모르겠어요 it sounds humble, not evasive."},{ko:"A: 이 서류 어떻게 작성해요? / B: 저도 잘 모르겠어요. 담당자한테 물어보세요.",romanization:"A: i seoryu eotteoke jakseonghaeyo? / B: jeodo jal moreugesseoyo. damdangjahante mureoboseyo.",en:"A: How do I fill out this form? / B: I'm not sure either. Try asking the person in charge.",note:"Workplace A/B: B's 저도 ('me too / I also') keeps the tone collaborative rather than dismissive; 담당자 = person in charge."},{ko:"언제 끝날지 아직 모르겠어요.",romanization:"eonje kkeunnalji ajing moreugesseoyo.",en:"I still don't know when it'll finish.",note:"-ㄹ지 embeds the unknown future fact inside 모르겠어요, showing the EMBEDDED QUESTION structure essential for real speech."}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[1]},안녕하세요:{ko:"안녕하세요",romanization:"annyeonghaseyo",en:"Hello / Hi (polite)",pos:"expression",chapter:"2",ex:{ko:"안녕하세요. 저는 지수예요.",en:"Hello. I am Jisu.",note:"안녕하세요 is always the opener; then your name introduction follows naturally."},collocations:["안녕하세요, 처음 뵙겠습니다","선생님, 안녕하세요","안녕하세요! (in person and text)"],nuance:"안녕하세요 is the all-purpose 존댓말 greeting for strangers, coworkers, shopkeepers, teachers — basically any adult you are not on 반말 terms with. The root 안녕(安寧) means 'peace/well-being', so the phrase literally asks 'are you at peace?', but modern Koreans hear it simply as 'hello'; it works morning, noon, and night since Korean has no separate 'good morning/afternoon/evening' equivalents. The register ladder runs: 안녕 (반말, close friends / children / clear juniors) → 안녕하세요 (standard polite) → 안녕하십니까 (격식체, formal broadcasts and service settings). A key social rule: saying 안녕 to a teacher, boss, or older stranger signals either extreme intimacy or disrespect — always default to 안녕하세요 until 반말 is mutually established. The classic English-speaker trap is splitting greetings by time of day or tacking on 어떻게 지내세요? every time — in Korean, 안녕하세요 alone is the complete, natural hello, and opening with a wellbeing question to a stranger sounds oddly probing.",explanation:'안녕하세요 (annyeonghaseyo) = "Hello. / Hi.". Treat it as a ready-made line rather than separate words: 안녕하세요 ("hello (polite)"). Learn the situation it belongs to, and notice the reply it tends to invite.',shortExplanation:'안녕하세요 is a practical expression meaning "Hello. / Hi.".',commonMistakes:["Do not add another polite ending to a phrase that is already complete.","Use the whole expression in the situation shown by the examples.","Saying 안녕 to a teacher, boss, or older stranger — that is 반말 and sounds rude/childish; use 안녕하세요 with anyone you owe respect.","Searching for a 'good morning / good evening' equivalent — Korean uses one 안녕하세요 all day; time-of-day greetings are not standard.","Writing or saying 안녕하새요 — the verb ending is 세요 (하 + 세요), never 새요."],conjugationTips:[],usagePhrases:[{ko:"안녕하세요",romanization:"annyeonghaseyo",en:"hello (polite)",note:"the default greeting to almost anyone you meet"},{ko:"안녕",romanization:"annyeong",en:"hi / hey",note:"반말, to a close friend, a child, or someone clearly younger"},{ko:"안녕하십니까",romanization:"annyeonghasimnikka",en:"hello (formal)",note:"격식체; soldiers, announcers, staff to customers, formal speeches"},{ko:"안녕하세요, 잘 지내셨어요?",romanization:"annyeonghaseyo, jal jinaesyeosseoyo?",en:"hello, have you been well?",note:"natural extension when greeting someone you know"}],examples:[{ko:"A: 안녕하세요! / B: 네, 안녕하세요.",romanization:"A: annyeonghaseyo! / B: ne, annyeonghaseyo.",en:"A: Hello! / B: Yes, hello.",note:"the bare greeting returned with the same words — no extra 'how are you?' needed"},{ko:"안녕하세요, 처음 뵙겠습니다.",romanization:"annyeonghaseyo, cheoeum boepgetseumnida.",en:"Hello, nice to meet you (first time).",note:"everyday: chaining the greeting into a first introduction"},{ko:"(가게에 들어가며) 안녕하세요~ 사장님 계세요?",romanization:"(gagee deureogamyeo) annyeonghaseyo~ sajangnim gyeseyo?",en:"(walking into a shop) Hello~ is the owner in?",note:"real situation: 안녕하세요 doubles as 'excuse me' to get attention in a shop"}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[2]},"안녕히 계세요":{ko:"안녕히 계세요",romanization:"annyeonghi gyeseyo",en:"Goodbye (said by the one leaving)",pos:"expression",chapter:"2",ex:{ko:"제가 먼저 갈게요. 안녕히 계세요!",en:"I'll go first. Goodbye!",note:"Say 안녕히 계세요 when you are leaving and the other person is staying. Say 안녕히 가세요 to someone who is leaving."},collocations:["제가 먼저 갈게요. 안녕히 계세요","안녕히 가세요","또 만나요"],nuance:"안녕히 계세요 is the mirror image of 안녕히 가세요: you say it when YOU are the one leaving and the other person STAYS. The pivot is the verb — 계시다 is the honorific of 있다 'to be/remain (of a person)', so 계세요 wishes the one staying to 'remain in peace'. Both phrases share the same 안녕(安寧) 'peace' root; the verb alone signals direction. English speakers reliably swap the two because 'goodbye' has no who-moves information — the one-second fix is: if my feet are moving, use 계세요; if their feet are moving, use 가세요. A smooth social move before departing is to add 먼저 갈게요 or 먼저 가 볼게요 ('I'll head off first') so leaving ahead of others doesn't seem abrupt or rude. When leaving a workplace where colleagues are still working, pairing 안녕히 계세요 with 수고하세요 ('keep up the good work') is the natural and considerate exit. Formal register: 안녕히 계십시오.",explanation:'"Goodbye (said by the person who is leaving)." — that is 안녕히 계세요 (annyeonghi gyeseyo). It is a fixed expression you use as a chunk, like 안녕히 계세요 ("goodbye, stay in peace"). Match it to the right moment and the right listener; the examples show when it fits and what usually comes next.',shortExplanation:'안녕히 계세요 is a practical expression meaning "Goodbye (said by the person who is leaving).".',commonMistakes:["Do not add another polite ending to a phrase that is already complete.","Use the whole expression in the situation shown by the examples.","Using 안녕히 가세요 as you walk out the door — that orders the people staying to leave; the person departing always says 안녕히 계세요.","Saying 안녕히 있으세요 with plain 있다 — to show respect for a person staying, you must use the honorific verb 계시다, so it is always 안녕히 계세요, never 안녕히 있으세요.","Bolting without a word in a group setting — add 먼저 갈게요 / 먼저 가 보겠습니다 before 안녕히 계세요 so leaving first feels considerate, not abrupt."],conjugationTips:[],usagePhrases:[{ko:"안녕히 계세요",romanization:"annyeonghi gyeseyo",en:"goodbye, stay in peace",note:"you leave, they stay — mirror image of 가세요"},{ko:"안녕히 계십시오",romanization:"annyeonghi gyesipsio",en:"goodbye, stay well (very formal)",note:"departing a formal setting such as an office or ceremony"},{ko:"먼저 가 볼게요",romanization:"meonjeo ga bolgeyo",en:"I'll head off first",note:"softening phrase added before 안녕히 계세요 so leaving early reads polite"},{ko:"안녕히 계세요, 수고하세요",romanization:"annyeonghi gyeseyo, sugohaseyo",en:"bye, keep up the good work",note:"natural dual exit line when leaving a still-working colleague"}],examples:[{ko:"A: 먼저 가겠습니다. 안녕히 계세요. / B: 네, 안녕히 가세요.",romanization:"A: meonjeo gagetseumnida. annyeonghi gyeseyo. / B: ne, annyeonghi gaseyo.",en:"A: I'll be heading off now. Goodbye (stay well). / B: Take care, goodbye.",note:"A is leaving and says 안녕히 계세요 to B; B stays and returns 안녕히 가세요 — each uses the correct directional verb"},{ko:"저 먼저 갈게요. 안녕히 계세요.",romanization:"jeo meonjeo galgeyo. annyeonghi gyeseyo.",en:"I'm off first. Take care and stay well.",note:"you depart while others stay; 먼저 갈게요 flags you are the first to leave"},{ko:"바쁘신데 시간 내 주셔서 감사합니다. 안녕히 계세요.",romanization:"bappeusinde sigan nae jusyeoseo gamsahamnida. annyeonghi gyeseyo.",en:"Thank you for making time despite being busy. Goodbye.",note:"polite close of a meeting — you leave, your host remains"}],forms:null,irregular:null,level:"A1",cluster:{title:"안녕히 가세요 vs 안녕히 계세요",rule:"Ask one question: who is walking away? Say 안녕히 가세요 to the person who leaves, and 안녕히 계세요 if you are the one leaving — so 안녕히 계세요 is what you say on your way out of a shop or someone's home.",members:[{ko:"안녕히 가세요",en:"Goodbye (to someone who is leaving).",romanization:"annyeonghi gaseyo",when:"the other person walks away",hint:"what you say to the person leaving",example:{ko:"안녕히 가세요. 내일 봐요.",en:"Goodbye. See you tomorrow."},self:!1},{ko:"안녕히 계세요",en:"Goodbye (said by the person who is leaving).",romanization:"annyeonghi gyeseyo",when:"you leave, they stay",hint:"your goodbye as you walk out",example:{ko:"저 먼저 갈게요. 안녕히 계세요.",en:"I'm heading off. Goodbye."},self:!0}]},chapters:[2]},감사합니다:{ko:"감사합니다",romanization:"gamsahamnida",en:"Thank you (formal)",pos:"expression",chapter:"2",ex:{ko:"도와주셔서 감사합니다.",en:"Thank you for helping me.",note:"감사합니다 is the safer, more formal option — use it with strangers, in shops, and in any formal setting."},collocations:["정말 감사합니다","도와주셔서 감사합니다","감사합니다 vs 고마워요"],nuance:"감사합니다 is the default 존댓말 'thank you' safe with literally anyone — a stranger, a clerk, a teacher, your boss — and never wrong. It comes from Sino-Korean 감사(感謝), giving it a slightly formal, composed feel compared to the warmer native alternative 고맙습니다. The formality ladder runs: 고마워 (반말, friends/juniors) → 고마워요 (gentle polite) → 감사합니다 (standard polite) → 대단히 감사합니다 / 감사드립니다 (격식, speeches, written). The nearest alternative is 고맙습니다, which is pure native Korean and sounds a touch warmer and more personal; both are equally polite, and the choice is mostly about tone rather than rank. The classic English-speaker error is stacking a noun directly: you cannot say '도움 감사합니다' as if words simply pile up — to thank for an action you must attach ~아/어 주셔서 (도와주셔서 감사합니다). Another mistake is using 고마워 with strangers or anyone older, which sounds presumptuous and rude.",explanation:'"Thank you." — that is 감사합니다 (gamsahamnida). It is a fixed expression you use as a chunk, like 감사합니다 ("thank you (formal-polite)"). Match it to the right moment and the right listener; the examples show when it fits and what usually comes next.',shortExplanation:'감사합니다 is a practical expression meaning "Thank you.".',commonMistakes:["Do not add another polite ending to a phrase that is already complete.","Use the whole expression in the situation shown by the examples.","Saying 고마워 to a stranger, clerk, or anyone older — that is 반말 and sounds rude; default to 감사합니다 or at least 고마워요.","Trying to thank for an action by just naming it ('도와 감사합니다') — Korean needs ~아/어 주셔서: 도와주셔서 감사합니다.","Writing 감사 합니다 with a space — 감사합니다 is one word; the space is wrong."],conjugationTips:[],usagePhrases:[{ko:"감사합니다",romanization:"gamsahamnida",en:"thank you (formal-polite)",note:"the all-purpose 존댓말 thanks to anyone"},{ko:"고마워",romanization:"gomawo",en:"thanks / thank you",note:"반말, to a close friend or someone younger"},{ko:"대단히 감사합니다",romanization:"daedanhi gamsahamnida",en:"thank you very much (formal)",note:"격식, public, written, or to a customer"},{ko:"정말 감사합니다",romanization:"jeongmal gamsahamnida",en:"thank you so much",note:"natural extension adding warmth"}],examples:[{ko:"감사합니다.",romanization:"gamsahamnida.",en:"Thank you.",note:"the bare safe thanks you can say to anyone in any situation"},{ko:"도와주셔서 감사합니다.",romanization:"dowajusyeoseo gamsahamnida.",en:"Thank you for helping me.",note:"attach ~아/어 주셔서 before 감사합니다 to thank for a specific action"},{ko:"A: 바쁘신데 시간 내 주셔서 정말 감사합니다. / B: 별말씀을요, 당연히 해야죠.",romanization:"A: bappeusinde sigan nae jusyeoseo jeongmal gamsahamnida. / B: byeolmalsseumeuryo, dangyeonhi haeyajyo.",en:"A: Thank you so much for making time despite being so busy. / B: Not at all, of course I would.",note:"full polite exchange after someone goes out of their way; note the humble reply 별말씀을요"}],forms:null,irregular:null,level:"A1",cluster:{title:"감사합니다 vs 고맙습니다 vs 고마워요",rule:"감사합니다 and 고맙습니다 are equally polite and swappable — 감사합니다 is what you hear most in shops and at work, 고맙습니다 sounds a little warmer and more personal. 고마워요 is the softer 요-form for people you already know, not for a boss or a customer.",members:[{ko:"감사합니다",en:"Thank you.",romanization:"gamsahamnida",when:"anyone, any polite situation",hint:"the never-wrong default thank you",example:{ko:"도와주셔서 감사합니다.",en:"Thank you for helping me."},self:!0},{ko:"고맙습니다",en:"Thank you.",romanization:"gomapseumnida",when:"polite, warmer and more personal",hint:"just as polite, a touch warmer",example:{ko:"정말 고맙습니다.",en:"Thank you very much."},self:!1},{ko:"고마워요",en:"Thank you.",romanization:"gomawoyo",when:"friends, familiar people",hint:"the softer 요-form for people you know",example:{ko:"선물 고마워요.",en:"Thanks for the present."},self:!1}]},chapters:[2]},고마워요:{ko:"고마워요",romanization:"gomawoyo",en:"Thank you (warm/friendly)",pos:"expression",chapter:"2",ex:{ko:"선물이에요? 정말 고마워요!",en:"It's a gift? Thank you so much!",note:"고마워요 is warmer and more personal than 감사합니다 — great for friends and classmates."},collocations:["정말 고마워요","오늘 고마워요","고마워 (casual, drop -요)"],nuance:"Polite enough for many situations, but 감사합니다 is safer in formal service or business contexts.",explanation:'고마워요 (gomawoyo) = "Thank you.". Treat it as a ready-made line rather than separate words: 고마워요 ("Thank you."). Learn the situation it belongs to, and notice the reply it tends to invite.',shortExplanation:'고마워요 is a practical expression meaning "Thank you.".',commonMistakes:["Do not add another polite ending to a phrase that is already complete.","Use the whole expression in the situation shown by the examples."],conjugationTips:[],usagePhrases:[{ko:"고마워요",romanization:"gomawoyo",en:"Thank you.",note:"Polite but warm."},{ko:"정말 고마워요",romanization:"jeongmal gomawoyo",en:"Thank you so much.",note:"Warm thanks."},{ko:"도와줘서 고마워요",romanization:"dowajwoseo gomawoyo",en:"Thanks for helping.",note:"Friendly."},{ko:"오늘 고마워요",romanization:"oneul gomawoyo",en:"Thanks for today.",note:"Natural close."}],examples:[{ko:"고마워요.",romanization:"gomawoyo.",en:"Thank you.",note:"Polite."},{ko:"정말 고마워요.",romanization:"jeongmal gomawoyo.",en:"Thank you so much.",note:"Warm."},{ko:"도와줘서 고마워요.",romanization:"dowajwoseo gomawoyo.",en:"Thanks for helping.",note:"Friendly."}],forms:null,irregular:null,level:"A1",cluster:{title:"감사합니다 vs 고맙습니다 vs 고마워요",rule:"감사합니다 and 고맙습니다 are equally polite and swappable — 감사합니다 is what you hear most in shops and at work, 고맙습니다 sounds a little warmer and more personal. 고마워요 is the softer 요-form for people you already know, not for a boss or a customer.",members:[{ko:"감사합니다",en:"Thank you.",romanization:"gamsahamnida",when:"anyone, any polite situation",hint:"the never-wrong default thank you",example:{ko:"도와주셔서 감사합니다.",en:"Thank you for helping me."},self:!1},{ko:"고맙습니다",en:"Thank you.",romanization:"gomapseumnida",when:"polite, warmer and more personal",hint:"just as polite, a touch warmer",example:{ko:"정말 고맙습니다.",en:"Thank you very much."},self:!1},{ko:"고마워요",en:"Thank you.",romanization:"gomawoyo",when:"friends, familiar people",hint:"the softer 요-form for people you know",example:{ko:"선물 고마워요.",en:"Thanks for the present."},self:!0}]},chapters:[2]},죄송합니다:{ko:"죄송합니다",romanization:"joesonghamnida",en:"I'm sorry / I apologize (formal)",pos:"expression",chapter:"2",ex:{ko:"늦어서 죄송합니다.",en:"I'm sorry for being late.",note:"죄송합니다 is the formal apology — use it when you've genuinely caused trouble or in professional/service situations."},collocations:["정말 죄송합니다","늦어서 죄송해요","죄송한데요 (softer)"],nuance:"죄송합니다 is the higher-deference 'I'm sorry', from Sino-Korean 죄송(罪悚), literally 'I feel I have committed a fault and am fearful before you'. That deferential weight makes it the correct apology toward strangers, seniors, customers, and your boss — situations where showing you lower yourself is required. The formality ladder: 미안해 (반말, peers/friends) → 미안해요 (gentle polite) → 죄송해요 / 죄송합니다 (polite, upward-safe) → 대단히 죄송합니다 / 죄송스럽습니다 (격식, serious fault). The dividing line versus 미안하다 is deference: 죄송하다 lowers yourself and is always safe upward; 미안하다 is more horizontal and personal, and sounds too casual to a boss. Three concrete English-speaker mistakes: (1) attaching the reason wrong — use X-아/어서 죄송합니다 (늦어서 죄송합니다), not '늦은 것 죄송'; (2) using 미안해 to a boss or stranger; (3) confusing it with 실례합니다, which is 'excuse me' for a small intrusion, not an apology for fault.",explanation:`죄송합니다 (joesonghamnida) = "I'm sorry. / I apologize.". Treat it as a ready-made line rather than separate words: 죄송합니다 ("I'm sorry (formal-polite)"). Learn the situation it belongs to, and notice the reply it tends to invite.`,shortExplanation:`죄송합니다 is a practical expression meaning "I'm sorry. / I apologize.".`,commonMistakes:["Do not add another polite ending to a phrase that is already complete.","Use the whole expression in the situation shown by the examples.","Saying 미안해 to a boss, teacher, or stranger — that is 반말; use 죄송합니다 (or at least 미안해요) for a real apology upward.","Forming the reason wrong, e.g. '늦은 거 죄송' — use the ~아/어서 connector: 늦어서 죄송합니다.","Swapping in 실례합니다 to apologize for a real mistake — 실례합니다 is 'excuse me' for a minor intrusion, not an apology for fault."],conjugationTips:[],usagePhrases:[{ko:"죄송합니다",romanization:"joesonghamnida",en:"I'm sorry (formal-polite)",note:"the safe 존댓말 apology to anyone, esp. seniors/strangers"},{ko:"미안해",romanization:"mianhae",en:"sorry",note:"반말, to a friend or someone younger/closer"},{ko:"대단히 죄송합니다",romanization:"daedanhi joesonghamnida",en:"I deeply apologize (formal)",note:"격식, serious fault, customer/public setting"},{ko:"정말 죄송합니다",romanization:"jeongmal joesonghamnida",en:"I'm so sorry",note:"natural extension adding sincerity"}],examples:[{ko:"죄송합니다.",romanization:"joesonghamnida.",en:"I'm sorry.",note:"the bare polite apology, safe with anyone you don't know well"},{ko:"늦어서 죄송합니다.",romanization:"neujeoseo joesonghamnida.",en:"I'm sorry I'm late.",note:"reason + 아/어서 + 죄송합니다; the standard structure for apologizing for a cause"},{ko:"A: 제 실수로 불편을 드렸습니다. 정말 죄송합니다. / B: 아니에요, 괜찮아요.",romanization:"A: je silsuro bulpyeoneul deuryeotseumnida. jeongmal joesonghamnida. / B: anieyo, gwaenchanayo.",en:"A: I caused inconvenience because of my mistake. I'm truly sorry. / B: No, it's all right.",note:"formal exchange owning the fault clearly; notice how 불편을 드리다 (cause inconvenience upward) pairs naturally"}],forms:null,irregular:null,level:"A1",cluster:{title:"미안해요 vs 죄송해요 vs 죄송합니다",rule:"Pick by who you are apologizing to: 미안해요 for friends, peers and people younger than you; 죄송해요/죄송합니다 for strangers, seniors, customers and your boss. Between those two, 죄송해요 is softer and everyday, 죄송합니다 is the formal one you use at work or when the mistake is serious.",members:[{ko:"미안해요",en:"I'm sorry.",romanization:"mianhaeyo",when:"friends, peers, younger people",hint:"for people close to you or below you",example:{ko:"늦어서 미안해요.",en:"Sorry I'm late."},self:!1},{ko:"죄송해요",en:"I'm sorry — the everyday spoken polite apology, softer than 죄송합니다 and more deferential than 미안해요.",romanization:"joesonghaeyo",when:"polite everyday apology, softer",hint:"the gentler polite apology to strangers",example:{ko:"기다리게 해서 죄송해요.",en:"I'm sorry to keep you waiting."},self:!1},{ko:"죄송합니다",en:"I'm sorry. / I apologize.",romanization:"joesonghamnida",when:"boss, customers, serious apologies",hint:"the safest, most formal apology",example:{ko:"늦어서 정말 죄송합니다.",en:"I'm truly sorry for being late."},self:!0}]},chapters:[2]},미안해요:{ko:"미안해요",romanization:"mianhaeyo",en:"I'm sorry (friendly)",pos:"expression",chapter:"2",ex:{ko:"미안해요, 늦었어요.",en:"Sorry, I'm late.",note:"미안해요 is the everyday polite apology — less heavy than 죄송합니다, appropriate for friends and classmates."},collocations:["미안해요","정말 미안해요","미안해 (casual)"],nuance:"미안해요/미안하다 is the warmer, more horizontal 'sorry' — used downward or sideways: to friends, peers, your kids, or people close in age and rank. From Sino-Korean 미안(未安), literally 'not at ease (in my heart)', it expresses personal guilt rather than formal deference. The register ladder: 미안해 (반말) → 미안해요 (gently polite) → 미안합니다 (firmer polite) → 죄송합니다 (deferential, upward/격식). The key dividing line versus 죄송하다 is deference: 미안하다 does NOT lower you toward the listener, so it can feel too casual or even presumptuous with a boss or customer — for those situations always choose 죄송합니다. English speakers wrongly treat 미안해요 and 죄송합니다 as interchangeable 'sorry'; using 미안해요 to your boss sounds insufficiently deferential, while using 죄송합니다 to a close friend sounds coldly distant. Also: the small 'sorry, excuse me' to squeeze past a stranger on the street is NOT 미안해요 but 실례합니다 / 잠시만요.",explanation:`미안해요 (mianhaeyo) means "I'm sorry.". Say it as one set phrase — for example 미안해요 ("I'm sorry (gently polite)"). What matters is the situation and how polite it sounds, so copy it whole from the examples instead of translating word by word.`,shortExplanation:`미안해요 is a practical expression meaning "I'm sorry.".`,commonMistakes:["Do not add another polite ending to a phrase that is already complete.","Use the whole expression in the situation shown by the examples.","Using 미안해요 to a boss, customer, or elder for a real fault — it isn't deferential enough; say 죄송합니다.","Using 미안하다 to brush past someone in a crowd — Koreans say 실례합니다 or 잠시만요, not 미안해요, for that.","Saying 미안해 to someone you've just met — too familiar; with strangers use 미안합니다/죄송합니다."],conjugationTips:[],usagePhrases:[{ko:"미안해요",romanization:"mianhaeyo",en:"I'm sorry (gently polite)",note:"존댓말 to a peer or familiar adult; warm, personal"},{ko:"미안해",romanization:"mianhae",en:"sorry",note:"반말, to a friend or someone younger/closer"},{ko:"미안합니다",romanization:"mianhamnida",en:"I'm sorry (formal-polite)",note:"격식-leaning polite, neutral and a bit firmer"},{ko:"정말 미안해",romanization:"jeongmal mianhae",en:"I'm really sorry",note:"natural extension adding sincerity in 반말"}],examples:[{ko:"미안해요.",romanization:"mianhaeyo.",en:"I'm sorry.",note:"a soft, personal polite apology to someone familiar or at peer level"},{ko:"연락 늦어서 미안해.",romanization:"yeollang neujeoseo mianhae.",en:"Sorry for the late reply.",note:"everyday 반말 apology with ~아/어서 to a friend; note 연락 (contact) + 늦어서"},{ko:"A: 약속을 못 지켰네. 정말 미안해. / B: 아니야, 괜찮아. 다음에 보면 되지.",romanization:"A: yaksogeul mot jikyeonne. jeongmal mianhae. / B: aniya, gwaenchana. daeume bomyeon doeji.",en:"A: I couldn't keep my promise. I'm really sorry. / B: No, it's fine. We'll see each other next time.",note:"반말 exchange showing authentic apology and warm reassurance between friends"}],forms:null,irregular:null,level:"A1",cluster:{title:"미안해요 vs 죄송해요 vs 죄송합니다",rule:"Pick by who you are apologizing to: 미안해요 for friends, peers and people younger than you; 죄송해요/죄송합니다 for strangers, seniors, customers and your boss. Between those two, 죄송해요 is softer and everyday, 죄송합니다 is the formal one you use at work or when the mistake is serious.",members:[{ko:"미안해요",en:"I'm sorry.",romanization:"mianhaeyo",when:"friends, peers, younger people",hint:"for people close to you or below you",example:{ko:"늦어서 미안해요.",en:"Sorry I'm late."},self:!0},{ko:"죄송해요",en:"I'm sorry — the everyday spoken polite apology, softer than 죄송합니다 and more deferential than 미안해요.",romanization:"joesonghaeyo",when:"polite everyday apology, softer",hint:"the gentler polite apology to strangers",example:{ko:"기다리게 해서 죄송해요.",en:"I'm sorry to keep you waiting."},self:!1},{ko:"죄송합니다",en:"I'm sorry. / I apologize.",romanization:"joesonghamnida",when:"boss, customers, serious apologies",hint:"the safest, most formal apology",example:{ko:"늦어서 정말 죄송합니다.",en:"I'm truly sorry for being late."},self:!1}]},chapters:[2]},네:{ko:"네",romanization:"ne",en:"Yes / I see / okay",pos:"expression",chapter:"2",ex:{ko:"네, 알겠어요.",en:"Yes, I understand.",note:"네 doesn't only mean 'yes' — it's also used as a listening signal ('I hear you') while someone is talking."},collocations:["네, 맞아요","네, 알겠어요","네, 괜찮아요"],nuance:"네 can also mean “I hear you” or “okay” while listening, not only yes.",explanation:'네 (ne) = "Yes.". Treat it as a ready-made line rather than separate words: 네 ("Yes."). Learn the situation it belongs to, and notice the reply it tends to invite.',shortExplanation:'네 is a practical expression meaning "Yes.".',commonMistakes:["Do not add another polite ending to a phrase that is already complete.","Use the whole expression in the situation shown by the examples."],conjugationTips:[],usagePhrases:[{ko:"네",romanization:"ne",en:"Yes.",note:"Polite yes."},{ko:"네, 맞아요",romanization:"ne, majayo",en:"Yes, that is right.",note:"Agreement."},{ko:"네, 알겠어요",romanization:"ne, algesseoyo",en:"Yes, I understand.",note:"Acknowledgment."},{ko:"네, 괜찮아요",romanization:"ne, gwaenchanayo",en:"Yes, it is okay.",note:"Reassurance."}],examples:[{ko:"네.",romanization:"ne.",en:"Yes.",note:"Basic."},{ko:"네, 맞아요.",romanization:"ne, majayo.",en:"Yes, that is right.",note:"Agreement."},{ko:"네, 알겠습니다.",romanization:"ne, algetseumnida.",en:"Yes, I understand.",note:"Formal."}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[2]},아니요:{ko:"아니요",romanization:"aniyo",en:"No (polite)",pos:"expression",chapter:"2",ex:{ko:"아니요, 저는 학생이 아니에요.",en:"No, I'm not a student.",note:"아니요 is the polite 'no' — always softer when followed by a short explanation like 괜찮아요 or 몰라요."},collocations:["아니요, 괜찮아요","아니요, 몰라요","아니요, 저는 ___이 아니에요"],nuance:"Use 아니요 as a polite no. 아니 is casual, and 아니요 often sounds softer when followed by a short explanation like 괜찮아요 or 몰라요.",explanation:'아니요 (aniyo) means "No.". Say it as one set phrase — for example 아니요 ("No."). What matters is the situation and how polite it sounds, so copy it whole from the examples instead of translating word by word.',shortExplanation:'아니요 is a practical expression meaning "No.".',commonMistakes:["Do not add another polite ending to a phrase that is already complete.","Use the whole expression in the situation shown by the examples."],conjugationTips:[],usagePhrases:[{ko:"아니요",romanization:"aniyo",en:"No.",note:"Polite no."},{ko:"아니요, 괜찮아요",romanization:"aniyo, gwaenchanayo",en:"No, it is okay.",note:"Declining politely."},{ko:"아니요, 몰라요",romanization:"aniyo, mollayo",en:"No, I do not know.",note:"Answer."},{ko:"아니요, 안 가요",romanization:"aniyo, an gayo",en:"No, I am not going.",note:"Negative answer."}],examples:[{ko:"아니요.",romanization:"aniyo.",en:"No.",note:"Basic."},{ko:"아니요, 괜찮아요.",romanization:"aniyo, gwaenchanayo.",en:"No, it is okay.",note:"Polite decline."},{ko:"아니요, 저는 안 가요.",romanization:"aniyo, jeoneun an gayo.",en:"No, I am not going.",note:"Clarifying."}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[2]},"만나서 반가워요":{ko:"만나서 반가워요",romanization:"mannaseo bangawoyo",en:"Nice to meet you",pos:"expression",chapter:"2",ex:{ko:"저는 민준이에요. 만나서 반가워요!",en:"I'm Minjun. Nice to meet you!",note:"This is the standard 'nice to meet you' — said after exchanging names for the first time."},collocations:["만나서 반갑습니다 (formal)","처음 뵙겠습니다 (very formal first meeting)","반가워요"],nuance:"만나서 반가워요 = 만나서 ('upon meeting / because we've met', from 만나다+ the causal connector -아서) + 반가워요 (반갑다 'to be glad/delighted'). So it literally says 'I am glad because I have met you' — the emotion 반가움 is the point, not just a social formula. Note the grammar: 반갑다 is a ㅂ-irregular adjective, so before -아/어요 the ㅂ drops and becomes 우, giving 반가워요 (not 반갑어요) — the same shift as 춥다→추워요, 돕다→도와요. Register-wise, 반가워요 is warmly friendly; 반갑습니다 is buttoned-up formal for business and ceremonies; the humble 만나 뵙게 되어 반갑습니다 is reserved for high-respect encounters. A crucial situation note: 만나서 반가워요 is essentially a FIRST-MEETING expression. English speakers often reuse 'nice to see you' at subsequent meetings, but at second or third encounters Koreans naturally switch to 오랜만이에요 ('long time no see') or 잘 지냈어요? ('have you been well?'). Reusing the first-meeting phrase can imply you forgot meeting them. The standard reply to 반가워요 is 저도 반가워요.",explanation:'만나서 반가워요 (mannaseo bangawoyo) = "Nice to meet you.". Treat it as a ready-made line rather than separate words: 만나서 반가워요 ("nice to meet you"). Learn the situation it belongs to, and notice the reply it tends to invite.',shortExplanation:'만나서 반가워요 is a practical expression meaning "Nice to meet you.".',commonMistakes:["Do not add another polite ending to a phrase that is already complete.","Use the whole expression in the situation shown by the examples.","Saying 반갑어요 — 반갑다 is ㅂ-irregular; the -어요 form is 반가워요 (ㅂ → 우). Writing or pronouncing 반갑어요 is a clear grammar error.","Re-using 만나서 반가워요 the second time you see the same person — it implies you forgot the first meeting; at reunions use 오랜만이에요 instead.","Replying with a bare 네 to someone's 반가워요 — always mirror warmly with 저도 반가워요 so the introduction doesn't feel one-sided."],conjugationTips:[],usagePhrases:[{ko:"만나서 반가워요",romanization:"mannaseo bangawoyo",en:"nice to meet you",note:"warm, friendly-polite (해요체) — first encounter, any context"},{ko:"만나서 반갑습니다",romanization:"mannaseo bangapseumnida",en:"pleased to meet you (formal)",note:"formal first meeting — business, ceremonies"},{ko:"만나 뵙게 되어 반갑습니다",romanization:"manna boepge doeeo bangapseumnida",en:"honored to meet you",note:"humble-polite; toward a senior or VIP you have long wanted to meet"},{ko:"저도 반가워요",romanization:"jeodo bangawoyo",en:"nice to meet you too",note:"standard echo reply — always mirror the same register"}],examples:[{ko:"A: 안녕하세요, 저는 소연이에요. / B: 만나서 반가워요!",romanization:"A: annyeonghaseyo, jeoneun soyeonieyo. / B: mannaseo bangawoyo!",en:"A: Hello, I'm Soyeon. / B: Nice to meet you!",note:"basic exchange at a first meeting — B reflects A's register"},{ko:"안녕하세요, 만나서 반가워요. 저는 지민이에요. 잘 부탁해요.",romanization:"annyeonghaseyo, mannaseo bangawoyo. jeoneun jiminieyo. jal butakaeyo.",en:"Hello, nice to meet you. I'm Jimin. Looking forward to working together.",note:"greeting plus self-intro — 잘 부탁해요 anchors the relationship going forward"},{ko:"말씀 많이 들었어요. 만나서 정말 반갑습니다.",romanization:"malsseum mani deureosseoyo. mannaseo jeongmal bangapseumnida.",en:"I've heard so much about you. I'm truly pleased to meet you.",note:"formal introduction after someone has been spoken of — 정말 adds genuine warmth; 반갑습니다 lifts the register"}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[2]},잠시만요:{ko:"잠시만요",romanization:"jamsimanyo",en:"One moment, please",pos:"expression",chapter:"2",ex:{ko:"잠시만요, 다시 말씀해 주세요.",en:"One moment, please say that again.",note:"Use 잠시만요 any time you need a pause — at stores, classrooms, or when you haven't heard something clearly."},collocations:["잠시만 기다려 주세요","잠시만요, 확인할게요","잠깐만요 (slightly casual)"],nuance:"More polite than 잠깐만요. Very useful in stores, offices, and classrooms.",explanation:'"One moment, please." — that is 잠시만요 (jamsimanyo). It is a fixed expression you use as a chunk, like 잠시만요 ("One moment, please."). Match it to the right moment and the right listener; the examples show when it fits and what usually comes next.',shortExplanation:'잠시만요 is a practical expression meaning "One moment, please.".',commonMistakes:["Do not add another polite ending to a phrase that is already complete.","Use the whole expression in the situation shown by the examples."],conjugationTips:[],usagePhrases:[{ko:"잠시만요",romanization:"jamsimanyo",en:"One moment, please.",note:"Polite pause."},{ko:"잠시만 기다려 주세요",romanization:"jamsiman gidaryeo juseyo",en:"Please wait a moment.",note:"Request."},{ko:"잠시만요, 지나갈게요",romanization:"jamsimanyo, jinagalgeyo",en:"Excuse me, I will pass.",note:"Moving through."},{ko:"잠시만 확인할게요",romanization:"jamsiman hwaginhalgeyo",en:"I will check for a moment.",note:"Service/work."}],examples:[{ko:"잠시만요.",romanization:"jamsimanyo.",en:"One moment, please.",note:"Basic."},{ko:"잠시만 기다려 주세요.",romanization:"jamsiman gidaryeo juseyo.",en:"Please wait a moment.",note:"Polite request."},{ko:"잠시만 확인할게요.",romanization:"jamsiman hwaginhalgeyo.",en:"I will check for a moment.",note:"Work/service."}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[2]},저:{ko:"저",romanization:"jeo",en:"I / me (polite)",pos:"pronoun",chapter:"2·3",ex:{ko:"저는 마이클이에요.",en:"I am Michael.",note:"저 is the polite first-person pronoun — always use this until you're on casual terms with the other person."},collocations:["저는","저의 / 제 (my)","저도 (me too)"],nuance:"저 is the humble 'I/me,' the polite counterpart of 나. It does not mean something different from 나 — it encodes DEFERENCE, lowering yourself to raise the listener, so it is the correct choice with elders, strangers, customers, and any formal moment, and it sits naturally with 요-form and -ㅂ니다 speech. Like 나 it has an irregular subject form: 저 + 가 fuses to 제가, not '저가.' Two traps for English speakers: first, the homograph — this 저 (I) is spelled identically to the demonstrative 저 'that (over there),' but sentence position keeps them apart; second, the humble plural 저희 ('we/our'), which has no English equivalent and which learners forget, defaulting to plain 우리 even when politely referring to their own company or family. When in doubt about register, 저 is the safer pronoun.",explanation:'"I; me (humble/polite)" is 저 (jeo). The word itself is easy; what matters is the company it keeps, like 저 ("I / me (humble)"). Watch the particle attached to 저 in each example — that little marker, not the word, tells you whether it is the topic, the subject, the object, or a place. Copy one full sentence about basic everyday communication first, then vary one word.',shortExplanation:'저 means "I; me (humble/polite)" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Saying '저가' for the subject — the fused humble form is 제가.","Reaching for casual 나 with strangers, elders, or customers; 저 is the respectful default.","Using plain 우리 where humility is expected — politely lower your own group with 저희 (저희 회사, 저희 집)."],conjugationTips:[],usagePhrases:[{ko:"저",romanization:"jeo",en:"I / me (humble)",note:"Humble first-person pronoun; the safe default with elders, strangers, customers, and in formal settings."},{ko:"제가",romanization:"jega",en:"I (subject)",note:"저 + 가 fuses to 제가, never '저가.' Use it to volunteer or take responsibility politely."},{ko:"저는",romanization:"jeoneun",en:"I / as for me (topic)",note:"저 + 는; the standard opener for introducing yourself: 저는 ...이에요/입니다."},{ko:"저희",romanization:"jeohui",en:"we / our (humble)",note:"humble 'we'; 저희 회사, 저희 집 politely lowers your own group toward the listener."}],examples:[{ko:"저는 학생이에요.",romanization:"jeoneun haksaengieyo.",en:"I am a student.",note:"Simple self-introduction; 저 + 는 paired with the polite 요-form."},{ko:"제가 도와드릴게요.",romanization:"jega dowadeurilgeyo.",en:"I'll help you.",note:"Everyday offer at work: subject 제가 plus the humble 도와드리다 to lift the listener."},{ko:"처음 뵙겠습니다, 저는 김민수입니다.",romanization:"cheoeum boepgetseumnida, jeoneun gimminsuimnida.",en:"Nice to meet you, I'm Kim Minsu.",note:"Real first meeting in 격식체 (formal -ㅂ니다); 저 is obligatory here."}],forms:null,irregular:null,level:"A2",cluster:null,chapters:[2,3]},이름:{ko:"이름",romanization:"ireum",en:"name",pos:"noun",chapter:"2·3",ex:{ko:"이름이 뭐예요?",en:"What is your name?",note:"이름 ends in 'm' (consonant) → 이에요 when you predicate it: 제 이름은 ___이에요."},collocations:["이름이 뭐예요?","제 이름은 ___이에요","이름을 쓰세요"],nuance:"제 이름은 is a safe polite way to introduce your name.",explanation:'"name" is 이름 (ireum). The word itself is easy; what matters is the company it keeps, like 이름이 뭐예요? ("What is your name?"). Watch the particle attached to 이름 in each example — that little marker, not the word, tells you whether it is the topic, the subject, the object, or a place. Copy one full sentence about basic everyday communication first, then vary one word.',shortExplanation:'이름 means "name" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Do not translate “my” as 나의 in normal self-introduction; 제 is natural and polite."],conjugationTips:[],usagePhrases:[{ko:"이름이 뭐예요?",romanization:"ireumi mwoyeyo?",en:"What is your name?",note:"Question."},{ko:"제 이름은 하나예요",romanization:"je ireumeun hanayeyo",en:"My name is Hana.",note:"Topic."},{ko:"이름을 써 주세요",romanization:"ireumeul sseo juseyo",en:"Please write your name.",note:"Object."},{ko:"이름이 있어요",romanization:"ireumi isseoyo",en:"There is a name.",note:"Subject."}],examples:[{ko:"이름이 뭐예요?",romanization:"ireumi mwoyeyo?",en:"What is your name?",note:"Basic question."},{ko:"제 이름은 하나예요.",romanization:"je ireumeun hanayeyo.",en:"My name is Hana.",note:"Self-introduction."},{ko:"여기에 이름을 써 주세요.",romanization:"yeogie ireumeul sseo juseyo.",en:"Please write your name here.",note:"Form."}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[2,3]},학생:{ko:"학생",romanization:"haksaeng",en:"student",pos:"noun",chapter:"2·3·43·46",ex:{ko:"저는 한국어 학생이에요.",en:"I am a Korean language student.",note:"학생 ends in 'ng' (consonant) → 이에요. One of the most-used identity nouns in self-introductions."},collocations:["한국어 학생","대학생 (university student)","학생이에요"],nuance:"학생 is a common identity word. Use 이에요 after 학생 because it ends in a consonant.",explanation:'학생 (haksaeng) means "student". Learn it inside a frame, not as a bare word: a useful first chunk is 학생이에요 ("I am a student."). In Korean the particle or ending next to 학생 signals its job — topic, subject, object, place, time, method, or description — so read the examples for the small piece beside it. Start with one real sentence about classroom communication, study plans, and asking for repetition or help, then change a single part.',shortExplanation:'학생 means "student" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Use 학생이에요, not 학생예요."],conjugationTips:[],usagePhrases:[{ko:"학생이에요",romanization:"haksaengieyo",en:"I am a student.",note:"Identity sentence."},{ko:"저는 학생이에요",romanization:"jeoneun haksaengieyo",en:"I am a student.",note:"Topic marker."},{ko:"학생이 있어요",romanization:"haksaengi isseoyo",en:"There is a student.",note:"Subject/existence."},{ko:"학생하고 공부해요",romanization:"haksaenghago gongbuhaeyo",en:"I study with a student.",note:"With a person."}],examples:[{ko:"저는 학생이에요.",romanization:"jeoneun haksaengieyo.",en:"I am a student.",note:"Self-introduction."},{ko:"학생이 질문해요.",romanization:"haksaengi jilmunhaeyo.",en:"The student asks a question.",note:"Subject."},{ko:"학생하고 같이 공부해요.",romanization:"haksaenghago gachi gongbuhaeyo.",en:"I study together with a student.",note:"Together."}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[2,3,43,46]},선생님:{ko:"선생님",romanization:"seonsaengnim",en:"teacher / instructor",pos:"noun",chapter:"2·3·33·34·42",ex:{ko:"선생님, 안녕하세요!",en:"Hello, teacher!",note:"선생님 is both 'teacher' as a noun and the address form used directly — like calling someone 'Teacher' instead of their name."},collocations:["선생님, 안녕하세요","한국어 선생님","선생님이에요"],nuance:"님 makes the word respectful. 선생님 is also used as a polite title.",explanation:'"teacher" is 선생님 (seonsaengnim). The word itself is easy; what matters is the company it keeps, like 선생님이에요 ("is a teacher."). Watch the particle attached to 선생님 in each example — that little marker, not the word, tells you whether it is the topic, the subject, the object, or a place. Copy one full sentence about classroom communication, study plans, and asking for repetition or help first, then vary one word.',shortExplanation:'선생님 means "teacher" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Do not call a teacher 선생 without 님 in ordinary polite speech."],conjugationTips:[],usagePhrases:[{ko:"선생님이에요",romanization:"seonsaengnimieyo",en:"is a teacher.",note:"Identity."},{ko:"선생님께 물어봐요",romanization:"seonsaengnimkke mureobwayo",en:"I ask the teacher.",note:"Honorific direction."},{ko:"선생님, 안녕하세요",romanization:"seonsaengnim, annyeonghaseyo",en:"Hello, teacher.",note:"Polite address."},{ko:"선생님한테 말해요",romanization:"seonsaengnimhante malhaeyo",en:"I speak to the teacher.",note:"Everyday direction."}],examples:[{ko:"우리 선생님이에요.",romanization:"uri seonsaengnimieyo.",en:"This is our teacher.",note:"Introduction."},{ko:"선생님께 물어봐요.",romanization:"seonsaengnimkke mureobwayo.",en:"I ask the teacher.",note:"Respectful."},{ko:"선생님, 다시 말해 주세요.",romanization:"seonsaengnim, dasi malhae juseyo.",en:"Teacher, please say it again.",note:"Classroom."}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[2,3,33,34,42]},처음:{ko:"처음",romanization:"cheoeum",en:"first time",pos:"noun/adverb",chapter:"2",ex:{ko:"처음 뵙겠습니다.",en:"How do you do. / I'm meeting you for the first time.",note:"처음 뵙겠습니다 is a very formal first-meeting phrase. In everyday language exchange settings, 만나서 반가워요 is more natural."},collocations:["처음 만나요","처음 뵙겠습니다","처음이에요 (it's my first time)"],nuance:"처음 means 'the first time' or 'the beginning', and it flexibly works as both a noun and a time adverb. As a time word it most often appears as 처음에 'at first' — typically to contrast the early state with how things turn out later (처음에는 어려웠어요 'at first it was hard') — or as 처음으로 'for the first time' for a brand-new experience. Its opposite is 마지막 'the last/final'. The sharp contrast to master is 처음 vs 먼저: 처음 is 'the first TIME / the beginning' (a point in time), whereas 먼저 is 'first in ORDER / ahead of others, beforehand' (먼저 가세요 'go ahead first', 먼저 손을 씻으세요 'wash your hands first'). So 'I'll do this first (before that)' is 먼저, but 'I did this for the first time' is 처음. English 'first' blurs both, which is the trap. You'll meet 처음 early in the set greeting 처음 뵙겠습니다. It pairs with 에, 으로, 부터, and 뵙다/오다/먹다.",explanation:'"at first; for the first time" is 처음 (cheoeum). The word itself is easy; what matters is the company it keeps, like 처음에 ("at first, in the beginning"). Watch the particle attached to 처음 in each example — that little marker, not the word, tells you whether it is the topic, the subject, the object, or a place. Copy one full sentence about basic everyday communication first, then vary one word.',shortExplanation:'처음 means "at first; for the first time" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Confusing 처음 (first time / at first) with 먼저 (first in order, beforehand). 'Go ahead first' is 먼저 가세요, NOT ✗ 처음 가세요.","Forgetting 에 when you mean 'at first', e.g. ✗ 처음 어려웠어요 for the contrastive 'at first'. Use 처음에(는) 어려웠어요.","Breaking up the fixed greeting, e.g. ✗ 처음에 뵙겠습니다. It's the set phrase 처음 뵙겠습니다 — learn it whole, no particle."],conjugationTips:[],usagePhrases:[{ko:"처음에",romanization:"cheoeume",en:"at first, in the beginning",note:"With 에 for 'at the start', usually setting up a later contrast."},{ko:"처음으로",romanization:"cheoeumeuro",en:"for the first time",note:"으로 marks the 'firstness' of an experience."},{ko:"처음 뵙겠습니다",romanization:"cheoeum boepgetseumnida",en:"nice to meet you (first meeting)",note:"Fixed formal greeting the very first time you meet someone."},{ko:"처음부터",romanization:"cheoeumbuteo",en:"from the (very) beginning",note:"부터 'from' = right from the start, often 'do it over from scratch'."}],examples:[{ko:"한국에 처음 왔어요.",romanization:"hanguge cheoeum wasseoyo.",en:"I came to Korea for the first time.",note:"Plain first-experience sentence; 처음 right before the verb."},{ko:"처음에는 어려웠는데 지금은 괜찮아요.",romanization:"cheoeumeneun eoryeowonneunde jigeumeun gwaenchanayo.",en:"At first it was hard, but now it's fine.",note:"처음에 sets up the classic 'at first... but now' contrast with 지금."},{ko:"만나서 반갑습니다. 처음 뵙겠습니다.",romanization:"mannaseo bangapseumnida. cheoeum boepgetseumnida.",en:"Glad to meet you. It's the first time meeting you.",note:"Real-situation set phrase for a first introduction — memorize as a unit."}],forms:null,irregular:null,level:"A2",cluster:null,chapters:[2]},반갑다:{ko:"반갑다",romanization:"bangapda",en:"to be glad / pleased to meet",pos:"adjective",chapter:"2",ex:{ko:"만나서 정말 반가워요.",en:"I'm so pleased to meet you.",note:"반갑다 is an adjective meaning 'glad to see/meet someone.' In 해요 speech it becomes 반가워요 — an irregular adjective (ㅂ irregular: 반갑다 → 반가워요)."},collocations:["만나서 반가워요","반갑습니다 (formal)","정말 반가워요"],nuance:"반갑다 is the warm rush of gladness at meeting or seeing someone, and it powers Korea's everyday introduction 만나서 반가워요 ('nice to meet you'). It is a ㅂ-irregular adjective: before an 아/어 ending the ㅂ becomes 우 and merges, so 반갑 + 아요 → 반가워요 (formal 반갑습니다, past 반가웠어요). Keep it firmly about PEOPLE (or news/voices tied to people) — you are glad to encounter someone — unlike 기쁘다, which is general happiness about any good thing (passing an exam, a sunny day). A handy contrast: 기쁘다 = happy in general; 반갑다 = specifically happy to see/meet someone; 즐겁다 = enjoyable/having a good time. English-speaker pitfall: 'I'm glad' in English covers everything, but you can't say 반가워요 about an event or an achievement — 시험에 붙어서 반가워요 is wrong; that is 기뻐요. Reserve 반갑다 for the joy of someone's presence, voice, or a welcome reunion.",explanation:'"to be glad (to meet/see)" is 반갑다 (bangapda). The word itself is easy; what matters is the company it keeps, like 반가워요 ("Nice to meet you / glad to see you"). Watch the particle attached to 반갑다 in each example — that little marker, not the word, tells you whether it is the topic, the subject, the object, or a place. Copy one full sentence about basic everyday communication first, then vary one word.',shortExplanation:'반갑다 means "to be glad (to meet/see)" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Conjugating as 반갑아요; the ㅂ-irregular gives 반가워요.","Using it for general happiness — 'I'm happy I passed' is 기뻐요, not 반가워요; 반갑다 is specifically about meeting/seeing someone.","Saying it about objects or events — 반갑다 attaches to people, voices, or welcome news, not things in general."],conjugationTips:[],usagePhrases:[{ko:"반가워요",romanization:"bangawoyo",en:"Nice to meet you / glad to see you",note:"present 요-form; ㅂ-irregular (반갑 → 반가워요)"},{ko:"만나서 반가워요",romanization:"mannaseo bangawoyo",en:"Glad to meet you",note:"set greeting: 만나서 + 반가워요"},{ko:"반갑습니다",romanization:"bangapseumnida",en:"Pleased to meet you (formal)",note:"-습니다 polite-formal greeting"},{ko:"반가운 소식",romanization:"bangaun sosik",en:"welcome news",note:"-(으)ㄴ attributive; news you're glad to hear"}],examples:[{ko:"만나서 반가워요.",romanization:"mannaseo bangawoyo.",en:"Nice to meet you.",note:"simple: the standard first-meeting greeting"},{ko:"네 목소리 들으니까 진짜 반가워요.",romanization:"ne moksori deureunikka jinjja bangawoyo.",en:"It's so good to hear your voice.",note:"everyday: -(으)니까 trigger + 진짜"},{ko:"여기서 고향 친구를 만나다니, 정말 반가워요!",romanization:"yeogiseo gohyang chingureul mannadani, jeongmal bangawoyo!",en:"To run into a friend from back home here — I'm truly delighted!",note:"real-situation: -다니 (surprise) + warm gladness"}],forms:null,irregular:null,level:"A2",cluster:null,chapters:[2]},아니에요:{ko:"아니에요",romanization:"anieyo",en:"am not / is not / are not",pos:"expression",chapter:"2·3",ex:{ko:"저는 학생이 아니에요. 선생님이에요.",en:"I'm not a student. I'm a teacher.",note:"아니에요 is the polite negative of 이에요/예요. Notice the pattern: N이/가 아니에요 — the noun takes 이/가 (subject marker), then 아니에요."},collocations:["학생이 아니에요","___이 아니에요","아니에요 (standalone = 'not at all / no problem')"],nuance:"아니에요 negates noun labels. It is not the same as 없어요, which means something does not exist or you do not have it.",explanation:'아니에요 (anieyo) means "is not / am not / are not". Learn it inside a frame, not as a bare word: a useful first chunk is 학생이 아니에요. ("I am not a student."). In Korean the particle or ending next to 아니에요 signals its job — topic, subject, object, place, time, method, or description — so read the examples for the small piece beside it. Start with one real sentence about basic everyday communication, then change a single part.',shortExplanation:'아니에요 means "is not / am not / are not" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Do not stack 이에요 and 아니에요 together. Say 학생이 아니에요, not 학생이에요 아니에요."],conjugationTips:[],usagePhrases:[{ko:"학생이 아니에요.",romanization:"haksaengi anieyo.",en:"I am not a student.",note:"학생 ends in a consonant, so use 이 before 아니에요."},{ko:"의사가 아니에요.",romanization:"uisaga anieyo.",en:"I am not a doctor.",note:"의사 ends in a vowel, so use 가 before 아니에요."},{ko:"일본 사람이 아니에요.",romanization:"ilbon sarami anieyo.",en:"I am not Japanese.",note:"사람 ends in a consonant, so use 이."}],examples:[{ko:"저는 선생님이 아니에요. 학생이에요.",romanization:"jeoneun seonsaengnimi anieyo. haksaengieyo.",en:"I am not a teacher. I am a student.",note:"This contrasts one identity with another."}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[2,3]},나라:{ko:"나라",romanization:"nara",en:"country",pos:"noun",chapter:"3",ex:{ko:"어느 나라 사람이에요?",en:"What country are you from?",note:"나라 ends in vowel ㅏ → would take 예요 when used as the sentence topic; 어느 = which"},collocations:["어느 나라","나라 이름","우리나라"],nuance:"나라 is the plain NATIVE Korean word for 'country' (not Sino-Korean), and it works for any nation in everyday speech. Its closest synonym is the Sino-Korean 국가 (國家), and the dividing line is register and abstraction: 나라 is warm, everyday, and concrete ('어느 나라?'), while 국가 is formal and institutional, used for the state as a political entity (국가 정책 'national policy', 국가대표 'national team' — note 국가 not 나라 here). So you'd ask a new acquaintance 어느 나라에서 왔어요? but a textbook would write 국가 간의 관계 'relations between states'. The single most important collocation is 우리나라 — written as ONE word (not 우리 나라) when it means 'our country' in the sense of 'Korea, from our shared insider view'. English speakers tend to over-use the literal 'my country' (제 나라), which sounds detached; among Koreans the warm default is 우리나라. Particle behavior is regular: 나라가 많다 (there are many countries), 어느 나라에서 (from which country). Don't reach for 국가 in casual conversation — it sounds stiff and bureaucratic.",explanation:'나라 (nara) = "country". Treat it as a building block that needs a frame: 우리나라 ("our country") shows how it actually behaves. The grammar lives in the particle or ending beside 나라, so notice that piece as you read, not just the dictionary meaning. Begin from a complete sentence about basic everyday communication and swap just one element to make it yours.',shortExplanation:'나라 means "country" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Using 나라 in formal institutional phrases — 'national team' is 국가대표, 'national policy' is 국가 정책; 나라 is the casual word, 국가 the formal/abstract one.","Writing 우리 나라 with a space when meaning 'Korea/our nation' — the warm fixed sense is one word, 우리나라.","Saying 제 나라 by default for 'my country' — among Koreans the natural warm form is 우리나라; 제 나라 sounds oddly distancing."],conjugationTips:[],usagePhrases:[{ko:"우리나라",romanization:"urinara",en:"our country",note:"우리 + 나라 written as one word; means one's own nation warmly"},{ko:"어느 나라",romanization:"eoneu nara",en:"which country",note:"어느 = which (among a set); the standard question word for nations"},{ko:"나라 이름",romanization:"nara ireum",en:"country name",note:"나라 modifies 이름; the name of a country"},{ko:"나라마다",romanization:"naramada",en:"every country / from country to country",note:"마다 = each/every; common in 나라마다 달라요 'differs by country'"}],examples:[{ko:"어느 나라에서 왔어요?",romanization:"eoneu naraeseo wasseoyo?",en:"Which country are you from?",note:"Simple, extremely common question; 어느 나라 + 에서 marks origin"},{ko:"우리나라는 사계절이 있어요.",romanization:"urinaraneun sagyejeori isseoyo.",en:"Our country has four seasons.",note:"Everyday; 우리나라 as one word, 사계절 = four seasons"},{ko:"나라마다 인사하는 방법이 달라요.",romanization:"naramada insahaneun bangbeobi dallayo.",en:"The way of greeting differs from country to country.",note:"Real-situation; 마다 = each, 다르다 = be different"}],forms:null,irregular:null,level:"A2",cluster:null,chapters:[3]},사람:{ko:"사람",romanization:"saram",en:"person / people",pos:"noun",chapter:"3",ex:{ko:"저는 한국 사람이에요.",en:"I am Korean.",note:"사람 ends in consonant ㅁ → 이에요; [country] + 사람 is the standard pattern for nationality"},collocations:["한국 사람","미국 사람","어느 나라 사람"],nuance:"사람 can mean one person or people in general. It is useful for describing crowds, identity, and who someone is.",explanation:'사람 (saram) means "person / people". Learn it inside a frame, not as a bare word: a useful first chunk is 사람이 많아요 ("There are many people."). In Korean the particle or ending next to 사람 signals its job — topic, subject, object, place, time, method, or description — so read the examples for the small piece beside it. Start with one real sentence about basic everyday communication, then change a single part.',shortExplanation:'사람 means "person / people" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Do not use 사람 for a close relationship when 친구, 선생님, or 가족 is more specific."],conjugationTips:[],usagePhrases:[{ko:"사람이 많아요",romanization:"sarami manayo",en:"There are many people.",note:"Subject."},{ko:"한국 사람이에요",romanization:"hanguk saramieyo",en:"I am Korean / a Korean person.",note:"Identity."},{ko:"이 사람은 누구예요?",romanization:"i sarameun nuguyeyo?",en:"Who is this person?",note:"Topic question."},{ko:"사람을 만나요",romanization:"sarameul mannayo",en:"I meet a person.",note:"Object."}],examples:[{ko:"사람이 많아요.",romanization:"sarami manayo.",en:"There are many people.",note:"Subject."},{ko:"이 사람은 누구예요?",romanization:"i sarameun nuguyeyo?",en:"Who is this person?",note:"Topic."},{ko:"좋은 사람을 만났어요.",romanization:"joeun sarameul mannasseoyo.",en:"I met a good person.",note:"Object."}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[3]},이건:{ko:"이건",romanization:"igeon",en:"this (thing) is / as for this",pos:"pronoun + particle (contraction)",chapter:"3",ex:{ko:"이건 뭐예요?",en:"What is this?",note:"이건 = 이것 + 은 (contracted); 이것 = this thing, 은 = topic marker; used constantly in real speech — more natural than 이것은"},collocations:["이건 뭐예요?","이건 메뉴예요","이건 제 명함이에요"],nuance:"Use 이건 when the thing is near you or already visible in the conversation.",explanation:'"this is / as for this" is 이건 (igeon). The word itself is easy; what matters is the company it keeps, like 이건 뭐예요? ("What is this?"). Watch the particle attached to 이건 in each example — that little marker, not the word, tells you whether it is the topic, the subject, the object, or a place. Copy one full sentence about basic everyday communication first, then vary one word.',shortExplanation:'이건 means "this is / as for this" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Do not say 이는 뭐예요. Use 이건 뭐예요 in everyday speech."],conjugationTips:[],usagePhrases:[{ko:"이건 뭐예요?",romanization:"igeon mwoyeyo?",en:"What is this?",note:"core object-identifying question"},{ko:"이건 메뉴예요.",romanization:"igeon menyuyeyo.",en:"This is a menu.",note:"vowel-ending noun + 예요"},{ko:"이건 책이에요.",romanization:"igeon chaegieyo.",en:"This is a book.",note:"consonant-ending noun + 이에요"}],examples:[{ko:"이건 제 명함이에요.",romanization:"igeon je myeonghamieyo.",en:"This is my business card.",note:"A natural first-meeting object sentence."}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[3]},뭐:{ko:"뭐",romanization:"mwo",en:"what",pos:"question pronoun",chapter:"3·19",ex:{ko:"이름이 뭐예요?",en:"What is your name?",note:"뭐 ends in vowel → 예요; 뭐 is the spoken/colloquial form of 무엇 (what)"},collocations:["이건 뭐예요?","직업이 뭐예요?","이름이 뭐예요?"],nuance:"뭐 is the spoken form of 무엇. It is very common in everyday Korean.",explanation:'뭐 (mwo) = "what". Treat it as a building block that needs a frame: 뭐예요? ("What is it?") shows how it actually behaves. The grammar lives in the particle or ending beside 뭐, so notice that piece as you read, not just the dictionary meaning. Begin from a complete sentence about basic everyday communication and swap just one element to make it yours.',shortExplanation:'뭐 means "what" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","뭐예요 is natural spoken Korean; 무엇이에요 is more careful/dictionary-like."],conjugationTips:[],usagePhrases:[{ko:"뭐예요?",romanization:"mwoyeyo?",en:"What is it?",note:"Question."},{ko:"뭐 먹어요?",romanization:"mwo meogeoyo?",en:"What do you eat?",note:"Object question."},{ko:"뭐 하고 싶어요?",romanization:"mwo hago sipeoyo?",en:"What do you want to do?",note:"Desire."},{ko:"뭐 드릴까요?",romanization:"mwo deurilkkayo?",en:"What can I get you?",note:"Service."}],examples:[{ko:"이건 뭐예요?",romanization:"igeon mwoyeyo?",en:"What is this?",note:"Object identity."},{ko:"뭐 먹고 싶어요?",romanization:"mwo meokgo sipeoyo?",en:"What do you want to eat?",note:"Desire."},{ko:"지금 뭐 해요?",romanization:"jigeum mwo haeyo?",en:"What are you doing now?",note:"Daily."}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[3,19]},제:{ko:"제",romanization:"je",en:"my (humble/polite possessive)",pos:"pronoun",chapter:"3",ex:{ko:"제 이름은 민수예요.",en:"My name is Minsu.",note:"제 is the possessive form of 저 (polite 'I'); 내 is the possessive of 나 (casual 'I') — use 제 in formal/polite situations"},collocations:["제 이름","제 친구","제 직업"],nuance:"제 sounds polite and safe. 내 is casual and belongs with close friends or informal speech.",explanation:'제 (je) = "my (polite/humble)". Treat it as a building block that needs a frame: 제 이름 ("my name") shows how it actually behaves. The grammar lives in the particle or ending beside 제, so notice that piece as you read, not just the dictionary meaning. Begin from a complete sentence about basic everyday communication and swap just one element to make it yours.',shortExplanation:'제 means "my (polite/humble)" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Do not use 내 in a first meeting unless the relationship is already casual."],conjugationTips:[],usagePhrases:[{ko:"제 이름",romanization:"je ireum",en:"my name",note:"introduction phrase"},{ko:"제 직업",romanization:"je jigeop",en:"my job",note:"identity phrase"},{ko:"제 명함",romanization:"je myeongham",en:"my business card",note:"first-meeting phrase"}],examples:[{ko:"제 이름은 민수예요.",romanization:"je ireumeun minsuyeyo.",en:"My name is Minsu.",note:"이름 ends in a consonant, so it takes 은 as the topic marker."}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[3]},직업:{ko:"직업",romanization:"jigeop",en:"job / occupation / profession",pos:"noun",chapter:"3",ex:{ko:"직업이 뭐예요?",en:"What is your job?",note:"직업 ends in consonant 받침 ㅂ → if the answer uses it as topic: 직업은; as subject in the question: 직업이"},collocations:["직업이 뭐예요?","직업은","좋은 직업"],nuance:"직업 (職業, 'duty-work') is the abstract category of one's profession or line of work — the answer to 'what do you do for a living,' not the daily grind itself. The dividing line you must feel: 직업 is the occupation as an identity (간호사, 교사), 직장 is the specific company you belong to, and 일/업무 is the actual work you perform. So 직업이 뭐예요? asks WHAT you are, while 무슨 일 해요? asks more casually what work you do day to day. Register is neutral-to-formal, perfect for a first meeting; among close friends 무슨 일 해? feels warmer. The classic English-speaker trap is 직업을 해요 to mean 'I work' — Korean never 'does' an occupation; you simply state it with 이에요/예요 (선생님이에요), and the particle after 직업 is 이 (직업이), since the word ends in a consonant.",explanation:`"job; occupation" is 직업 (jigeop). The word itself is easy; what matters is the company it keeps, like 직업이 뭐예요? ("What's your job?"). Watch the particle attached to 직업 in each example — that little marker, not the word, tells you whether it is the topic, the subject, the object, or a place. Copy one full sentence about talking about work, schedules, tasks, and obligations first, then vary one word.`,shortExplanation:'직업 means "job; occupation" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Saying 직업을 해요 for 'I work' — you cannot 'do' an occupation in Korean. Name the job instead: 저는 요리사예요 (I'm a cook).","Confusing 직업 (the profession/identity) with 직장 (the workplace/company). '회사가 멀어요' uses 직장, but '의사예요' is your 직업.","Using 가 after 직업 (직업가) — because 직업 ends in a consonant, the subject particle is 이: 직업이 뭐예요?"],conjugationTips:[],usagePhrases:[{ko:"직업이 뭐예요?",romanization:"jigeobi mwoyeyo?",en:"What's your job?",note:"The standard polite way to ask someone's occupation; note the particle is 이, not 가."},{ko:"직업을 바꾸다",romanization:"jigeobeul bakkuda",en:"to change one's occupation",note:"바꾸다 = swap one thing for another; use it for switching careers, not just today's task."},{ko:"전문 직업",romanization:"jeonmun jigeop",en:"a professional occupation",note:"전문 (專門, specialty) marks a skilled profession like doctor or lawyer."},{ko:"직업이 없다",romanization:"jigeobi eopsda",en:"to be without an occupation",note:"없다, not 안 있다; this is the natural way to say 'unemployed' softly."}],examples:[{ko:"직업이 뭐예요?",romanization:"jigeobi mwoyeyo?",en:"What is your job?",note:"The go-to first-meeting question; the verb is hidden inside 뭐예요."},{ko:"제 직업은 간호사예요.",romanization:"je jigeobeun ganhosayeyo.",en:"My job is a nurse.",note:"Topic 직업은 + the profession + 예요; you name the job, you don't 'do' it."},{ko:"좋은 직업을 갖고 싶어요.",romanization:"joeun jigeobeul gatgo sipeoyo.",en:"I want to have a good occupation.",note:"갖다(가지다) 'to hold/have' pairs with 직업 when talking about aspirations."}],forms:null,irregular:null,level:"A2",cluster:null,chapters:[3]},한국어:{ko:"한국어",romanization:"hangugeo",en:"Korean language",pos:"noun",chapter:"3·31·44",ex:{ko:"이건 한국어예요.",en:"This is Korean (the language).",note:"한국어 ends in vowel ㅓ → 예요. Use this when identifying a word, sentence, label, or class as Korean."},collocations:["한국어예요","한국어 공부","한국어 선생님"],nuance:"한국어 points to the language. 한국 사람 points to a Korean person.",explanation:'"Korean language" is 한국어 (hangugeo). The word itself is easy; what matters is the company it keeps, like 한국어예요. ("It is Korean."). Watch the particle attached to 한국어 in each example — that little marker, not the word, tells you whether it is the topic, the subject, the object, or a place. Copy one full sentence about basic everyday communication first, then vary one word.',shortExplanation:'한국어 means "Korean language" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Do not use 한국어 when you mean a Korean person. Say 한국 사람."],conjugationTips:[],usagePhrases:[{ko:"한국어예요.",romanization:"hangugeoyeyo.",en:"It is Korean.",note:"vowel-ending noun + 예요"},{ko:"한국어 선생님",romanization:"hangugeo seonsaengnim",en:"Korean teacher",note:"language + teacher"}],examples:[{ko:"이건 한국어예요.",romanization:"igeon hangugeoyeyo.",en:"This is Korean.",note:"Use this when identifying a sentence, label, or language."}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[3,31,44]},영어:{ko:"영어",romanization:"yeongeo",en:"English language",pos:"noun",chapter:"3",ex:{ko:"저는 영어 선생님이에요.",en:"I am an English teacher.",note:"영어 describes the kind of teacher; 선생님 is the final noun, and it ends in ㅁ → 이에요."},collocations:["영어 선생님","영어예요","영어 공부"],nuance:"영어 is the language. 미국 사람 means an American person.",explanation:'영어 (yeongeo) = "English language". Treat it as a building block that needs a frame: 영어예요. ("It is English.") shows how it actually behaves. The grammar lives in the particle or ending beside 영어, so notice that piece as you read, not just the dictionary meaning. Begin from a complete sentence about basic everyday communication and swap just one element to make it yours.',shortExplanation:'영어 means "English language" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Do not use 영어 사람 for an English-speaking person. Use 미국 사람, 영국 사람, or another nationality as needed."],conjugationTips:[],usagePhrases:[{ko:"영어예요.",romanization:"yeongeoyeyo.",en:"It is English.",note:"vowel-ending noun + 예요"},{ko:"영어 선생님",romanization:"yeongeo seonsaengnim",en:"English teacher",note:"language + teacher"}],examples:[{ko:"제 직업은 영어 선생님이에요.",romanization:"je jigeobeun yeongeo seonsaengnimieyo.",en:"My job is English teacher.",note:"선생님 ends in a consonant, so the sentence ends with 이에요."}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[3]},반갑습니다:{ko:"반갑습니다",romanization:"bangapseumnida",en:"Nice to meet you",pos:"expression",chapter:"3",ex:{ko:"저는 민준이에요. 반갑습니다!",en:"I'm Minjun. Nice to meet you!",note:"반갑습니다 is formal; 반가워요 is slightly less formal — both are appropriate when meeting someone for the first time"},collocations:["처음 뵙겠습니다","반갑습니다","저도 반가워요"],nuance:"",explanation:"",shortExplanation:"",commonMistakes:[],conjugationTips:[],usagePhrases:[],examples:[],forms:null,irregular:null,level:"A1",cluster:null,chapters:[3]},어느:{ko:"어느",romanization:"eoneu",en:"which / what (kind of)",pos:"determiner",chapter:"3·19",ex:{ko:"어느 나라 사람이에요?",en:"Which country are you from?",note:"어느 is a modifier — it must be followed by a noun; unlike 어디 (where), 어느 modifies a noun directly"},collocations:["어느 나라","어느 학교","어느 쪽"],nuance:"어느 means 'which' and is a determiner: it ALWAYS sits in front of a noun and selects one option from a limited, often visible set (어느 것, 어느 나라, 어느 쪽). The synonym you must not blur is 무슨: 어느 chooses from a known, bounded group ('which of these?'), while 무슨 asks 'what kind of' from an open field (무슨 음악 좋아해요? 'what kind of music?'). So 어느 영화 leans toward 'which (of the movies we're choosing among)?' and 무슨 영화 toward 'what (kind of) movie?' The English-speaker pitfall is using 어느 like the pronoun 'which one' on its own — but it cannot stand alone; you must attach a noun, and for 'which one' specifically you say 어느 것/어느 거. Learn 어느 정도 as a unit; it idiomatically means 'to what extent / roughly how much.'",explanation:'"which" is 어느 (eoneu). The word itself is easy; what matters is the company it keeps, like 어느 것 ("which one"). Watch the particle attached to 어느 in each example — that little marker, not the word, tells you whether it is the topic, the subject, the object, or a place. Copy one full sentence about basic everyday communication first, then vary one word.',shortExplanation:'어느 means "which" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Using 어느 alone as 'which one' — it must precede a noun; say 어느 것/어느 거.","Confusing 어느 (which, from a set) with 무슨 (what kind of): 어느 나라 'which country' vs 무슨 일 'what kind of matter.'","Reading 어느 정도 word-for-word; treat it as a set phrase meaning 'to what degree / about how much.'"],conjugationTips:[],usagePhrases:[{ko:"어느 것",romanization:"eoneu geot",en:"which one",note:"어느 + 것 (spoken 어느 거). Picks one item out of a known set."},{ko:"어느 나라",romanization:"eoneu nara",en:"which country",note:"어느 + 나라. Extremely common in 'where are you from?' questions."},{ko:"어느 쪽",romanization:"eoneu jjok",en:"which side / way",note:"어느 + 쪽. Choosing between directions or two options."},{ko:"어느 정도",romanization:"eoneu jeongdo",en:"to what extent / about how much",note:"어느 + 정도. Set phrase asking degree or rough amount."}],examples:[{ko:"어느 것이 더 좋아요?",romanization:"eoneu geosi deo joayo?",en:"Which one is better?",note:"어느 needs a following noun (것 here) — it can't stand alone."},{ko:"어느 나라에서 왔어요?",romanization:"eoneu naraeseo wasseoyo?",en:"What country are you from?",note:"어느 나라 is the natural Korean framing of 'where from.'"},{ko:"한국어 어느 정도 해요?",romanization:"hangugeo eoneu jeongdo haeyo?",en:"How much Korean can you speak?",note:"어느 정도 asks degree — a fixed, very useful collocation."}],forms:null,irregular:null,level:"A2",cluster:null,chapters:[3,19]},예약:{ko:"예약",romanization:"yeyak",en:"reservation / booking",pos:"noun",chapter:"4",ex:{ko:"예약이 있어요?",en:"Do you have a reservation?",note:"예약 ends in consonant ㄱ → 예약이. Essential phrase at hotels and restaurants."},collocations:["예약이 있다","예약이 없다","예약하다 (to book)","예약을 취소하다 (cancel)"],nuance:"예약 is the noun. 예약하다 is the verb 'to reserve/book.' In this chapter, focus first on the noun with 있어요/없어요.",explanation:'예약 (yeyak) = "reservation / booking". Treat it as a building block that needs a frame: 예약이 있어요. ("I have a reservation.") shows how it actually behaves. The grammar lives in the particle or ending beside 예약, so notice that piece as you read, not just the dictionary meaning. Begin from a complete sentence about basic everyday communication and swap just one element to make it yours.',shortExplanation:'예약 means "reservation / booking" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Do not use 예약을 with 있어요/없어요. Use 예약이 because the reservation is the thing that exists."],conjugationTips:[],usagePhrases:[{ko:"예약이 있어요.",romanization:"yeyagi isseoyo.",en:"I have a reservation.",note:"예약 ends in ㄱ, so use 이."},{ko:"예약이 없어요.",romanization:"yeyagi eopseoyo.",en:"I do not have a reservation.",note:"same noun and particle, opposite verb"},{ko:"예약이 있으세요?",romanization:"yeyagi isseuseyo?",en:"Do you have a reservation?",note:"staff often use the honorific 있으세요 with customers."}],examples:[{ko:"예약이 없어요. 자리가 있어요?",romanization:"yeyagi eopseoyo. jariga isseoyo?",en:"I do not have a reservation. Is there a seat?",note:"A natural walk-in restaurant line."}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[4]},돈:{ko:"돈",romanization:"don",en:"money",pos:"noun",chapter:"4·42",ex:{ko:"지금 돈이 없어요.",en:"I don't have money right now.",note:"돈 ends in consonant ㄴ → 돈이. A survival phrase for daily life."},collocations:["돈이 있다","돈이 없다","돈이 많다","돈을 내다 (pay)"],nuance:"돈 is money. In stores, 카드 and 현금 are often more specific and useful.",explanation:'돈 (don) = "money". Treat it as a building block that needs a frame: 돈이 있어요 ("I have money.") shows how it actually behaves. The grammar lives in the particle or ending beside 돈, so notice that piece as you read, not just the dictionary meaning. Begin from a complete sentence about buying things, checking prices, quantities, and payment options and swap just one element to make it yours.',shortExplanation:'돈 means "money" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Do not use 돈을 있어요 for “have money”; say 돈이 있어요."],conjugationTips:[],usagePhrases:[{ko:"돈이 있어요",romanization:"doni isseoyo",en:"I have money.",note:"Possession."},{ko:"돈이 없어요",romanization:"doni eopseoyo",en:"I do not have money.",note:"Absence."},{ko:"돈을 내요",romanization:"doneul naeyo",en:"I pay money.",note:"Object."},{ko:"현금이 없어요",romanization:"hyeongeumi eopseoyo",en:"I do not have cash.",note:"Related."}],examples:[{ko:"돈이 있어요.",romanization:"doni isseoyo.",en:"I have money.",note:"Possession."},{ko:"현금이 없어요.",romanization:"hyeongeumi eopseoyo.",en:"I do not have cash.",note:"Shopping."},{ko:"돈을 내야 해요.",romanization:"doneul naeya haeyo.",en:"I have to pay money.",note:"Obligation."}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[4,42]},화장실:{ko:"화장실",romanization:"hwajangsil",en:"bathroom / restroom",pos:"noun",chapter:"4·10·49",ex:{ko:"여기 화장실이 있어요?",en:"Is there a bathroom here?",note:"화장실 ends in consonant ㄹ → 화장실이. One of the most important travel questions."},collocations:["화장실이 있다","화장실이 어디예요?","화장실을 찾다 (look for bathroom)"],nuance:"화장실 is the normal public word for bathroom/restroom.",explanation:'화장실 (hwajangsil) means "bathroom / restroom". Learn it inside a frame, not as a bare word: a useful first chunk is 화장실 어디예요? ("Where is the bathroom?"). In Korean the particle or ending next to 화장실 signals its job — topic, subject, object, place, time, method, or description — so read the examples for the small piece beside it. Start with one real sentence about getting around, reservations, directions, photos, and emergency help, then change a single part.',shortExplanation:'화장실 means "bathroom / restroom" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","화장실이 어디예요? is complete; 화장실 어디예요? is natural spoken Korean."],conjugationTips:[],usagePhrases:[{ko:"화장실 어디예요?",romanization:"hwajangsil eodiyeyo?",en:"Where is the bathroom?",note:"Travel."},{ko:"화장실이 있어요?",romanization:"hwajangsiri isseoyo?",en:"Is there a bathroom?",note:"Existence."},{ko:"화장실에 가요",romanization:"hwajangsire gayo",en:"I go to the bathroom.",note:"Destination."},{ko:"화장실에서 기다려요",romanization:"hwajangsireseo gidaryeoyo",en:"I wait at the bathroom.",note:"Action place."}],examples:[{ko:"화장실 어디예요?",romanization:"hwajangsil eodiyeyo?",en:"Where is the bathroom?",note:"Direct."},{ko:"여기 화장실 있어요?",romanization:"yeogi hwajangsil isseoyo?",en:"Is there a bathroom here?",note:"Existence."},{ko:"화장실에 가고 싶어요.",romanization:"hwajangsire gago sipeoyo.",en:"I want to go to the bathroom.",note:"Need."}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[4,10,49]},친구:{ko:"친구",romanization:"chingu",en:"friend",pos:"noun",chapter:"4·17·18·33·42·62",ex:{ko:"여기에 친구가 있어요.",en:"My friend is here.",note:"친구 ends in vowel 구 → 친구가. Spotlight on the friend as the one who exists/is present."},collocations:["친구가 있다","친구가 없다","친구를 만나다 (meet a friend)"],nuance:"친구 can mean friend or same-age peer depending on context.",explanation:'친구 (chingu) = "friend". Treat it as a building block that needs a frame: 친구예요 ("is a friend.") shows how it actually behaves. The grammar lives in the particle or ending beside 친구, so notice that piece as you read, not just the dictionary meaning. Begin from a complete sentence about basic everyday communication and swap just one element to make it yours.',shortExplanation:'친구 means "friend" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Use 친구를 만나요 for meeting a friend; do not use 에 for the person you meet."],conjugationTips:[],usagePhrases:[{ko:"친구예요",romanization:"chinguyeyo",en:"is a friend.",note:"Vowel ending takes 예요."},{ko:"친구가 와요",romanization:"chinguga wayo",en:"A friend is coming.",note:"Subject."},{ko:"친구를 만나요",romanization:"chingureul mannayo",en:"I meet a friend.",note:"Object."},{ko:"친구한테 말해요",romanization:"chinguhante malhaeyo",en:"I tell a friend.",note:"To a person."}],examples:[{ko:"제 친구예요.",romanization:"je chinguyeyo.",en:"This is my friend.",note:"Introduction."},{ko:"친구를 만나요.",romanization:"chingureul mannayo.",en:"I meet a friend.",note:"Object."},{ko:"친구가 집에 와요.",romanization:"chinguga jibe wayo.",en:"A friend comes home.",note:"Subject and place."}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[4,17,18,33,42,62]},방:{ko:"방",romanization:"bang",en:"room",pos:"noun",chapter:"4",ex:{ko:"빈 방이 있어요?",en:"Is there a vacant room?",note:"방 ends in consonant ㅇ → 방이. Essential hotel check-in phrase."},collocations:["방이 있다","빈 방 (empty room)","방을 예약하다 (book a room)"],nuance:"방 is the Sino-Korean character 房 ('room, chamber') and is the all-purpose word for any enclosed room, and it builds dozens of everyday compounds: 안방 (master/main room), 공부방 (study room), 노래방 (singing room/karaoke), 찜질방 (Korean sauna room), and PC방 (internet cafe). The key contrast to fix in your head is 방 vs 집: 집 is the whole house/home, but 방 is just one room inside it, so 'I'm going home' must be 집에 가요, never 방에 가요. The grammar trap is the 에 vs 에서 split: merely being located in the room uses 에 (방에 있어요 = it's in the room), but any action carried out inside the room uses 에서 (방에서 공부해요 = I study in my room) — English 'in the room' blurs both, and overusing 에 for actions is the #1 beginner error. Collocations: 방을 치우다/정리하다 (tidy the room), 방이 좁다 (the room is cramped). Register is fully neutral, used by everyone.",explanation:'방 (bang) means "room". Learn it inside a frame, not as a bare word: a useful first chunk is 내 방 ("my room"). In Korean the particle or ending next to 방 signals its job — topic, subject, object, place, time, method, or description — so read the examples for the small piece beside it. Start with one real sentence about daily routines at home, sleep, doors, windows, and simple requests, then change a single part.',shortExplanation:'방 means "room" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Saying 방에서 있어요 for 'it's in the room.' Existence/location with 있다 takes 에 (방에 있어요); 에서 is only for actions performed there.","Translating 'I'm going home' as 방에 가요. 방 is a single room, not the home as a whole — use 집에 가요.","Pairing 작다 with rooms to mean 'cramped.' For a tight room Koreans prefer 방이 좁아요 (narrow/cramped); 작다 sounds like the room's dimensions are literally tiny."],conjugationTips:[],usagePhrases:[{ko:"내 방",romanization:"nae bang",en:"my room",note:"casual possessive 내; the polite form is 제 방"},{ko:"방이 좁아요",romanization:"bangi jobayo",en:"the room is small/cramped",note:"subject 이; 좁다 is the natural opposite of 넓다 for rooms"},{ko:"방에 있어요",romanization:"bange isseoyo",en:"it is in the room",note:"static location takes 에 with 있다"},{ko:"방에서 자요",romanization:"bangeseo jayo",en:"I sleep in the room",note:"action done inside a place takes 에서"}],examples:[{ko:"여기가 제 방이에요.",romanization:"yeogiga je bangieyo.",en:"This is my room.",note:"서술격 조사 이에요 after a consonant; introducing a space"},{ko:"방에서 친구하고 게임해요.",romanization:"bangeseo chinguhago geimhaeyo.",en:"I play games with a friend in my room.",note:"action location 에서, not 에, because something is happening there"},{ko:"방이 너무 좁아서 침대만 있어요.",romanization:"bangi neomu jobaseo chimdaeman isseoyo.",en:"The room is so small that there's only a bed.",note:"-아서 gives the reason; 좁다 (cramped) vs 작다 (small in size)"}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[4]},자리:{ko:"자리",romanization:"jari",en:"seat / spot / space",pos:"noun",chapter:"4",ex:{ko:"자리가 있어요?",en:"Is there a seat available?",note:"자리 ends in vowel 리 → 자리가. Used at restaurants, cafés, cinemas."},collocations:["자리가 있다","자리가 없다","자리를 잡다 (grab a seat)"],nuance:"자리 is the native everyday noun for a seat or a spot you occupy — a seat on a train, a table at a restaurant, a place in a line, even a 'position' in life (좋은 자리 = a good job/standing). The crucial contrast is 자리 vs 의자: 의자 (椅子) is the physical chair as an object, while 자리 is the seat/spot as a space you take or reserve — so you ask 자리 있어요? ('is there a seat/spot?'), not 의자 있어요? (which sounds like 'do you have a chair to sell?'). 자리 collocates richly: 창가 자리 (window seat), 빈자리 (empty seat), 자리에 앉다 (sit down), 자리를 잡다/맡다 (grab/save a spot), 자리를 비우다 (step away from one's seat). Register is neutral and friendly. English-speaker pitfall: with 앉다 ('sit') use the location particle 에 — 자리에 앉아요, not 자리 앉아요; and to choose a seat type use 로/으로 (창가 자리로).",explanation:'자리 (jari) = "seat, spot, place". Treat it as a building block that needs a frame: 창가 자리 ("a window seat") shows how it actually behaves. The grammar lives in the particle or ending beside 자리, so notice that piece as you read, not just the dictionary meaning. Begin from a complete sentence about getting around, reservations, directions, photos, and emergency help and swap just one element to make it yours.',shortExplanation:'자리 means "seat, spot, place" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Saying 의자 when you mean a seat/spot. 의자 is a physical chair; a seat you take or reserve is 자리 (빈자리 있어요?).","Dropping 에 with 앉다. 'Sit in the seat' is 자리에 앉아요; 자리 앉아요 is missing the particle.","Using 있다 wrong for a free seat. Ask 빈자리 있어요? ('is there an empty seat?'); 자리가 비었어요? is also fine but means 'is the seat vacated?'."],conjugationTips:[],usagePhrases:[{ko:"창가 자리",romanization:"changga jari",en:"a window seat",note:"창가 = by the window; a top travel collocation"},{ko:"빈자리",romanization:"binjari",en:"an empty seat",note:"빈 (empty) + 자리, written together"},{ko:"자리에 앉다",romanization:"jarie anjda",en:"to sit in a/the seat",note:"에 marks where you sit; pairs with 앉다"},{ko:"자리를 잡다",romanization:"jarireul japda",en:"to grab/save a spot",note:"잡다 = secure a seat or spot"}],examples:[{ko:"창가 자리로 주세요.",romanization:"changga jariro juseyo.",en:"A window seat, please.",note:"자리로 주세요 = 'give me the ~ seat'; 로 picks the option"},{ko:"여기 빈자리 있어요?",romanization:"yeogi binjari isseoyo?",en:"Is there an empty seat here?",note:"빈자리 있어요? = the standard 'seat free here?' ask"},{ko:"일행이 자리 잡는 동안 제가 주문할게요.",romanization:"ilhaengi jari jamneun dongan jega jumunhalgeyo.",en:"While my group grabs a table, I'll order.",note:"자리(를) 잡다 = secure seats; 동안 = 'during/while'"}],forms:null,irregular:null,level:"A2",cluster:null,chapters:[4]},물:{ko:"물",romanization:"mul",en:"water",pos:"noun",chapter:"4·5·42",ex:{ko:"물이 없어요.",en:"There is no water.",note:"물 ends in consonant ㄹ → 물이. Works for 'there is no water' or 'I don't have water.'"},collocations:["물이 있다","물이 없다","물을 마시다 (drink water)"],nuance:"물 is essential in restaurants. 물 주세요 is more useful than just knowing “water.”",explanation:'물 (mul) = "water". Treat it as a building block that needs a frame: 물 주세요 ("Water, please.") shows how it actually behaves. The grammar lives in the particle or ending beside 물, so notice that piece as you read, not just the dictionary meaning. Begin from a complete sentence about ordering food, explaining food restrictions, and asking what to eat together and swap just one element to make it yours.',shortExplanation:'물 means "water" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Use 물을 마셔요 for drinking water, but 물 주세요 for requesting water."],conjugationTips:[],usagePhrases:[{ko:"물 주세요",romanization:"mul juseyo",en:"Water, please.",note:"Request."},{ko:"물을 마셔요",romanization:"mureul masyeoyo",en:"I drink water.",note:"Object."},{ko:"물이 있어요",romanization:"muri isseoyo",en:"There is water.",note:"Subject."},{ko:"찬물 주세요",romanization:"chanmul juseyo",en:"Cold water, please.",note:"Restaurant."}],examples:[{ko:"물 주세요.",romanization:"mul juseyo.",en:"Water, please.",note:"Restaurant."},{ko:"물을 좀 마셔요.",romanization:"mureul jom masyeoyo.",en:"I drink some water.",note:"Object."},{ko:"여기 물이 있어요.",romanization:"yeogi muri isseoyo.",en:"There is water here.",note:"Subject."}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[4,5,42]},"시간이 있다":{ko:"시간이 있다",romanization:"sigani itda",en:"to have time (lit. time exists)",pos:"verb phrase",chapter:"4·8",ex:{ko:"오늘 시간이 있어요? 같이 밥 먹고 싶어요.",en:"Do you have time today? I want to eat together.",note:"시간이 있어요 is the natural Korean way to say 'have time' — pairs perfectly with 고 싶어요 for invitations"},collocations:["시간이 있어요","시간이 없어요","시간이 있으면","언제 시간이 있어요?"],nuance:"시간 works with 있어요/없어요 and is essential for scheduling.",explanation:'시간 (sigan) = "time". Treat it as a building block that needs a frame: 시간이 있어요 ("I have time.") shows how it actually behaves. The grammar lives in the particle or ending beside 시간, so notice that piece as you read, not just the dictionary meaning. Begin from a complete sentence about basic everyday communication and swap just one element to make it yours.',shortExplanation:'시간 means "time" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Do not use 시간을 있어요 for “have time”; say 시간이 있어요."],conjugationTips:[],usagePhrases:[{ko:"시간이 있어요",romanization:"sigani isseoyo",en:"I have time.",note:"Existence/possession."},{ko:"시간이 없어요",romanization:"sigani eopseoyo",en:"I do not have time.",note:"Absence."},{ko:"시간이 있으면",romanization:"sigani isseumyeon",en:"if you have time.",note:"Condition."},{ko:"몇 시예요?",romanization:"myeot siyeyo?",en:"What time is it?",note:"Related question."}],examples:[{ko:"시간이 있어요?",romanization:"sigani isseoyo?",en:"Do you have time?",note:"Question."},{ko:"오늘은 시간이 없어요.",romanization:"oneureun sigani eopseoyo.",en:"I do not have time today.",note:"Topic + subject."},{ko:"시간이 있으면 전화해 주세요.",romanization:"sigani isseumyeon jeonhwahae juseyo.",en:"If you have time, please call.",note:"Condition."}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[4,8]},있어요:{ko:"있어요",romanization:"isseoyo",en:"there is / have / exists (polite)",pos:"verb",chapter:"4",ex:{ko:"냉장고에 우유가 있어요.",en:"There is milk in the fridge.",note:"있어요 checks the presence lamp: is milk in the fridge? Yes. Note 에 for the location and 이/가 for the thing that exists."},collocations:["N이/가 있어요","N에 있어요 (something IS at a place)","있어요? (do you have it?)"],nuance:"있어요 can mean both 'there is' and 'have.' Context tells whether the sentence is about existence or possession.",explanation:'있어요 (isseoyo) means "there is / have". Learn it inside a frame, not as a bare word: a useful first chunk is 시간이 있어요. ("I have time."). In Korean the particle or ending next to 있어요 signals its job — topic, subject, object, place, time, method, or description — so read the examples for the small piece beside it. Start with one real sentence about basic everyday communication, then change a single part.',shortExplanation:'있어요 means "there is / have" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Do not use 을/를 with 있어요. Say 시간이 있어요, not 시간을 있어요."],conjugationTips:[],usagePhrases:[{ko:"시간이 있어요.",romanization:"sigani isseoyo.",en:"I have time.",note:"시간 ends in a consonant, so use 이."},{ko:"자리가 있어요.",romanization:"jariga isseoyo.",en:"There is a seat.",note:"자리 ends in a vowel, so use 가."},{ko:"예약이 있어요?",romanization:"yeyagi isseoyo?",en:"Do you have a reservation?",note:"A common restaurant and hotel question."}],examples:[{ko:"여기 화장실이 있어요?",romanization:"yeogi hwajangsiri isseoyo?",en:"Is there a bathroom here?",note:"The question word order stays the same; intonation makes it a question."}],forms:null,irregular:null,level:"A2",cluster:null,chapters:[4]},없어요:{ko:"없어요",romanization:"eopseoyo",en:"there isn't / don't have / absent (polite)",pos:"verb",chapter:"4",ex:{ko:"오늘은 시간이 없어요.",en:"I don't have time today.",note:"없어요 is the lamp-OFF version. 오늘은 sets the time as topic with 은/는; 시간이 is the subject of non-existence."},collocations:["N이/가 없어요","없어요? (do you not have it?)","아무것도 없어요 (nothing at all)"],nuance:"없어요 negates existence or possession. It is not the same as 아니에요, which negates a noun identity.",explanation:'"there is not / do not have" is 없어요 (eopseoyo). The word itself is easy; what matters is the company it keeps, like 시간이 없어요. ("I do not have time."). Watch the particle attached to 없어요 in each example — that little marker, not the word, tells you whether it is the topic, the subject, the object, or a place. Copy one full sentence about basic everyday communication first, then vary one word.',shortExplanation:'없어요 means "there is not / do not have" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Do not say 예약을 없어요. The reservation is the subject of absence: 예약이 없어요."],conjugationTips:[],usagePhrases:[{ko:"시간이 없어요.",romanization:"sigani eopseoyo.",en:"I do not have time.",note:"same subject particle as 시간이 있어요"},{ko:"문제가 없어요.",romanization:"munjega eopseoyo.",en:"There is no problem.",note:"문제 ends in a vowel, so use 가."},{ko:"예약이 없어요.",romanization:"yeyagi eopseoyo.",en:"I do not have a reservation.",note:"Useful for walk-in restaurant or hotel situations."}],examples:[{ko:"지금 돈이 없어요.",romanization:"jigeum doni eopseoyo.",en:"I do not have money right now.",note:"돈 ends in a consonant, so use 이."}],forms:null,irregular:null,level:"A2",cluster:null,chapters:[4]},많다:{ko:"많다",romanization:"manta",en:"to be a lot / many",pos:"adjective",chapter:"4",ex:{ko:"오늘 사람이 많아요.",en:"There are a lot of people today.",note:"사람이 많아요 uses 이/가 — the spotlight is on 사람 as the thing that is plentiful. 많다 often pairs with 이/가."},collocations:["N이/가 많다","시간이 많다","돈이 많다"],nuance:"많다 describes quantity. 많이 is the adverb form “a lot.” Learners should practice both because 많아요 describes a noun, while 많이 describes an action.",explanation:'많다 (manta) means "to be many / much". Learn it inside a frame, not as a bare word: a useful first chunk is 많아요 ("There are many / it is a lot."). In Korean the particle or ending next to 많다 signals its job — topic, subject, object, place, time, method, or description — so read the examples for the small piece beside it. Start with one real sentence about basic everyday communication, then change a single part.',shortExplanation:'많다 means "to be many / much" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","많다 and 많이 are different: 사람이 많아요, 많이 먹어요."],conjugationTips:[{title:"Describing a noun: ㄴ/은 vs ㄹ/을",body:'To put 많다 in front of a noun, use the ㄴ/은 form for how something is right now: 많은 것 ("a many / much thing"). The ㄹ/을 form points to something that will or might become that way later. So 뜨거운 물 is water that is hot now, but 뜨거울 물 is water that will be hot — same adjective, different time feeling. For everyday description, reach for the ㄴ/은 form.'}],usagePhrases:[{ko:"많아요",romanization:"manayo",en:"There are many / it is a lot.",note:"Polite."},{ko:"사람이 많아요",romanization:"sarami manayo",en:"There are many people.",note:"Subject."},{ko:"시간이 많아요",romanization:"sigani manayo",en:"I have a lot of time.",note:"Subject."},{ko:"많이 먹어요",romanization:"mani meogeoyo",en:"I eat a lot.",note:"Adverb form."}],examples:[{ko:"사람이 많아요.",romanization:"sarami manayo.",en:"There are many people.",note:"Subject."},{ko:"시간이 많지 않아요.",romanization:"sigani manchi anayo.",en:"I do not have much time.",note:"Careful negative."},{ko:"한국어를 많이 공부해요.",romanization:"hangugeoreul mani gongbuhaeyo.",en:"I study Korean a lot.",note:"Adverb related."}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[4]},예약하다:{ko:"예약하다",romanization:"yeyakada",en:"to reserve / book",pos:"verb",chapter:"4·28",ex:{ko:"식당을 예약했어요.",en:"I made a restaurant reservation.",note:"When 예약 is used as a verb (예약하다), the restaurant is the object → 을/를. Compare: 예약이 있어요 (the reservation exists → 이/가)."},collocations:["N을 예약하다","예약해요 (polite present)","예약했어요 (past)"],nuance:"예약하다 works for restaurants, hotels, tickets, classes, and appointments.",explanation:'"to reserve / book" in Korean is 예약하다 (yeyakada). In real conversation you will lean on the polite form 예약해요, so make that your default and leave the bare dictionary form 예약하다 for study notes. Grow outward from one concrete line — 방을 예약해요 ("book a room.") — then reshape the same stem into 예약하고 싶어요 (desire), 예약할 수 있어요 (ability), and 예약 못 해요 (a real limit) as the moment needs. The stem stays put; only the ending moves.',shortExplanation:'예약하다 means "to reserve / book" and is practiced through polite conversation forms.',commonMistakes:["Do not use the dictionary form 예약하다 as a complete polite sentence.","Use 예약해요 as the default until you know the relationship is casual."],conjugationTips:[{title:"ㄹ / 을 — can & will",body:'To say "can" or the future, attach ㄹ/을 to the stem: a vowel-final stem takes ㄹ and a consonant-final stem takes 을. 예약하다 becomes 예약할 수 있어요 ("can") and 예약할 거예요 ("will"). That is why 가다 → 갈 수 있어요 (not 가을), while 먹다 → 먹을 수 있어요. The same ㄹ/을 choice drives 거예요 and the noun-describing form.'}],usagePhrases:[{ko:"예약해요",romanization:"yeyakaeyo",en:"I reserve / book.",note:"Safe polite present form."},{ko:"예약 안 해요",romanization:"yeyak an haeyo",en:"I do not reserve / book.",note:"Short everyday negative."},{ko:"예약하고 싶어요",romanization:"yeyakago sipeoyo",en:"I want to reserve / book.",note:"Useful for choices and plans."},{ko:"예약할 수 있어요",romanization:"yeyakal su isseoyo",en:"I can reserve / book.",note:"Ability or possibility."},{ko:"예약해야 해요",romanization:"yeyakaeya haeyo",en:"I have to reserve / book.",note:"Requirement or obligation."},{ko:"방을 예약해요",romanization:"bangeul yeyakaeyo",en:"book a room.",note:"Travel phrase."}],examples:[{ko:"방을 예약하고 싶어요.",romanization:"bangeul yeyakago sipeoyo.",en:"I want to book a room.",note:"Hotel."},{ko:"이미 예약했어요.",romanization:"imi yeyakaesseoyo.",en:"I already made a reservation.",note:"Check-in."},{ko:"예약해야 해요?",romanization:"yeyakaeya haeyo?",en:"Do I have to reserve?",note:"Question."}],forms:{dictionary:"예약하다",casualPresent:"예약해",politePresent:"예약해요",formalPresent:"예약합니다",negative:"예약 안 해요",past:"예약했어요",future:"예약할 거예요",want:"예약하고 싶어요",can:"예약할 수 있어요",cannot:"예약 못 해요",must:"예약해야 해요",dontHaveTo:"예약 안 해도 돼요",pleaseDo:"예약해 주세요",pleaseDont:"예약하지 마세요",shallWe:"예약할까요?"},irregular:null,level:"A1",cluster:null,chapters:[4,28]},아프다:{ko:"아프다",romanization:"apeuda",en:"to hurt / be sick / be in pain",pos:"adjective",chapter:"4·11",ex:{ko:"배가 아파요.",en:"My stomach hurts.",note:"배 ends in vowel 배 → 배가. The body part that hurts takes 이/가 — this is a core pattern for describing symptoms."},collocations:["머리가 아프다","배가 아프다","다리가 아프다"],nuance:"아프다 covers both a specific body part hurting (배가 아파요 = my stomach hurts) and the whole-body state of being unwell/sick. The crucial point for English speakers: it is a descriptive adjective, not an action verb, so you describe yourself as 아파요, never 아파해요 — that -해요 ending belongs to verbs like 좋아해요. To say WHAT hurts, the hurting part takes the subject particle 이/가, not 을/를: 머리가 아파요, never 머리를 아파요, because nothing is doing an action to the head; the head simply is in a hurting state. The stem 아프- is ㅡ-irregular: before the -아/어 ending the bare ㅡ drops and, because the remaining vowel ㅏ is bright, 아 is chosen, giving 아 + 아 → 아파요 (not 아프어요). Compare 아프다 with 슬프다 (sad): both are emotional/physical states ending in -프다 and both drop ㅡ the same way (슬퍼요), so once you master 아파요 the pattern transfers. Note the polite/respectful form for an elder is 편찮으세요, a separate honorific word you would use instead of 아프세요 for grandparents.",explanation:`"to hurt; to be sick" is 아프다 (apeuda). The word itself is easy; what matters is the company it keeps, like 아파요 ("it hurts / I'm sick"). Watch the particle attached to 아프다 in each example — that little marker, not the word, tells you whether it is the topic, the subject, the object, or a place. Copy one full sentence about saying what hurts, asking for rest, and explaining basic health needs first, then vary one word.`,shortExplanation:'아프다 means "to hurt; to be sick" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Saying 아파해요 — 아프다 is an adjective, so the plain polite form is 아파요. -해요 only attaches to verbs, so 아파해요 sounds like you are 'doing' hurt, which is wrong.","Marking the body part with 을/를, e.g. 머리를 아파요. The hurting part is the subject of the state, so it must be 머리가 아파요 with 이/가.","Writing 아프어요 by adding the ending mechanically. The ㅡ of 아프- drops before -아/어, and the bright vowel rule gives 아파요."],conjugationTips:[],usagePhrases:[{ko:"아파요",romanization:"apayo",en:"it hurts / I'm sick",note:"ㅡ drops → 아파요"},{ko:"머리가 아파요",romanization:"meoriga apayo",en:"I have a headache",note:"body part + 이/가 + 아파요"},{ko:"많이 아파요",romanization:"mani apayo",en:"I'm really sick",note:"많이 (a lot) intensifies degree"},{ko:"어디가 아파요?",romanization:"eodiga apayo?",en:"where does it hurt?",note:"어디가 asks the spot, the doctor's opener"}],examples:[{ko:"저 오늘 좀 아파요.",romanization:"jeo oneul jom apayo.",en:"I'm a little sick today.",note:"좀 softens it to 'a bit' — telling someone you feel off"},{ko:"배가 아파서 학교에 못 갔어요.",romanization:"baega apaseo hakgyoe mot gasseoyo.",en:"My stomach hurt so I couldn't go to school.",note:"아파서 = the reason; pairs naturally with 못 갔어요"},{ko:"많이 아프시면 병원에 꼭 가 보세요.",romanization:"mani apeusimyeon byeongwone kkok ga boseyo.",en:"If it hurts a lot, please be sure to see a doctor.",note:"아프시면 adds 시 to respect the listener's body"}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[4,11]},좋다:{ko:"좋다",romanization:"jota",en:"to be good / to like",pos:"adjective",chapter:"4·44",ex:{ko:"커피가 좋아요.",en:"I like coffee. / Coffee is good.",note:"In the 'I like X' pattern, X takes 이/가, not 을/를. The spotlight (이/가) is on the thing liked, not the object of an action."},collocations:["N이/가 좋다","뭐가 좋아요? (what do you like?)","다 좋아요 (everything is fine)"],nuance:"좋아요 can mean “it is good” or “I like it.” The subject often takes 이/가.",explanation:'좋다 (jota) = "to be good / to like". Treat it as a building block that needs a frame: 좋아요 ("It is good / I like it.") shows how it actually behaves. The grammar lives in the particle or ending beside 좋다, so notice that piece as you read, not just the dictionary meaning. Begin from a complete sentence about basic everyday communication and swap just one element to make it yours.',shortExplanation:'좋다 means "to be good / to like" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","For liking something, Korean often says X이/가 좋아요, not X을/를 좋아요."],conjugationTips:[{title:"Describing a noun: ㄴ/은 vs ㄹ/을",body:'To put 좋다 in front of a noun, use the ㄴ/은 form for how something is right now: 좋은 것 ("a good / to like thing"). The ㄹ/을 form points to something that will or might become that way later. So 뜨거운 물 is water that is hot now, but 뜨거울 물 is water that will be hot — same adjective, different time feeling. For everyday description, reach for the ㄴ/은 form.'}],usagePhrases:[{ko:"좋아요",romanization:"joayo",en:"It is good / I like it.",note:"Polite adjective."},{ko:"이거 좋아요",romanization:"igeo joayo",en:"This is good.",note:"Pointing."},{ko:"날씨가 좋아요",romanization:"nalssiga joayo",en:"The weather is good.",note:"Subject."},{ko:"저는 커피가 좋아요",romanization:"jeoneun keopiga joayo",en:"I like coffee.",note:"Preference."}],examples:[{ko:"이거 좋아요.",romanization:"igeo joayo.",en:"This is good.",note:"Evaluation."},{ko:"날씨가 좋아요.",romanization:"nalssiga joayo.",en:"The weather is good.",note:"Subject."},{ko:"저는 한국어가 좋아요.",romanization:"jeoneun hangugeoga joayo.",en:"I like Korean.",note:"Preference."}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[4,44]},먹다:{ko:"먹다",romanization:"meokda",en:"to eat",pos:"verb",chapter:"5·6·8·17·18·27·28·29·44·45·57·60",ex:{ko:"맵지 않은 것을 먹고 싶어요.",en:"I want to eat something that isn't spicy.",note:"먹고 싶어요 — desire form; essential at Korean restaurants for dietary preferences"},collocations:["먹고 싶어요","먹을 수 있어요","못 먹어요","같이 먹어요"],nuance:"먹다 is used for meals and food. For medicine, Korean often uses 약을 먹어요, literally “eat medicine,” which means “take medicine.”",explanation:'먹다 (meokda) means "to eat". Start from the polite form 먹어요 — it is safe with almost anyone, so use it before the dictionary form 먹다. A strong first sentence is 점심을 먹어요 ("eat lunch."); once that feels natural, swap the noun, place, or time and reuse the verb everywhere. Korean changes the ending rather than the word, so the same 먹다 also becomes 먹고 싶어요 (want), 먹을 수 있어요 (can), and 못 먹어요 (cannot). Say one true sentence about ordering food, explaining food restrictions, and asking what to eat together, then bend it.',shortExplanation:'먹다 means "to eat" and is practiced through polite conversation forms.',commonMistakes:["Do not use the dictionary form 먹다 as a complete polite sentence.","Use 먹어요 as the default until you know the relationship is casual."],conjugationTips:[{title:"ㄹ / 을 — can & will",body:'To say "can" or the future, attach ㄹ/을 to the stem: a vowel-final stem takes ㄹ and a consonant-final stem takes 을. 먹다 becomes 먹을 수 있어요 ("can") and 먹을 거예요 ("will"). That is why 가다 → 갈 수 있어요 (not 가을), while 먹다 → 먹을 수 있어요. The same ㄹ/을 choice drives 거예요 and the noun-describing form.'}],usagePhrases:[{ko:"먹어요",romanization:"meogeoyo",en:"I eat.",note:"Safe polite present form."},{ko:"안 먹어요",romanization:"an meogeoyo",en:"I do not eat.",note:"Short everyday negative."},{ko:"먹고 싶어요",romanization:"meokgo sipeoyo",en:"I want to eat.",note:"Useful for choices and plans."},{ko:"먹을 수 있어요",romanization:"meogeul su isseoyo",en:"I can eat.",note:"Ability or possibility."},{ko:"먹어야 해요",romanization:"meogeoya haeyo",en:"I have to eat.",note:"Requirement or obligation."},{ko:"점심을 먹어요",romanization:"jeomsimeul meogeoyo",en:"eat lunch.",note:"Use an object with 을/를."}],examples:[{ko:"아침을 먹어요.",romanization:"achimeul meogeoyo.",en:"I eat breakfast.",note:"Simple daily routine."},{ko:"저녁을 같이 먹을까요?",romanization:"jeonyeogeul gachi meogeulkkayo?",en:"Shall we eat dinner together?",note:"Invitation."},{ko:"매운 음식은 못 먹어요.",romanization:"maeun eumsigeun mon meogeoyo.",en:"I cannot eat spicy food.",note:"Useful food restriction."}],forms:{dictionary:"먹다",casualPresent:"먹어",politePresent:"먹어요",formalPresent:"먹습니다",negative:"안 먹어요",past:"먹었어요",future:"먹을 거예요",want:"먹고 싶어요",can:"먹을 수 있어요",cannot:"못 먹어요",must:"먹어야 해요",dontHaveTo:"안 먹어도 돼요",pleaseDo:"먹어 주세요",pleaseDont:"먹지 마세요",shallWe:"먹을까요?"},irregular:null,level:"A1",cluster:null,chapters:[5,6,8,17,18,27,28,29,44,45,57,60]},마시다:{ko:"마시다",romanization:"masida",en:"to drink",pos:"verb",chapter:"5·8",ex:{ko:"커피를 마시고 싶어요.",en:"I want to drink coffee.",note:"마시 + 고 싶어요 — the stem ends in a vowel so 고 attaches cleanly"},collocations:["마시고 싶어요","마실 수 있어요","못 마셔요","물을 마시다"],nuance:"마시다 is for liquids. In casual speech, Koreans often drop particles: 커피 마셔요 is natural.",explanation:'"to drink" in Korean is 마시다 (masida). In real conversation you will lean on the polite form 마셔요, so make that your default and leave the bare dictionary form 마시다 for study notes. Grow outward from one concrete line — 물을 마셔요 ("drink water.") — then reshape the same stem into 마시고 싶어요 (desire), 마실 수 있어요 (ability), and 못 마셔요 (a real limit) as the moment needs. The stem stays put; only the ending moves.',shortExplanation:'마시다 means "to drink" and is practiced through polite conversation forms.',commonMistakes:["Do not use the dictionary form 마시다 as a complete polite sentence.","Use 마셔요 as the default until you know the relationship is casual."],conjugationTips:[{title:"ㄹ / 을 — can & will",body:'To say "can" or the future, attach ㄹ/을 to the stem: a vowel-final stem takes ㄹ and a consonant-final stem takes 을. 마시다 becomes 마실 수 있어요 ("can") and 마실 거예요 ("will"). That is why 가다 → 갈 수 있어요 (not 가을), while 먹다 → 먹을 수 있어요. The same ㄹ/을 choice drives 거예요 and the noun-describing form.'}],usagePhrases:[{ko:"마셔요",romanization:"masyeoyo",en:"I drink.",note:"Safe polite present form."},{ko:"안 마셔요",romanization:"an masyeoyo",en:"I do not drink.",note:"Short everyday negative."},{ko:"마시고 싶어요",romanization:"masigo sipeoyo",en:"I want to drink.",note:"Useful for choices and plans."},{ko:"마실 수 있어요",romanization:"masil su isseoyo",en:"I can drink.",note:"Ability or possibility."},{ko:"마셔야 해요",romanization:"masyeoya haeyo",en:"I have to drink.",note:"Requirement or obligation."},{ko:"물을 마셔요",romanization:"mureul masyeoyo",en:"drink water.",note:"Common object phrase."}],examples:[{ko:"물을 좀 마셔요.",romanization:"mureul jom masyeoyo.",en:"I drink some water.",note:"Use 좀 to soften."},{ko:"커피를 마시고 싶어요.",romanization:"keopireul masigo sipeoyo.",en:"I want to drink coffee.",note:"Desire form."},{ko:"술은 못 마셔요.",romanization:"sureun mon masyeoyo.",en:"I cannot drink alcohol.",note:"Restriction."}],forms:{dictionary:"마시다",casualPresent:"마셔",politePresent:"마셔요",formalPresent:"마십니다",negative:"안 마셔요",past:"마셨어요",future:"마실 거예요",want:"마시고 싶어요",can:"마실 수 있어요",cannot:"못 마셔요",must:"마셔야 해요",dontHaveTo:"안 마셔도 돼요",pleaseDo:"마셔 주세요",pleaseDont:"마시지 마세요",shallWe:"마실까요?"},irregular:null,level:"A1",cluster:null,chapters:[5,8]},운동하다:{ko:"운동하다",romanization:"undonghada",en:"to exercise",pos:"verb",chapter:"5·8·31·32·60",ex:{ko:"요즘 바빠서 운동 못 해요.",en:"Lately I'm busy so I can't exercise.",note:"운동하다 is a 하다 verb: 못 + 해요 = 못 해요. The noun 운동 and 못 해요 can be separated: 운동 못 해요."},collocations:["운동하고 싶어요","운동할 수 있어요","운동 못 해요","매일 운동해요"],nuance:"운동하다 = 한자 運動 (運 'move, transport' + 動 'move') + 하다, literally 'movement-movement,' i.e. to physically exercise. The same noun 운동 also means a sports movement or a social campaign, but with 하다 it's working out. A key feature for learners: Korean builds most sports the same way — noun + 하다 (축구하다 play soccer, 수영하다 swim), though racket sports take 치다 'hit' instead (테니스 치다). The contrast with 놀다 ('play, hang out, have fun') matters: 놀다 is unstructured fun, 운동하다 is purposeful physical activity, so don't say 놀다 when you mean training. Natural collocations: 헬스장에서 운동하다, 건강을 위해 운동하다, 운동 부족. As a 하다 verb the negatives split — 운동 안 해요, 운동 못 해요 — and you can swap in 운동을 안 하다 with the object marker for a touch more emphasis.",explanation:'운동하다 (undonghada) means "to exercise". Start from the polite form 운동해요 — it is safe with almost anyone, so use it before the dictionary form 운동하다. A strong first sentence is 매일 아침에 운동해요. ("I exercise every morning."); once that feels natural, swap the noun, place, or time and reuse the verb everywhere. Korean changes the ending rather than the word, so the same 운동하다 also becomes 운동하고 싶어요 (want), 운동할 수 있어요 (can), and 운동 못 해요 (cannot). Say one true sentence about basic everyday communication, then bend it.',shortExplanation:'운동하다 means "to exercise" and is practiced through polite conversation forms.',commonMistakes:["Do not use the dictionary form 운동하다 as a complete polite sentence.","Use 운동해요 as the default until you know the relationship is casual.","Using 놀다 (play/hang out) for working out: '공원에서 놀아요' means goofing around, not exercising. For a workout say 공원에서 운동해요.","Saying 안 운동해요. Inside the 하다 verb: 운동 안 해요 (or 운동을 안 해요).","Applying 운동하다 to racket and ball sports that need 치다: tennis is 테니스 쳐요, not 테니스 운동해요. Use the sport's own verb where one exists."],conjugationTips:[{title:"ㄹ / 을 — can & will",body:'To say "can" or the future, attach ㄹ/을 to the stem: a vowel-final stem takes ㄹ and a consonant-final stem takes 을. 운동하다 becomes 운동할 수 있어요 ("can") and 운동할 거예요 ("will"). That is why 가다 → 갈 수 있어요 (not 가을), while 먹다 → 먹을 수 있어요. The same ㄹ/을 choice drives 거예요 and the noun-describing form.'}],usagePhrases:[{ko:"운동해요",romanization:"undonghaeyo",en:"I exercise.",note:"Safe polite present form."},{ko:"운동 안 해요",romanization:"undong an haeyo",en:"I do not exercise.",note:"Short everyday negative."},{ko:"운동하고 싶어요",romanization:"undonghago sipeoyo",en:"I want to exercise.",note:"Useful for choices and plans."},{ko:"운동할 수 있어요",romanization:"undonghal su isseoyo",en:"I can exercise.",note:"Ability or possibility."},{ko:"운동해야 해요",romanization:"undonghaeya haeyo",en:"I have to exercise.",note:"Requirement or obligation."},{ko:"매일 아침에 운동해요.",romanization:"maeil achime undonghaeyo.",en:"I exercise every morning.",note:"Time + 에 + 운동하다 for a routine."}],examples:[{ko:"요즘 운동해?",romanization:"yojeum undonghae?",en:"Are you working out these days?",note:"Casual check-in; 요즘 (lately) frames an ongoing habit."},{ko:"건강을 위해서 운동하고 싶어요.",romanization:"geongangeul wihaeseo undonghago sipeoyo.",en:"I want to exercise for my health.",note:"건강을 위해서 (for the sake of health) + 운동하고 싶다."},{ko:"요즘 바빠서 운동 못 해요.",romanization:"yojeum bappaseo undong mo taeyo.",en:"I can't exercise these days because I'm busy.",note:"Negative ability 운동 못 하다, with 못 inside the 하다 verb."}],forms:{dictionary:"운동하다",casualPresent:"운동해",politePresent:"운동해요",formalPresent:"운동합니다",negative:"운동 안 해요",past:"운동했어요",future:"운동할 거예요",want:"운동하고 싶어요",can:"운동할 수 있어요",cannot:"운동 못 해요",must:"운동해야 해요",dontHaveTo:"운동 안 해도 돼요",pleaseDo:"운동해 주세요",pleaseDont:"운동하지 마세요",shallWe:"운동할까요?"},irregular:null,level:"A2",cluster:null,chapters:[5,8,31,32,60]},일하다:{ko:"일하다",romanization:"ilhada",en:"to work",pos:"verb",chapter:"5·6·27",ex:{ko:"오늘 일 안 해요.",en:"I'm not working today.",note:"Noun+하다 split negative: 일 + 안 + 해요 — the stop sign goes between noun and verb"},collocations:["일을 하다","일 안 해요","열심히 일하다"],nuance:"Use 에서 for where an action happens: 회사에서 일해요.",explanation:'일하다 (ilhada) means "to work". Start from the polite form 일해요 — it is safe with almost anyone, so use it before the dictionary form 일하다. A strong first sentence is 회사에서 일해요 ("work at a company."); once that feels natural, swap the noun, place, or time and reuse the verb everywhere. Korean changes the ending rather than the word, so the same 일하다 also becomes 일하고 싶어요 (want), 일할 수 있어요 (can), and 일 못 해요 (cannot). Say one true sentence about talking about work, schedules, tasks, and obligations, then bend it.',shortExplanation:'일하다 means "to work" and is practiced through polite conversation forms.',commonMistakes:["Do not use the dictionary form 일하다 as a complete polite sentence.","Use 일해요 as the default until you know the relationship is casual."],conjugationTips:[{title:"ㄹ / 을 — can & will",body:'To say "can" or the future, attach ㄹ/을 to the stem: a vowel-final stem takes ㄹ and a consonant-final stem takes 을. 일하다 becomes 일할 수 있어요 ("can") and 일할 거예요 ("will"). That is why 가다 → 갈 수 있어요 (not 가을), while 먹다 → 먹을 수 있어요. The same ㄹ/을 choice drives 거예요 and the noun-describing form.'}],usagePhrases:[{ko:"일해요",romanization:"ilhaeyo",en:"I work.",note:"Safe polite present form."},{ko:"일 안 해요",romanization:"il an haeyo",en:"I do not work.",note:"Short everyday negative."},{ko:"일하고 싶어요",romanization:"ilhago sipeoyo",en:"I want to work.",note:"Useful for choices and plans."},{ko:"일할 수 있어요",romanization:"ilhal su isseoyo",en:"I can work.",note:"Ability or possibility."},{ko:"일해야 해요",romanization:"ilhaeya haeyo",en:"I have to work.",note:"Requirement or obligation."},{ko:"회사에서 일해요",romanization:"hoesaeseo ilhaeyo",en:"work at a company.",note:"Action location uses 에서."}],examples:[{ko:"회사에서 일해요.",romanization:"hoesaeseo ilhaeyo.",en:"I work at a company.",note:"Location of action."},{ko:"오늘 늦게까지 일해야 해요.",romanization:"oneul neutgekkaji ilhaeya haeyo.",en:"I have to work late today.",note:"Obligation."},{ko:"주말에는 일 안 해요.",romanization:"jumareneun il an haeyo.",en:"I do not work on weekends.",note:"Routine."}],forms:{dictionary:"일하다",casualPresent:"일해",politePresent:"일해요",formalPresent:"일합니다",negative:"일 안 해요",past:"일했어요",future:"일할 거예요",want:"일하고 싶어요",can:"일할 수 있어요",cannot:"일 못 해요",must:"일해야 해요",dontHaveTo:"일 안 해도 돼요",pleaseDo:"일해 주세요",pleaseDont:"일하지 마세요",shallWe:"일할까요?"},irregular:null,level:"A1",cluster:null,chapters:[5,6,27]},밥:{ko:"밥",romanization:"bap",en:"cooked rice / meal",pos:"noun",chapter:"5",ex:{ko:"밥을 먹어요?",en:"Are you eating? / Do you eat rice?",note:"밥 ends in consonant ㅂ → 을; 밥을 먹다 is the most common eating phrase in Korean"},collocations:["밥을 먹다","아침을 먹다","점심을 먹다"],nuance:"밥 literally is the bowl of cooked white rice, but by extension it is the default word for 'a meal' — which is why 밥 먹었어요? functions as a real greeting like 'how are you?', not a literal question about rice. Contrast it with 식사(食事), the polite Sino-Korean word for 'a meal': you offer an elder 식사하셨어요?, never the blunt 밥 먹었어요?. The verb is 먹다(eat), and to cook rice you say 밥을 하다 or 밥을 짓다, not 밥을 만들다. The big English-speaker pitfall is hearing 밥 only as 'rice' and missing that 밥 먹자 means 'let's grab a bite', and that to a boss you must upgrade to 식사 to stay polite.",explanation:'밥 (bap) means "cooked rice; a meal". Learn it inside a frame, not as a bare word: a useful first chunk is 밥을 먹어요 ("I eat rice / I eat a meal"). In Korean the particle or ending next to 밥 signals its job — topic, subject, object, place, time, method, or description — so read the examples for the small piece beside it. Start with one real sentence about ordering food, explaining food restrictions, and asking what to eat together, then change a single part.',shortExplanation:'밥 means "cooked rice; a meal" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Saying 밥을 만들어요 for 'I make rice' — Korean fixes this verb as 밥을 해요 (or 밥을 지어요); 만들다 sounds like manufacturing.","Greeting an elder with 밥 먹었어요? — too blunt; use the honorific 식사하셨어요? instead.","Hearing 밥 only as 'rice' and so misreading 밥 먹자 — it actually means 'let's eat / let's grab a meal'."],conjugationTips:[],usagePhrases:[{ko:"밥을 먹어요",romanization:"babeul meogeoyo",en:"I eat rice / I eat a meal",note:"object marker 을; the all-purpose word for having any meal"},{ko:"밥이 맛있어요",romanization:"babi masisseoyo",en:"the rice is tasty",note:"subject marker 이 spotlights the rice itself"},{ko:"밥 먹었어요?",romanization:"bam meogeosseoyo?",en:"have you eaten?",note:"drops the particle in casual speech; works as a friendly greeting"},{ko:"밥을 해요",romanization:"babeul haeyo",en:"I cook (make) rice",note:"밥하다 = make rice/a meal, not 만들다"}],examples:[{ko:"저는 아침에 밥을 먹어요.",romanization:"jeoneun achime babeul meogeoyo.",en:"I eat rice in the morning.",note:"simple daily routine with object 을"},{ko:"밥 다 먹었으면 같이 나가자.",romanization:"bap da meogeosseumyeon gachi nagaja.",en:"If you're done eating, let's head out together.",note:"casual 반말; 밥 here = the whole meal, particle dropped"},{ko:"식사 나오기 전에 밥부터 좀 주세요.",romanization:"siksa naogi jeone bapbuteo jom juseyo.",en:"Before the meal comes, could you give us some rice first?",note:"real restaurant line; 밥(rice) vs 식사(the meal) used side by side"}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[5]},매일:{ko:"매일",romanization:"maeil",en:"every day",pos:"adverb",chapter:"5",ex:{ko:"매일 커피를 마셔요.",en:"I drink coffee every day.",note:"매일 is a time adverb — it doesn't need a particle; it modifies the entire sentence"},collocations:["매일 먹다","매일 운동하다","매일 공부하다"],nuance:"매일 means 'every day' and is the default word for habits and routines. The 매 is Sino-Korean 每 'each/every', and 일 is 日 'day', so it literally reads 'each-day'; swap the second half for 매주 每週 'every week', 매월/매달 'every month', 매년 每年 'every year'. Crucially 매일 is an adverb of frequency, so unlike clock times it takes NO 에 — say 매일 운동해요, never 매일에. English speakers also confuse it with 하루, which is the counter 'one day / a day' (하루 종일 'all day long'); 매일 is the recurring habit, 하루 is a single day. A near rival is 날마다 'each day', which is interchangeable in meaning but feels a touch more literary/measured, while 매일 is the plain everyday choice. It almost always comes before the verb and pairs happily with 거의, 아침/밤, and the emphatic 매일같이.",explanation:'"every day" is 매일 (maeil). The word itself is easy; what matters is the company it keeps, like 매일 아침 ("every morning"). Watch the particle attached to 매일 in each example — that little marker, not the word, tells you whether it is the topic, the subject, the object, or a place. Copy one full sentence about basic everyday communication first, then vary one word.',shortExplanation:'매일 means "every day" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Saying 매일에 공부해요 — frequency adverbs take no particle. Drop 에: 매일 공부해요. (The 에 belongs only on the clock time, e.g. 일곱 시에.)","Using 하루 where you mean a repeated habit, e.g. ✗ 하루 운동해요 for 'I exercise every day'. 하루 = one single day; the habit is 매일 운동해요.","Writing the verb 늘다-style 매일다 or treating it as a noun with 을/를. 매일 is purely an adverb — it modifies the verb directly."],conjugationTips:[],usagePhrases:[{ko:"매일 아침",romanization:"maeil achim",en:"every morning",note:"매(每) 'each' stacks before a time word: 매일 아침, 매일 밤, 매주 월요일."},{ko:"매일매일",romanization:"maeilmaeil",en:"day after day, every single day",note:"Reduplicating it adds warmth/emphasis, common in songs and encouragement."},{ko:"거의 매일",romanization:"geoui maeil",en:"almost every day",note:"거의 (almost) is the natural softener when it isn't literally 100% of days."},{ko:"매일같이",romanization:"maeilgachi",en:"every single day (emphatic)",note:"Write it closed (매일같이, not 매일 같이) — it stresses how relentlessly often, sometimes with mild complaint."}],examples:[{ko:"저는 매일 한국어를 공부해요.",romanization:"jeoneun maeil hangugeoreul gongbuhaeyo.",en:"I study Korean every day.",note:"Core habit pattern; 매일 sits right before the verb phrase."},{ko:"매일 아침 일곱 시에 일어나요.",romanization:"maeil achim ilgop sie ireonayo.",en:"I get up at seven every morning.",note:"Here the clock time takes 에 (일곱 시에), but 매일 itself never does."},{ko:"요즘 거의 매일 비가 와서 힘들어요.",romanization:"yojeum geoui maeil biga waseo himdeureoyo.",en:"Lately it rains almost every day, so it's tough.",note:"거의 매일 + a real complaint; shows the word in a fuller, lived-in sentence."}],forms:null,irregular:null,level:"A2",cluster:null,chapters:[5]},많이:{ko:"많이",romanization:"mani",en:"a lot / many / much",pos:"adverb",chapter:"5",ex:{ko:"물을 많이 마셔요.",en:"I drink a lot of water.",note:"많이 (adverb) modifies the verb directly — no particle needed on the adverb itself"},collocations:["많이 먹다","많이 마시다","많이 공부하다"],nuance:"많이 is the adverb form of the adjective 많다 ('to be many/much') and is the everyday word for 'a lot/much', sitting right in front of the verb it modifies (많이 먹어요, 많이 자요). Its near-synonym is 너무: 많이 just states a large amount neutrally, while 너무 carries an 'excessive, over the line' feeling, so 많이 매워요 is 'quite spicy' but 너무 매워요 is 'too spicy (uncomfortably)'. With feeling-verbs and adjectives 많이 stretches to mean 'very/badly', as in 많이 아파요 ('it hurts a lot'). The classic English-speaker pitfall is reaching for the adjective 많다 directly before a verb — you must use the adverb 많이 (많이 먹어요, never 많다 먹어요) — and remembering that, like all Korean adverbs, it comes before the verb, not after it.",explanation:'많이 (mani) = "a lot, much, many". Treat it as a building block that needs a frame: 많이 먹어요 ("I eat a lot") shows how it actually behaves. The grammar lives in the particle or ending beside 많이, so notice that piece as you read, not just the dictionary meaning. Begin from a complete sentence about basic everyday communication and swap just one element to make it yours.',shortExplanation:'많이 means "a lot, much, many" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Using the adjective 많다 where the verb needs the adverb: before a verb it is 많이 먹어요, not 많다 먹어요. 많다 can only sit at the end as a predicate (책이 많아요).","Putting 많이 after the verb on the English word order: 먹어요 많이 sounds broken; Korean adverbs go before the verb (많이 먹어요).","Treating 많이 and 너무 as interchangeable: 너무 implies 'too much/excessive', so 너무 좋아요 ('I like it so much') and 많이 좋아요 carry slightly different feelings."],conjugationTips:[],usagePhrases:[{ko:"많이 먹어요",romanization:"mani meogeoyo",en:"I eat a lot",note:"Sits directly before the verb; the default way to mark a large amount"},{ko:"많이 주세요",romanization:"mani juseyo",en:"Please give me a lot",note:"Handy when ordering food or asking a server for more"},{ko:"많이 바빠요",romanization:"mani bappayo",en:"I'm very busy",note:"Before an adjective 많이 shifts from 'a lot' to a degree word, 'very'"},{ko:"너무 많이",romanization:"neomu mani",en:"too much",note:"너무 많이 마셨어요 = I drank too much; 너무 adds the 'over the line' feeling"}],examples:[{ko:"오늘 비가 많이 와요.",romanization:"oneul biga mani wayo.",en:"It's raining a lot today.",note:"비가 오다 is the set verb for 'it rains'; 많이 measures the quantity"},{ko:"한국 음식을 많이 좋아해요.",romanization:"hanguk eumsigeul mani joahaeyo.",en:"I really like Korean food.",note:"With 좋아하다, 많이 means the feeling is strong, like 'a lot'"},{ko:"많이 드세요.",romanization:"mani deuseyo.",en:"Please help yourself / enjoy your meal.",note:"드세요 is the honorific of 먹다; this is what a host warmly says at the table"}],forms:null,irregular:null,level:"A2",cluster:null,chapters:[5]},카페:{ko:"카페",romanization:"kape",en:"café",pos:"noun",chapter:"6·18",ex:{ko:"카페에서 친구를 기다려요.",en:"I wait for my friend at the café.",note:"에서 — waiting is an active state/action"},collocations:["카페에 가다","카페에서 만나다","카페에서 일하다"],nuance:"카페 is a loanword (from French/English 'café') meaning a coffee shop — but in Korea it is as much a social and study space as a place to drink coffee; people sit for hours to chat, work on laptops, or go on a 카페 투어 of photogenic spots. The key contrast learners blur is 카페 vs 커피: 카페 is the *place*, 커피 is the *drink*, so '커피 마시러 카페에 가요' (go to the cafe to drink coffee). It overlaps with 커피숍 and the older 다방 (a dated tea-room), but 카페 is the modern default. Being borrowed, it has no hanja. The English-speaker pitfall is exactly that 카페/커피 mix-up, plus the particles — 카페에 가요 for going there but 카페에서 공부해요 for doing something there — and remember the purpose marker for 'to go drink coffee' is the verb stem + ~(으)러: 커피 마시러 카페에 가요.",explanation:'카페 (kape) means "cafe". Learn it inside a frame, not as a bare word: a useful first chunk is 조용한 카페 ("a quiet cafe"). In Korean the particle or ending next to 카페 signals its job — topic, subject, object, place, time, method, or description — so read the examples for the small piece beside it. Start with one real sentence about getting around, reservations, directions, photos, and emergency help, then change a single part.',shortExplanation:'카페 means "cafe" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Saying 커피에 가요 for 'I go to the cafe'. 커피 is the drink; the place is 카페, so it is 카페에 가요. To say why, use ~러: 커피 마시러 카페에 가요.","Using 에 instead of 에서 for activities done inside: 카페에 공부해요 is wrong. An action performed at the cafe takes 에서 — 카페에서 공부해요.","Assuming a 카페 only sells coffee fast like a takeout stand. Korean cafes are sit-down social/study spaces; ordering one drink and staying for hours is normal and expected."],conjugationTips:[],usagePhrases:[{ko:"조용한 카페",romanization:"joyonghan kape",en:"a quiet cafe",note:"조용하다 'to be quiet'; 조용한 카페 is a prized spot for studying or talking."},{ko:"카페에 가요",romanization:"kapee gayo",en:"I go to the cafe",note:"에 marks the destination you head to with 가다/오다."},{ko:"카페에서 공부해요",romanization:"kapeeseo gongbuhaeyo",en:"I study at the cafe",note:"에서 marks where the activity happens; people study and work in Korean cafes for hours."},{ko:"카페 투어",romanization:"kape tueo",en:"a cafe tour / cafe-hopping",note:"투어 from 'tour'; visiting several trendy cafes in a day, a popular outing."}],examples:[{ko:"카페가 예뻐요.",romanization:"kapega yeppeoyo.",en:"The cafe is pretty.",note:"Simple description; 예쁘다 here praises the interior/atmosphere, a very common reason to pick a cafe."},{ko:"친구랑 카페에서 두 시간 동안 수다 떨었어요.",romanization:"chingurang kapeeseo du sigan dongan suda tteoreosseoyo.",en:"I chatted with a friend at the cafe for two hours.",note:"동안 = 'for (a duration)'; 수다(를) 떨다 'to chat away' — cafes are social hubs."},{ko:"이 카페는 자리도 넓고 콘센트도 많아서 일하기 좋아요.",romanization:"i kapeneun jarido neolbgo konsenteudo manaseo ilhagi joayo.",en:"This cafe has roomy seats and lots of outlets, so it's good for working.",note:"콘센트 = power outlet; ~기 좋다 'good for ~ing' explains why Koreans 'cafe-work'."}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[6,18]},회사:{ko:"회사",romanization:"hoesa",en:"company / office",pos:"noun",chapter:"6",ex:{ko:"회사에서 8시간 일해요.",en:"I work at the office for 8 hours.",note:"에서 — working is an active action"},collocations:["회사에 가다","회사에서 일하다","회사에 다니다"],nuance:"회사 often means workplace in daily conversation, not only the company as an organization.",explanation:'"company / workplace" is 회사 (hoesa). The word itself is easy; what matters is the company it keeps, like 회사에 가요 ("I go to work / the company."). Watch the particle attached to 회사 in each example — that little marker, not the word, tells you whether it is the topic, the subject, the object, or a place. Copy one full sentence about talking about work, schedules, tasks, and obligations first, then vary one word.',shortExplanation:'회사 means "company / workplace" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","회사에 일해요 is unnatural for “work at a company”; use 회사에서 일해요."],conjugationTips:[],usagePhrases:[{ko:"회사에 가요",romanization:"hoesae gayo",en:"I go to work / the company.",note:"Destination."},{ko:"회사에서 일해요",romanization:"hoesaeseo ilhaeyo",en:"I work at a company.",note:"Action place."},{ko:"회사원이에요",romanization:"hoesawonieyo",en:"I am an office worker.",note:"Identity."},{ko:"회사에 있어요",romanization:"hoesae isseoyo",en:"I am at work.",note:"Location."}],examples:[{ko:"회사에 가요.",romanization:"hoesae gayo.",en:"I go to work.",note:"Destination."},{ko:"회사에서 일해요.",romanization:"hoesaeseo ilhaeyo.",en:"I work at a company.",note:"Action place."},{ko:"지금 회사에 있어요.",romanization:"jigeum hoesae isseoyo.",en:"I am at work now.",note:"Location."}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[6]},식당:{ko:"식당",romanization:"sikdang",en:"restaurant",pos:"noun",chapter:"6·17",ex:{ko:"식당에서 비빔밥을 먹어요.",en:"I eat bibimbap at the restaurant.",note:"에서 — eating is an active action"},collocations:["식당에 가다","식당에서 먹다","식당에서 만나다"],nuance:"식당 is 食堂 — 食 'eat' + 堂 'hall' — an 'eating hall', i.e. an ordinary, everyday place to have a meal: a neighborhood eatery, a noodle shop, or a 구내식당(cafeteria). The register contrast is 레스토랑, the loanword reserved for fancier, often Western, sit-down dining; you'd call a humble 백반집 a 식당, never a 레스토랑, and a candlelit Italian place a 레스토랑, not a plain 식당. The crucial grammar point is particle choice: use 에서 for an action done there (식당에서 먹어요 'eat AT the restaurant') but 에 for it as a destination (식당에 가요 'go TO the restaurant'). The English-speaker pitfall is exactly this 에/에서 split, since English 'at/to' don't map one-to-one; another is reaching for 레스토랑 as the default word for any restaurant when 식당 is the everyday term.",explanation:'"restaurant; eatery; cafeteria" is 식당 (sikdang). The word itself is easy; what matters is the company it keeps, like 식당에서 먹어요 ("I eat at the restaurant"). Watch the particle attached to 식당 in each example — that little marker, not the word, tells you whether it is the topic, the subject, the object, or a place. Copy one full sentence about ordering food, explaining food restrictions, and asking what to eat together first, then vary one word.',shortExplanation:'식당 means "restaurant; eatery; cafeteria" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Using 에 instead of 에서 for an action — 식당에서 먹어요 (eat AT), but 식당에 가요 (go TO); the verb decides the particle.","Defaulting to 레스토랑 for any restaurant — everyday eateries are 식당; 레스토랑 implies an upscale/Western place.","Saying 식당으로 먹어요 — 으로 marks means/direction, not the location of an action; the location particle is 에서."],conjugationTips:[],usagePhrases:[{ko:"식당에서 먹어요",romanization:"sikdangeseo meogeoyo",en:"I eat at the restaurant",note:"에서 marks the place where an action happens"},{ko:"식당에 가요",romanization:"sikdange gayo",en:"I go to the restaurant",note:"에 marks the destination of movement"},{ko:"식당이 깔끔해요",romanization:"sikdangi kkalkkeumhaeyo",en:"the restaurant is clean/tidy",note:"subject marker 이; 깔끔하다 = neat, clean"},{ko:"단골 식당",romanization:"dangol sikdang",en:"a regular haunt / go-to restaurant",note:"단골 = a place one frequents"}],examples:[{ko:"우리 이 식당에서 점심 먹어요.",romanization:"uri i sikdangeseo jeomsim meogeoyo.",en:"Let's eat lunch at this restaurant.",note:"simple line contrasting place-of-action 에서"},{ko:"저 식당에 가서 자리부터 잡을게요.",romanization:"jeo sikdange gaseo jaributeo jabeulgeyo.",en:"I'll go to that restaurant and grab a table first.",note:"everyday line; movement 에 then 가서"},{ko:"회사 구내식당이 싸고 빨라서 점심은 거기서 해결해요.",romanization:"hoesa gunaesikdangi ssago ppallaseo jeomsimeun geogiseo haegyeolhaeyo.",en:"The company cafeteria is cheap and fast, so I handle lunch there.",note:"real-situation use; 구내식당 = staff cafeteria"}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[6,17]},집:{ko:"집",romanization:"jip",en:"home / house",pos:"noun",chapter:"6·17",ex:{ko:"집에서 쉬고 싶어요.",en:"I want to rest at home.",note:"에서 — resting is an action at a location"},collocations:["집에 가다","집에 있다","집에서 요리하다"],nuance:"집 can mean home or house. 집에 often means “home” in movement/location sentences.",explanation:'집 (jip) means "home / house". Learn it inside a frame, not as a bare word: a useful first chunk is 집에 가요 ("I go home."). In Korean the particle or ending next to 집 signals its job — topic, subject, object, place, time, method, or description — so read the examples for the small piece beside it. Start with one real sentence about daily routines at home, sleep, doors, windows, and simple requests, then change a single part.',shortExplanation:'집 means "home / house" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Do not add 에서 for going home; use 집에 가요."],conjugationTips:[],usagePhrases:[{ko:"집에 가요",romanization:"jibe gayo",en:"I go home.",note:"Destination."},{ko:"집에 있어요",romanization:"jibe isseoyo",en:"I am at home.",note:"Location."},{ko:"집에서 쉬어요",romanization:"jibeseo swieoyo",en:"I rest at home.",note:"Action place."},{ko:"집이 멀어요",romanization:"jibi meoreoyo",en:"My home is far.",note:"Subject."}],examples:[{ko:"집에 가요.",romanization:"jibe gayo.",en:"I go home.",note:"Destination."},{ko:"오늘은 집에서 쉬어요.",romanization:"oneureun jibeseo swieoyo.",en:"I rest at home today.",note:"Action place."},{ko:"친구가 집에 와요.",romanization:"chinguga jibe wayo.",en:"A friend comes to my home.",note:"Destination."}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[6,17]},공원:{ko:"공원",romanization:"gongwon",en:"park",pos:"noun",chapter:"6",ex:{ko:"공원에서 운동해요.",en:"I exercise at the park.",note:"에서 — exercising is an action"},collocations:["공원에 가다","공원에서 걷다","공원에서 운동하다"],nuance:"공원 (公園, 'public-garden', 公 'public' + 園 'garden') is a public green space for walking, exercise, picnics and rest — found in every Korean neighborhood, from small 근린공원 to huge ones like 한강공원 or 올림픽공원. The near-synonym to distinguish is 정원 (庭園), a private *garden* attached to a home or building: 공원 is open to everyone, 정원 is someone's own landscaped yard, so don't call a public park a 정원. It is also not 놀이공원 (an amusement park with rides) — that compound needs 놀이. The collocations are scenic: 공원에서 산책하다 (stroll), 운동하다 (exercise), 돗자리를 깔다 (spread a picnic mat). The English-speaker pitfall is again 공원에 가요 (destination, 에) versus 공원에서 산책해요 (action location, 에서); and the static verb 앉다 takes 에 — 벤치에 앉다 'sit on the bench', not 에서.",explanation:'공원 (gongwon) = "park". Treat it as a building block that needs a frame: 넓은 공원 ("a spacious park") shows how it actually behaves. The grammar lives in the particle or ending beside 공원, so notice that piece as you read, not just the dictionary meaning. Begin from a complete sentence about getting around, reservations, directions, photos, and emergency help and swap just one element to make it yours.',shortExplanation:'공원 means "park" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Calling a private home garden a 공원. 공원 is a *public* green space; a private landscaped yard is a 정원 (庭園). The 公 in 공원 literally means 'public'.","Saying 공원에서 가요 for 'I go to the park'. Movement to the park needs 에 (공원에 가요); 에서 only marks an action carried out there, like 공원에서 운동해요.","Using 공원 to mean an amusement park. Rides-and-attractions parks are 놀이공원 (e.g. 에버랜드는 놀이공원이에요); a plain 공원 is just a green park."],conjugationTips:[],usagePhrases:[{ko:"넓은 공원",romanization:"neolbeun gongwon",en:"a spacious park",note:"넓다 'to be wide/spacious'; describes the open green area itself."},{ko:"공원에 가요",romanization:"gongwone gayo",en:"I go to the park",note:"에 marks the destination with 가다/오다."},{ko:"공원에서 산책해요",romanization:"gongwoneseo sanchaekaeyo",en:"I take a walk in the park",note:"에서 = where the action happens; 산책(을) 하다 'to take a stroll' is the classic park activity."},{ko:"공원 벤치",romanization:"gongwon benchi",en:"a park bench",note:"벤치 from 'bench'; 벤치에 앉다 'sit on the bench' — note location 에 with the static verb 앉다."}],examples:[{ko:"공원이 넓어요.",romanization:"gongwoni neolbeoyo.",en:"The park is spacious.",note:"Basic description; 넓다 'to be wide'. 이 after a consonant."},{ko:"저녁마다 공원에서 강아지랑 산책해요.",romanization:"jeonyeongmada gongwoneseo gangajirang sanchaekaeyo.",en:"Every evening I walk the dog in the park.",note:"마다 'every'; 에서 because the walking happens in the park; 랑 'with' (casual)."},{ko:"주말에는 공원에서 돗자리 깔고 도시락 먹는 사람이 많아요.",romanization:"jumareneun gongwoneseo dotjari kkalgo dosirang meongneun sarami manayo.",en:"On weekends many people lay out a mat and eat lunchboxes in the park.",note:"돗자리(를) 깔다 'spread a picnic mat' — a very Korean park scene; 에서 marks the location."}],forms:null,irregular:null,level:"A2",cluster:null,chapters:[6]},가다:{ko:"가다",romanization:"gada",en:"to go",pos:"verb",chapter:"6·8·17·18·29·45",ex:{ko:"오늘은 못 가요. 내일 갈 수 있어요.",en:"I can't go today. I can go tomorrow.",note:"Two patterns in one sentence: 못 가요 (blocked today) vs 갈 수 있어요 (open tomorrow)"},collocations:["가고 싶어요","갈 수 있어요","못 가요","같이 가요"],nuance:"Use 에 for destination: 학교에 가요, 집에 가요. Do not use 에서 for destination.",explanation:`가다 (gada) = "to go". Don't try to memorize all fifteen forms at once; anchor on 가요 plus one useful sentence like 학교에 가요 ("go to school."). After that the endings carry the meaning — 가고 싶어요 for what you want, 갈 수 있어요 for what you can, 못 가요 for what you can't. Keep the stem, change the ending, and one verb gives you a dozen sentences about getting around, reservations, directions, photos, and emergency help.`,shortExplanation:'가다 means "to go" and is practiced through polite conversation forms.',commonMistakes:["Do not use the dictionary form 가다 as a complete polite sentence.","Use 가요 as the default until you know the relationship is casual."],conjugationTips:[{title:"ㄹ / 을 — can & will",body:'To say "can" or the future, attach ㄹ/을 to the stem: a vowel-final stem takes ㄹ and a consonant-final stem takes 을. 가다 becomes 갈 수 있어요 ("can") and 갈 거예요 ("will"). That is why 가다 → 갈 수 있어요 (not 가을), while 먹다 → 먹을 수 있어요. The same ㄹ/을 choice drives 거예요 and the noun-describing form.'}],usagePhrases:[{ko:"가요",romanization:"gayo",en:"I go.",note:"Safe polite present form."},{ko:"안 가요",romanization:"an gayo",en:"I do not go.",note:"Short everyday negative."},{ko:"가고 싶어요",romanization:"gago sipeoyo",en:"I want to go.",note:"Useful for choices and plans."},{ko:"갈 수 있어요",romanization:"gal su isseoyo",en:"I can go.",note:"Ability or possibility."},{ko:"가야 해요",romanization:"gaya haeyo",en:"I have to go.",note:"Requirement or obligation."},{ko:"학교에 가요",romanization:"hakgyoe gayo",en:"go to school.",note:"Destination takes 에."}],examples:[{ko:"집에 가요.",romanization:"jibe gayo.",en:"I go home.",note:"Destination pattern."},{ko:"내일 병원에 가야 해요.",romanization:"naeil byeongwone gaya haeyo.",en:"I have to go to the hospital tomorrow.",note:"Obligation."},{ko:"같이 갈까요?",romanization:"gachi galkkayo?",en:"Shall we go together?",note:"Suggestion."}],forms:{dictionary:"가다",casualPresent:"가",politePresent:"가요",formalPresent:"갑니다",negative:"안 가요",past:"갔어요",future:"갈 거예요",want:"가고 싶어요",can:"갈 수 있어요",cannot:"못 가요",must:"가야 해요",dontHaveTo:"안 가도 돼요",pleaseDo:"가 주세요",pleaseDont:"가지 마세요",shallWe:"갈까요?"},irregular:null,level:"A1",cluster:null,chapters:[6,8,17,18,29,45]},오다:{ko:"오다",romanization:"oda",en:"to come",pos:"verb",chapter:"6·8·17·47·50",ex:{ko:"오늘 파티에 올 수 있어요?",en:"Can you come to the party today?",note:"오다 → stem 오 (vowel) → 올 수 있어요? A common social question — the ㄹ is added to the vowel stem"},collocations:["오고 싶어요","올 수 있어요","못 와요","같이 와요"],nuance:"오다 is from the speaker’s point of view. If someone moves toward you or your place, 오다 is usually right.",explanation:'오다 (oda) means "to come". Start from the polite form 와요 — it is safe with almost anyone, so use it before the dictionary form 오다. A strong first sentence is 집에 와요 ("come home."); once that feels natural, swap the noun, place, or time and reuse the verb everywhere. Korean changes the ending rather than the word, so the same 오다 also becomes 오고 싶어요 (want), 올 수 있어요 (can), and 못 와요 (cannot). Say one true sentence about basic everyday communication, then bend it.',shortExplanation:'오다 means "to come" and is practiced through polite conversation forms.',commonMistakes:["Do not use the dictionary form 오다 as a complete polite sentence.","Use 와요 as the default until you know the relationship is casual."],conjugationTips:[{title:"ㄹ / 을 — can & will",body:'To say "can" or the future, attach ㄹ/을 to the stem: a vowel-final stem takes ㄹ and a consonant-final stem takes 을. 오다 becomes 올 수 있어요 ("can") and 올 거예요 ("will"). That is why 가다 → 갈 수 있어요 (not 가을), while 먹다 → 먹을 수 있어요. The same ㄹ/을 choice drives 거예요 and the noun-describing form.'}],usagePhrases:[{ko:"와요",romanization:"wayo",en:"I come.",note:"Safe polite present form."},{ko:"안 와요",romanization:"an wayo",en:"I do not come.",note:"Short everyday negative."},{ko:"오고 싶어요",romanization:"ogo sipeoyo",en:"I want to come.",note:"Useful for choices and plans."},{ko:"올 수 있어요",romanization:"ol su isseoyo",en:"I can come.",note:"Ability or possibility."},{ko:"와야 해요",romanization:"waya haeyo",en:"I have to come.",note:"Requirement or obligation."},{ko:"집에 와요",romanization:"jibe wayo",en:"come home.",note:"Destination can still use 에."}],examples:[{ko:"친구가 와요.",romanization:"chinguga wayo.",en:"My friend is coming.",note:"Subject marker."},{ko:"오늘 못 와요.",romanization:"oneul mot wayo.",en:"I cannot come today.",note:"Useful cancellation."},{ko:"여기로 와 주세요.",romanization:"yeogiro wa juseyo.",en:"Please come here.",note:"Request with 여기로."}],forms:{dictionary:"오다",casualPresent:"와",politePresent:"와요",formalPresent:"옵니다",negative:"안 와요",past:"왔어요",future:"올 거예요",want:"오고 싶어요",can:"올 수 있어요",cannot:"못 와요",must:"와야 해요",dontHaveTo:"안 와도 돼요",pleaseDo:"와 주세요",pleaseDont:"오지 마세요",shallWe:"올까요?"},irregular:null,level:"A1",cluster:null,chapters:[6,8,17,47,50]},있다:{ko:"있다",romanization:"itda",en:"to be / to exist / to have",pos:"verb",chapter:"6",ex:{ko:"지금 카페에 있어요.",en:"I'm at the café right now.",note:"있다 = static existence → ALWAYS takes 에, never 에서"},collocations:["N에 있다","집에 있다","어디에 있어요?"],nuance:"",explanation:"",shortExplanation:"",commonMistakes:[],conjugationTips:[],usagePhrases:[],examples:[],forms:null,irregular:null,level:"A1",cluster:null,chapters:[6]},기다리다:{ko:"기다리다",romanization:"gidarida",en:"to wait",pos:"verb",chapter:"6·9·27·58",ex:{ko:"잠깐 기다려 주세요.",en:"Please wait a moment.",note:"기다리다 + 어 주세요 — 리 contracts to 려; asking someone to hold on"},collocations:["기다려 주세요","기다려도 돼요?","기다리지 않아도 돼요"],nuance:"기다려 주세요 is one of the most useful service and classroom requests.",explanation:`기다리다 (gidarida) = "to wait". Don't try to memorize all fifteen forms at once; anchor on 기다려요 plus one useful sentence like 잠깐 기다려 주세요 ("Please wait a moment."). After that the endings carry the meaning — 기다리고 싶어요 for what you want, 기다릴 수 있어요 for what you can, 못 기다려요 for what you can't. Keep the stem, change the ending, and one verb gives you a dozen sentences about using buses, subways, taxis, and asking where to get on or off.`,shortExplanation:'기다리다 means "to wait" and is practiced through polite conversation forms.',commonMistakes:["Do not use the dictionary form 기다리다 as a complete polite sentence.","Use 기다려요 as the default until you know the relationship is casual."],conjugationTips:[{title:"ㄹ / 을 — can & will",body:'To say "can" or the future, attach ㄹ/을 to the stem: a vowel-final stem takes ㄹ and a consonant-final stem takes 을. 기다리다 becomes 기다릴 수 있어요 ("can") and 기다릴 거예요 ("will"). That is why 가다 → 갈 수 있어요 (not 가을), while 먹다 → 먹을 수 있어요. The same ㄹ/을 choice drives 거예요 and the noun-describing form.'}],usagePhrases:[{ko:"기다려요",romanization:"gidaryeoyo",en:"I wait.",note:"Safe polite present form."},{ko:"안 기다려요",romanization:"an gidaryeoyo",en:"I do not wait.",note:"Short everyday negative."},{ko:"기다리고 싶어요",romanization:"gidarigo sipeoyo",en:"I want to wait.",note:"Useful for choices and plans."},{ko:"기다릴 수 있어요",romanization:"gidaril su isseoyo",en:"I can wait.",note:"Ability or possibility."},{ko:"기다려야 해요",romanization:"gidaryeoya haeyo",en:"I have to wait.",note:"Requirement or obligation."},{ko:"잠깐 기다려 주세요",romanization:"jamkkan gidaryeo juseyo",en:"Please wait a moment.",note:"Very useful request."}],examples:[{ko:"잠깐 기다려 주세요.",romanization:"jamkkan gidaryeo juseyo.",en:"Please wait a moment.",note:"Polite request."},{ko:"버스를 기다려요.",romanization:"beoseureul gidaryeoyo.",en:"I wait for the bus.",note:"Transportation."},{ko:"오래 기다렸어요.",romanization:"orae gidaryeosseoyo.",en:"I waited a long time.",note:"Past."}],forms:{dictionary:"기다리다",casualPresent:"기다려",politePresent:"기다려요",formalPresent:"기다립니다",negative:"안 기다려요",past:"기다렸어요",future:"기다릴 거예요",want:"기다리고 싶어요",can:"기다릴 수 있어요",cannot:"못 기다려요",must:"기다려야 해요",dontHaveTo:"안 기다려도 돼요",pleaseDo:"기다려 주세요",pleaseDont:"기다리지 마세요",shallWe:"기다릴까요?"},irregular:null,level:"A1",cluster:{title:"기다리다 vs 기대하다",rule:'These are false friends for English "wait for / expect." 기다리다 is actual waiting — time passing until someone or something arrives. 기대하다 is looking forward to something good, with no waiting around involved.',members:[{ko:"기다리다",en:"to wait",romanization:"gidarida",when:"waiting for a person, bus, turn",hint:"real waiting, time passing",example:{ko:"잠깐만 기다려 주세요.",en:"Please wait a moment."},self:!0},{ko:"기대하다",en:"to expect",romanization:"gidaehada",when:"looking forward to something good",hint:"hopeful anticipation, no waiting",example:{ko:"여행을 기대하고 있어요.",en:"I'm looking forward to the trip."},self:!1}]},chapters:[6,9,27,58]},오후:{ko:"오후",romanization:"ohu",en:"afternoon / PM",pos:"noun",chapter:"6",ex:{ko:"오후에 도서관에서 공부해요.",en:"I study at the library in the afternoon.",note:"오후에 marks time; 도서관에서 marks the action place"},collocations:["오후에","오후 시간","오후에 만나다"],nuance:"오후 is the Sino-Korean PM label, literally 午後 'after noon' (午 noon, 後 after), the exact counterpart of 오전 午前. It covers every PM hour from 12:00 until evening, where it hands off to 저녁. The contrast to watch is 오후 vs 저녁: 오후 is the neutral clock-PM you write on schedules (오후 3시 회의), while 저녁 is the lived early-evening AND the dinner meal; so a 6 p.m. plan can be 오후 6시 on a timetable but 저녁 when you talk about eating. 오후 collocates with clock times (오후 3시), 수업/회의/근무, and the fixed 오후 늦게 'late in the afternoon'. The number-one English-speaker pitfall is order: 'PM' follows the number in English but the period LEADS in Korean — say 오후 5시, never 5시 오후. A second trap is treating 오후 as a greeting-time word like 'good afternoon'; Korean has no clock-based greeting, so you still say 안녕하세요, not anything built on 오후.",explanation:'"afternoon / PM" is 오후 (ohu). The word itself is easy; what matters is the company it keeps, like 오후에 ("in the afternoon"). Watch the particle attached to 오후 in each example — that little marker, not the word, tells you whether it is the topic, the subject, the object, or a place. Copy one full sentence about basic everyday communication first, then vary one word.',shortExplanation:'오후 means "afternoon / PM" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Writing 다섯 시 오후 — Korean order is period-then-time, so it must be 오후 다섯 시.","Using 오후 for an early-evening dinner plan — for the dinner-time feel switch to 저녁 (저녁 여섯 시), since 오후 is the neutral daytime-PM span.","Trying to greet someone with a phrase based on 오후 like English 'good afternoon' — Korean uses the all-purpose 안녕하세요 regardless of the hour."],conjugationTips:[],usagePhrases:[{ko:"오후에",romanization:"ohue",en:"in the afternoon",note:"time particle 에 = 'during the PM'"},{ko:"오후 세 시",romanization:"ohu se si",en:"3 PM",note:"period precedes the clock number"},{ko:"오후 수업",romanization:"ohu sueop",en:"afternoon class",note:"오후 modifies the noun directly"},{ko:"내일 오후",romanization:"naeil ohu",en:"tomorrow afternoon",note:"day word + 오후 stack with no particle between"}],examples:[{ko:"오후에 친구를 만나요.",romanization:"ohue chingureul mannayo.",en:"I meet a friend in the afternoon.",note:"basic: 에 marks time-when"},{ko:"오후 두 시에 약속이 있어요.",romanization:"ohu du sie yaksogi isseoyo.",en:"I have an appointment at 2 PM.",note:"everyday: 오후 + 두 시 + 에 in sequence"},{ko:"오후 늦게 비가 올 것 같아요.",romanization:"ohu neutge biga ol geot gatayo.",en:"It looks like it'll rain late in the afternoon.",note:"real-situation: 오후 늦게 = 'late in the PM', a fixed phrase"}],forms:null,irregular:null,level:"A2",cluster:null,chapters:[6]},저녁:{ko:"저녁",romanization:"jeonyeok",en:"evening",pos:"noun",chapter:"6",ex:{ko:"저녁에 집에 와요.",en:"I come home in the evening.",note:"저녁에 marks time; 집에 marks the destination of 오다"},collocations:["저녁에","저녁 시간","저녁에 오다"],nuance:"저녁 is a native Korean word covering the early-night period AND the dinner meal, mirroring 아침/점심: 저녁을 먹다 is the food, 저녁에 is the time. The fine line is 저녁 vs 밤: 저녁 is the social early evening — dusk through dinner, when people are still out — whereas 밤 is true late night when it's dark and quiet; so a 7 p.m. dinner is 저녁, but 11 p.m. is 밤. 저녁 also contrasts with the clock label 오후, which ends as 저녁 begins. Habitual partners: 저녁을 먹다, 저녁 식사, 저녁 약속, 저녁 메뉴, 저녁에 만나다. The main English-speaker pitfall is using 밤 for the dinner meal because 'night' feels close — but 'eat dinner' is 저녁을 먹다, never 밤을 먹다 (밤 can't name a meal, and 밤 also happens to mean 'chestnut'). A second trap: don't mark the dinner-meal with 에; you eat 저녁을, while 저녁에 means 'in the evening (do something)'.",explanation:'"evening; also dinner" is 저녁 (jeonyeok). The word itself is easy; what matters is the company it keeps, like 저녁을 먹어요 ("eat dinner"). Watch the particle attached to 저녁 in each example — that little marker, not the word, tells you whether it is the topic, the subject, the object, or a place. Copy one full sentence about ordering food, explaining food restrictions, and asking what to eat together first, then vary one word.',shortExplanation:'저녁 means "evening; also dinner" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Saying 밤을 먹어요 for 'eat dinner' — 밤 names late-night, not a meal (and also means 'chestnut'); the dinner meal is 저녁을 먹어요.","Using 저녁 for genuinely late night (e.g. midnight) — past dinner into the dark, quiet hours it becomes 밤; 저녁 is the early, social evening.","Marking the meal with 에 (저녁에 먹어요, meaning the food) — the dinner-as-object needs 을: 저녁을 먹어요."],conjugationTips:[],usagePhrases:[{ko:"저녁을 먹어요",romanization:"jeonyeogeul meogeoyo",en:"eat dinner",note:"meal sense → object 을"},{ko:"저녁에",romanization:"jeonyeoge",en:"in the evening",note:"time sense → 에"},{ko:"저녁 식사",romanization:"jeonyeok siksa",en:"dinner (meal)",note:"식사 'a meal' makes the dinner sense explicit & polite"},{ko:"내일 저녁",romanization:"naeil jeonyeok",en:"tomorrow evening",note:"day word + 저녁 with no particle between"}],examples:[{ko:"저녁에 영화를 봐요.",romanization:"jeonyeoge yeonghwareul bwayo.",en:"I watch a movie in the evening.",note:"basic: 저녁에 = the time slot"},{ko:"저녁 뭐 먹을까요?",romanization:"jeonyeong mwo meogeulkkayo?",en:"What should we eat for dinner?",note:"everyday: meal 을 dropped in casual speech + 을까요 suggestion"},{ko:"오늘 저녁에 시간 괜찮으면 같이 식사해요.",romanization:"oneul jeonyeoge sigan gwaenchaneumyeon gachi siksahaeyo.",en:"If you're free this evening, let's eat together.",note:"real-situation: 저녁에 (time) + polite invitation 식사하다"}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[6]},주세요:{ko:"주세요",romanization:"juseyo",en:"please give me / please do",pos:"verb ending",chapter:"7",ex:{ko:"아메리카노 두 잔 주세요.",en:"Two Americanos, please.",note:"N + 주세요 = the single most useful ordering pattern in Korea"},collocations:["N 주세요","N 좀 주세요","영수증 주세요"],nuance:"",explanation:"",shortExplanation:"",commonMistakes:[],conjugationTips:[],usagePhrases:[],examples:[],forms:null,irregular:null,level:"A1",cluster:null,chapters:[7]},얼마예요:{ko:"얼마예요",romanization:"eolmayeyo",en:"how much is it?",pos:"expression",chapter:"7",ex:{ko:"이거 얼마예요?",en:"How much is this?",note:"이거 (this) + 얼마예요 — the go-to price question in any market, convenience store, or café"},collocations:["이거 얼마예요?","다 해서 얼마예요?","할인하면 얼마예요?"],nuance:"",explanation:"",shortExplanation:"",commonMistakes:[],conjugationTips:[],usagePhrases:[],examples:[],forms:null,irregular:null,level:"A1",cluster:null,chapters:[7]},카드:{ko:"카드",romanization:"kadeu",en:"card (credit/debit)",pos:"noun",chapter:"7",ex:{ko:"카드로 결제할 수 있어요?",en:"Can I pay by card?",note:"카드 ends in a vowel → 로 (not 으로)"},collocations:["카드로 결제하다","카드로 내다","카드 돼요?"],nuance:"카드로 is the method “by card.” 카드 돼요? is short but very common.",explanation:'카드 (kadeu) means "card". Learn it inside a frame, not as a bare word: a useful first chunk is 카드 돼요? ("Can I pay by card?"). In Korean the particle or ending next to 카드 signals its job — topic, subject, object, place, time, method, or description — so read the examples for the small piece beside it. Start with one real sentence about buying things, checking prices, quantities, and payment options, then change a single part.',shortExplanation:'카드 means "card" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","카드로 사요 means buy by card, not buy a card."],conjugationTips:[],usagePhrases:[{ko:"카드 돼요?",romanization:"kadeu dwaeyo?",en:"Can I pay by card?",note:"Shortcut."},{ko:"카드로 결제해요",romanization:"kadeuro gyeoljehaeyo",en:"I pay by card.",note:"Method."},{ko:"카드 써도 돼요?",romanization:"kadeu sseodo dwaeyo?",en:"May I use a card?",note:"Permission."},{ko:"카드가 있어요",romanization:"kadeuga isseoyo",en:"I have a card.",note:"Possession."}],examples:[{ko:"카드 돼요?",romanization:"kadeu dwaeyo?",en:"Can I pay by card?",note:"Store."},{ko:"카드로 결제할게요.",romanization:"kadeuro gyeoljehalgeyo.",en:"I will pay by card.",note:"Payment."},{ko:"카드 써도 돼요?",romanization:"kadeu sseodo dwaeyo?",en:"May I use a card?",note:"Permission."}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[7]},현금:{ko:"현금",romanization:"hyeongeum",en:"cash",pos:"noun",chapter:"7",ex:{ko:"현금으로 낼게요.",en:"I'll pay in cash.",note:"현금 ends in a consonant (ㅁ) → 으로"},collocations:["현금으로 내다","현금 없어요","현금만 돼요"],nuance:"현금(現金) is Sino-Korean — 現 'present/actual' + 金 'gold/money' — literally 'actual money', i.e. physical notes and coins you hand over, as opposed to 카드 (card) or 계좌이체 (bank transfer). The crucial grammar point is the particle: payment method takes 으로/로 ('by means of'), so 'pay with cash' is 현금으로 내다/계산하다 — English speakers reach for 'with' and wrongly grab 와/하고 (which mean 'together with a person/thing') or 에 (location/time). 현금 is more specific than the umbrella word 돈 (money): 돈 covers wealth in general, but 현금 specifically means money in hand right now (you can have lots of 돈 in the bank but no 현금 in your wallet). A very useful real-life phrase is 현금 영수증 ('cash receipt') — a registered receipt for tax deduction that clerks routinely offer with 현금 영수증 해 드릴까요? Collocations: 현금으로 내다/계산하다/결제하다, 현금만 받다, 현금이 모자라다.",explanation:'현금 (hyeongeum) = "cash". Treat it as a building block that needs a frame: 현금으로 내요 ("I pay with cash") shows how it actually behaves. The grammar lives in the particle or ending beside 현금, so notice that piece as you read, not just the dictionary meaning. Begin from a complete sentence about buying things, checking prices, quantities, and payment options and swap just one element to make it yours.',shortExplanation:'현금 means "cash" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Using 에 or 하고 for 'with cash' — 현금에 내요 or 현금하고 내요 are wrong. The means particle is 으로: 현금으로 내요. Reserve 하고/와 for accompaniment ('with a friend').","Treating 현금 and 돈 as identical. 돈이 없어요 can mean you're broke overall; 현금이 없어요 specifically means you have no physical cash on you (maybe you have a card). Pick the one you mean.","Forgetting that 되다 marks acceptability: 'is cash OK?' is 현금 돼요?, and 'cash only' is 현금만 돼요. Saying 현금 있어요? to ask a shop's policy asks whether the SHOP has cash, not whether they accept it."],conjugationTips:[],usagePhrases:[{ko:"현금으로 내요",romanization:"hyeongeumeuro naeyo",en:"I pay with cash",note:"(으)로 'by means of' is THE particle for payment method"},{ko:"현금으로 계산해요",romanization:"hyeongeumeuro gyesanhaeyo",en:"I pay by cash",note:"계산하다 'settle/check out' — common at registers"},{ko:"현금만 돼요",romanization:"hyeongeumman dwaeyo",en:"cash only",note:"만 'only' + 되다 'works/is OK'"},{ko:"현금 영수증 해 주세요",romanization:"hyeongeum yeongsujeung hae juseyo",en:"please issue a cash receipt",note:"현금 영수증 is the tax receipt clerks ask about"}],examples:[{ko:"저는 현금으로 낼게요.",romanization:"jeoneun hyeongeumeuro naelgeyo.",en:"I'll pay with cash.",note:"simple: 으로 marks the method, 낼게요 'I'll pay' shows your intention"},{ko:"지금 현금이 좀 모자라요.",romanization:"jigeum hyeongeumi jom mojarayo.",en:"I'm a bit short on cash right now.",note:"everyday: 모자라다 'be short/lacking' is more natural here than 없다"},{ko:"여기는 카드 안 되고 현금만 받아요.",romanization:"yeogineun kadeu an doego hyeongeumman badayo.",en:"They don't take card here, only cash.",note:"real situation: contrasting 카드 vs 현금 with 만 'only'"}],forms:null,irregular:null,level:"A2",cluster:null,chapters:[7]},결제하다:{ko:"결제하다",romanization:"gyeoljekhada",en:"to pay / to process payment",pos:"verb",chapter:"7",ex:{ko:"카드로 결제하면 돼요?",en:"Is it okay to pay by card?",note:"결제하다 is the formal word for payment processing; 내다 or 계산하다 are more casual"},collocations:["카드로 결제하다","결제 되다","결제 안 되다"],nuance:"",explanation:"",shortExplanation:"",commonMistakes:[],conjugationTips:[],usagePhrases:[],examples:[],forms:null,irregular:null,level:"A1",cluster:null,chapters:[7]},영수증:{ko:"영수증",romanization:"yeongsujeung",en:"receipt",pos:"noun",chapter:"7",ex:{ko:"영수증 주세요.",en:"Receipt, please.",note:"Direct N 주세요 request — no extra particles needed"},collocations:["영수증 주세요","영수증 필요해요","영수증 없어요"],nuance:"영수증(領收證) is Sino-Korean — 領 'receive' + 收 'collect' + 證 'proof/certificate' — literally a 'proof of receiving (payment)', the printed slip showing the shop got your money. Distinguish it from 계산서(計算書) 'the bill/check', which is the itemized statement of what you OWE (you read a 계산서 before paying, mostly at restaurants), whereas the 영수증 is issued AFTER you pay as proof. Also keep 영수증 apart from 현금 영수증, a specifically Korean tax-deduction receipt tied to your phone number that clerks ask about separately. Because clerks routinely offer it, you'll constantly hear the polite 영수증 드릴까요? ('shall I give you the receipt?', humble 드리다 raising you the customer), and the practical answer is 네, 주세요 or 아니요, 괜찮아요. The English-speaker pitfall is mislabeling: don't call the receipt a 계산서 — that's the pre-payment bill — and remember a refund hinges on it (환불하려면 영수증이 필요해요). Collocations: 영수증을 주다/받다, 영수증이 필요하다, 영수증을 챙기다 (keep the receipt), 현금 영수증, 영수증을 버리다.",explanation:'영수증 (yeongsujeung) = "receipt". Treat it as a building block that needs a frame: 영수증을 주세요 ("please give me the receipt") shows how it actually behaves. The grammar lives in the particle or ending beside 영수증, so notice that piece as you read, not just the dictionary meaning. Begin from a complete sentence about buying things, checking prices, quantities, and payment options and swap just one element to make it yours.',shortExplanation:'영수증 means "receipt" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Confusing 영수증 (proof-of-payment receipt, given after you pay) with 계산서 (the itemized bill you read before paying, common at restaurants). They sit on opposite sides of the payment.","Answering the clerk's 영수증 드릴까요? with the wrong move. 'Yes please' is 네, 주세요; 'no thanks' is 아니요, 괜찮아요. Saying just 네 without 주세요 can sound abrupt.","Forgetting the receipt is required for refunds. Throwing it away then asking 환불해 주세요 won't work; keep it (영수증을 챙기다) if you might return the item."],conjugationTips:[],usagePhrases:[{ko:"영수증을 주세요",romanization:"yeongsujeungeul juseyo",en:"please give me the receipt",note:"주다 + 세요; the basic checkout request"},{ko:"영수증이 필요해요",romanization:"yeongsujeungi piryohaeyo",en:"I need the receipt",note:"필요하다 'be needed'; the needed thing takes 가/이"},{ko:"영수증을 받아요",romanization:"yeongsujeungeul badayo",en:"I get a receipt",note:"받다 'receive', the customer's side"},{ko:"영수증을 버려요",romanization:"yeongsujeungeul beoryeoyo",en:"I throw away the receipt",note:"버리다 'throw away', a common follow-up action"}],examples:[{ko:"영수증 좀 주세요.",romanization:"yeongsujeung jom juseyo.",en:"Could I have the receipt, please?",note:"simple: 좀 softens the request, particle dropped in speech"},{ko:"환불하려면 영수증이 꼭 필요해요.",romanization:"hwanbulharyeomyeon yeongsujeungi kkok piryohaeyo.",en:"You absolutely need the receipt to get a refund.",note:"everyday: -려면 'if you want to' + 꼭 'definitely' tying 영수증 to 환불"},{ko:"영수증 드릴까요? 아니면 버려 드릴까요?",romanization:"yeongsujeung deurilkkayo? animyeon beoryeo deurilkkayo?",en:"Would you like the receipt, or shall I throw it away for you?",note:"real situation: the exact clerk's question, with humble 드리다 'give'"}],forms:null,irregular:null,level:"A2",cluster:null,chapters:[7]},주문하다:{ko:"주문하다",romanization:"jumunhada",en:"to order (food/items)",pos:"verb",chapter:"7·8",ex:{ko:"뭐 주문하고 싶어요?",en:"What do you want to order?",note:"주문하 + 고 싶어요 — essential restaurant phrase; 주문하다 is a 하다 verb"},collocations:["주문하고 싶어요","주문할 수 있어요","주문 못 해요","지금 주문해요"],nuance:"주문하다 is used for ordering food, drinks, products, or services.",explanation:'주문하다 (jumunhada) means "to order". Start from the polite form 주문해요 — it is safe with almost anyone, so use it before the dictionary form 주문하다. A strong first sentence is 음식을 주문해요 ("order food."); once that feels natural, swap the noun, place, or time and reuse the verb everywhere. Korean changes the ending rather than the word, so the same 주문하다 also becomes 주문하고 싶어요 (want), 주문할 수 있어요 (can), and 주문 못 해요 (cannot). Say one true sentence about ordering food, explaining food restrictions, and asking what to eat together, then bend it.',shortExplanation:'주문하다 means "to order" and is practiced through polite conversation forms.',commonMistakes:["Do not use the dictionary form 주문하다 as a complete polite sentence.","Use 주문해요 as the default until you know the relationship is casual."],conjugationTips:[{title:"ㄹ / 을 — can & will",body:'To say "can" or the future, attach ㄹ/을 to the stem: a vowel-final stem takes ㄹ and a consonant-final stem takes 을. 주문하다 becomes 주문할 수 있어요 ("can") and 주문할 거예요 ("will"). That is why 가다 → 갈 수 있어요 (not 가을), while 먹다 → 먹을 수 있어요. The same ㄹ/을 choice drives 거예요 and the noun-describing form.'}],usagePhrases:[{ko:"주문해요",romanization:"jumunhaeyo",en:"I order.",note:"Safe polite present form."},{ko:"주문 안 해요",romanization:"jumun an haeyo",en:"I do not order.",note:"Short everyday negative."},{ko:"주문하고 싶어요",romanization:"jumunhago sipeoyo",en:"I want to order.",note:"Useful for choices and plans."},{ko:"주문할 수 있어요",romanization:"jumunhal su isseoyo",en:"I can order.",note:"Ability or possibility."},{ko:"주문해야 해요",romanization:"jumunhaeya haeyo",en:"I have to order.",note:"Requirement or obligation."},{ko:"음식을 주문해요",romanization:"eumsigeul jumunhaeyo",en:"order food.",note:"Restaurant phrase."}],examples:[{ko:"음식을 주문하고 싶어요.",romanization:"eumsigeul jumunhago sipeoyo.",en:"I want to order food.",note:"Restaurant."},{ko:"아직 주문 안 했어요.",romanization:"ajik jumun an haesseoyo.",en:"I have not ordered yet.",note:"Status."},{ko:"같이 주문할까요?",romanization:"gachi jumunhalkkayo?",en:"Shall we order together?",note:"Suggestion."}],forms:{dictionary:"주문하다",casualPresent:"주문해",politePresent:"주문해요",formalPresent:"주문합니다",negative:"주문 안 해요",past:"주문했어요",future:"주문할 거예요",want:"주문하고 싶어요",can:"주문할 수 있어요",cannot:"주문 못 해요",must:"주문해야 해요",dontHaveTo:"주문 안 해도 돼요",pleaseDo:"주문해 주세요",pleaseDont:"주문하지 마세요",shallWe:"주문할까요?"},irregular:null,level:"A1",cluster:null,chapters:[7,8]},메뉴:{ko:"메뉴",romanization:"menyu",en:"menu",pos:"noun",chapter:"7",ex:{ko:"메뉴 주세요.",en:"Menu, please.",note:"메뉴 is a loanword from English; in practice many Korean cafés have menus only on boards, so this is more useful than it sounds"},collocations:["메뉴 주세요","메뉴 보다","메뉴 있어요?"],nuance:"메뉴 (loanword from 'menu') carries two senses Koreans switch between freely: (1) the printed list of offerings, and (2) an individual dish/order — so 무슨 메뉴 먹을까? means 'which dish shall we get?', and 메뉴 정했어? means 'have you decided what to order?'. When you specifically mean the physical card you hand over, Koreans often say 메뉴판 (menu-board) to disambiguate. The dish sense overlaps with 음식(food in general) and 요리(a cooked dish), but 메뉴 frames it as a selectable option on offer. Common partners: 메뉴를 정하다/고르다(decide/choose a dish), 메뉴가 다양하다(varied), 오늘의 메뉴(today's special). The English-speaker pitfall is locking 메뉴 to the printed-list meaning only, then being confused by 이 집은 메뉴가 맛있어요 — which praises the dishes, not the paper.",explanation:'메뉴 (menyu) = "menu; a menu item / dish". Treat it as a building block that needs a frame: 메뉴를 봐요 ("I look at the menu") shows how it actually behaves. The grammar lives in the particle or ending beside 메뉴, so notice that piece as you read, not just the dictionary meaning. Begin from a complete sentence about ordering food, explaining food restrictions, and asking what to eat together and swap just one element to make it yours.',shortExplanation:'메뉴 means "menu; a menu item / dish" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Thinking 메뉴 only means the printed list — it also means an individual dish, e.g. 이 메뉴 맛있어요 = 'this dish is tasty'.","Asking for the physical card as just 메뉴 when clarity matters — say 메뉴판 (the menu board/card).","Pairing 메뉴 with 마시다/읽다 oddly — you 보다 (look at) a menu and 정하다/고르다 (decide/choose) a dish."],conjugationTips:[],usagePhrases:[{ko:"메뉴를 봐요",romanization:"menyureul bwayo",en:"I look at the menu",note:"보다 = look at; 봐요 in 요-form"},{ko:"메뉴판 좀 주세요",romanization:"menyupan jom juseyo",en:"please give me the menu (board)",note:"메뉴판 = the physical menu card; 주세요 polite request"},{ko:"메뉴가 많아요",romanization:"menyuga manayo",en:"there are many menu items / choices",note:"subject marker 가; here 메뉴 = the dishes available"},{ko:"오늘의 메뉴",romanization:"oneurui menyu",en:"today's special / today's dish",note:"메뉴 = a specific offered dish, not the list"}],examples:[{ko:"메뉴 좀 보여 주세요.",romanization:"menyu jom boyeo juseyo.",en:"Please show me the menu.",note:"simple polite request at a restaurant"},{ko:"여기 제일 잘 나가는 메뉴가 뭐예요?",romanization:"yeogi jeil jal naganeun menyuga mwoyeyo?",en:"What's the most popular dish here?",note:"everyday ordering line; 메뉴 = a dish, 잘 나가다 = sell well"},{ko:"메뉴 정하기 전에 메뉴판부터 다시 볼까요?",romanization:"menyu jeonghagi jeone menyupanbuteo dasi bolkkayo?",en:"Before we decide on a dish, shall we look at the menu card again?",note:"real-situation line using both senses: dish vs physical menu"}],forms:null,irregular:null,level:"A2",cluster:null,chapters:[7]},하나:{ko:"하나",romanization:"hana",en:"one (native Korean number)",pos:"number",chapter:"7·20",ex:{ko:"아메리카노 하나 주세요.",en:"One Americano, please.",note:"Quantities in ordering use native Korean numbers (하나, 둘, 셋), not Sino-Korean (일, 이, 삼)"},collocations:["하나 주세요","하나만 주세요","한 개"],nuance:'하나 is the native-Korean (고유어) word for "one," the counting system Koreans use for tangible things, people, age, and the clock hour — as opposed to its Sino-Korean twin 일, which rules dates, money, minutes, and phone numbers. The single biggest fact to internalize: when 하나 sits directly in front of a counter (개, 명, 시, 살, 마리), it loses its last syllable and becomes 한 — 한 개, 한 명, 한 시 — while the full 하나 only stands alone (as in counting "하나, 둘" or taking a particle, 하나만). English speakers reliably trip here by saying 하나 개 or, worse, importing the Sino number and saying 일 개; both sound clearly wrong to a Korean ear. There is no hanja because it is purely native, so do not look for one.',explanation:'하나 (hana) means "one (native number)". Learn it inside a frame, not as a bare word: a useful first chunk is 한 개 ("one item"). In Korean the particle or ending next to 하나 signals its job — topic, subject, object, place, time, method, or description — so read the examples for the small piece beside it. Start with one real sentence about basic everyday communication, then change a single part.',shortExplanation:'하나 means "one (native number)" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Saying 하나 개 — before any counter the form must contract to 한, so it is 한 개. The full 하나 is only used standalone or with a particle.","Using the Sino 일 for the hour or for objects (일 시, 일 개). The clock hour and counting things are native territory, so it must be 한 시, 한 개.","Writing it solid as 한개 — Korean keeps a space between the number-word and the counter: 한 개."],conjugationTips:[],usagePhrases:[{ko:"한 개",romanization:"han gae",en:"one item",note:"하나 drops its 나 to become 한 right before a counter"},{ko:"한 시",romanization:"han si",en:"one o'clock",note:"the HOUR is always native: 한 시, never 일 시"},{ko:"한 명",romanization:"han myeong",en:"one person",note:"명 is the plain counter for people; 한 분 is the polite version"},{ko:"하나만",romanization:"hanaman",en:"just one",note:"the full standalone 하나 takes particles like 만, 도, 를"}],examples:[{ko:"하나, 둘, 셋!",romanization:"hana, dul, set!",en:"One, two, three!",note:"counting out loud (a countdown) uses the bare standalone forms"},{ko:"사과 한 개만 주세요.",romanization:"sagwa han gaeman juseyo.",en:"Please give me just one apple.",note:"before the counter 개, 하나 must shrink to 한"},{ko:"회의는 오후 한 시에 시작해요.",romanization:"hoeuineun ohu han sie sijakaeyo.",en:"The meeting starts at one in the afternoon.",note:"real scheduling: the clock hour is native (한 시) but you would say the minutes in Sino"}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[7,20]},좀:{ko:"좀",romanization:"jom",en:"a bit / please (softener)",pos:"adverb",chapter:"7·9",ex:{ko:"좀 도와주세요.",en:"Please help me (softened).",note:"좀 before a request softens it — like 'kindly' or 'if you could'; almost always present in polite Korean requests"},collocations:["좀 도와주세요","좀 기다려 주세요","좀 더 주세요"],nuance:"좀 is the contracted, spoken form of 조금 and is everywhere in daily conversation. Its key second life — the part that trips up English speakers — is as a request softener: in 물 좀 주세요 or 좀 도와주세요, 좀 is not measuring a 'little' amount at all but functioning like 'please/if you would', taking the bluntness off a command. So 물 주세요 is grammatically fine but can feel abrupt, whereas 물 좀 주세요 sounds warm and natural. Compared with the full 조금, 좀 is purely conversational and a touch more casual; in formal writing or stiff announcements you revert to 조금 or a fuller polite request form. Collocates constantly with request verbs (좀 주세요, 좀 해 주세요, 좀 보여 주세요) and with mild complaints (좀 춥다, 좀 그렇다). The pitfall is over-literal reading: don't try to translate the 'softener' 좀 as 'a little', and don't drop it from requests — Koreans add it precisely to sound polite.",explanation:`"a bit, a little (casual); please" is 좀 (jom). The word itself is easy; what matters is the company it keeps, like 좀 비싸요 ("It's a bit pricey"). Watch the particle attached to 좀 in each example — that little marker, not the word, tells you whether it is the topic, the subject, the object, or a place. Copy one full sentence about basic everyday communication first, then vary one word.`,shortExplanation:'좀 means "a bit, a little (casual); please" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Thinking 좀 always means 'a little': in 좀 도와주세요 it works as a politeness softener ('please'), not a quantity. Translating it as 'help me a little' misses the tone.","Dropping 좀 from requests to be 'cleaner': bare commands like 물 주세요 can sound blunt; native speakers add 좀 (물 좀 주세요) to soften them.","Using 좀 in formal writing or speeches, where it reads as too casual; switch to 조금 or a full polite form there."],conjugationTips:[],usagePhrases:[{ko:"좀 비싸요",romanization:"jom bissayo",en:"It's a bit pricey",note:"The short, spoken reduction of 조금"},{ko:"좀 도와주세요",romanization:"jom dowajuseyo",en:"Please help me a little",note:"Here 좀 is a softener, not really an amount, like a gentle 'please'"},{ko:"이거 좀 주세요",romanization:"igeo jom juseyo",en:"Could I have this, please",note:"Extremely common when ordering or asking for things at a shop"},{ko:"저기요, 잠깐만요",romanization:"jeogiyo, jamkkanmanyo",en:"Excuse me, just a sec",note:"잠깐만요 buys a moment of time; pairs naturally with 좀 in requests"}],examples:[{ko:"여기 좀 추워요.",romanization:"yeogi jom chuwoyo.",en:"It's a bit cold in here.",note:"좀 makes the comment sound soft and offhand rather than a complaint"},{ko:"물 좀 주세요.",romanization:"mul jom juseyo.",en:"Some water, please.",note:"Slipping in 좀 makes the request friendlier and more natural than 물 주세요"},{ko:"오늘은 좀 바빠요.",romanization:"oneureun jom bappayo.",en:"I'm a little busy today.",note:"좀 cushions a refusal so it lands gently"}],forms:null,irregular:null,level:"A2",cluster:{title:"조금 vs 좀 vs 약간",rule:'For real amounts all three overlap — 좀 is simply the spoken contraction of 조금, and 약간 is the cooler, more written "slightly". The deciding fact is that only 좀 has a second life as a request softener, where it means "please / if you would" and not "a little" at all (물 좀 주세요).',members:[{ko:"조금",en:"a little, a bit, a few",romanization:"jogeum",when:"stating a small amount clearly",hint:"the full form — speech and writing alike",example:{ko:"조금만 기다려 주세요.",en:"Please wait just a little."},self:!1},{ko:"좀",en:"a bit, a little (casual); please",romanization:"jom",when:"everyday speech; softening requests",hint:'spoken 조금 — and the "please" softener',example:{ko:"물 좀 주세요.",en:"Could I get some water, please?"},self:!0},{ko:"약간",en:"a little, a bit",romanization:"yakgan",when:"slightly, in a measured way",hint:'the cooler, more written "slightly"',example:{ko:"이거 약간 매워요.",en:"This is slightly spicy."},self:!1}]},chapters:[7,9]},더:{ko:"더",romanization:"deo",en:"more",pos:"adverb",chapter:"7·22",ex:{ko:"물 좀 더 주세요.",en:"A little more water, please.",note:"더 = more quantity; often combined with 좀 for a polite, natural request for a refill"},collocations:["더 주세요","좀 더","더 있어요?"],nuance:"더 is the basic comparative marker meaning 'more,' and crucially Korean has no '-er/more...than' suffix — you simply put 더 before the adjective and (optionally) mark the standard of comparison with the particle 보다: A가 B보다 더 크다 = 'A is bigger than B.' Its direct antonym is 덜 ('less'). A common booster is 훨씬 ('by far, much'), which stacks in front: 훨씬 더 좋다 = 'much better.' Watch two set phrases: 더 이상 + negative = 'no longer / not anymore' (더 이상 못 참아 = 'I can't take it anymore'), and 더 ~ -ㄹ수록 patterns for 'the more...'. The English-speaker pitfall: learners often drop 더 entirely because they expect the adjective itself to change form ('big' → 'bigger'), but 크다 never inflects for comparison — without 더 the sentence just says 'is big,' not 'is bigger.' Another trap is the 보다 direction: 보다 attaches to the thing you compare AGAINST (the 'than' item), so '내가 너보다 커' = 'I'm taller than you,' which feels backwards to English ears. Also don't confuse spoken 더 with the homophone-ish 덜; they are opposites.",explanation:'더 (deo) means "more". Learn it inside a frame, not as a bare word: a useful first chunk is 더 주세요. ("Please give me more."). In Korean the particle or ending next to 더 signals its job — topic, subject, object, place, time, method, or description — so read the examples for the small piece beside it. Start with one real sentence about basic everyday communication, then change a single part.',shortExplanation:'더 means "more" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Omitting 더 and expecting the adjective to inflect like English 'bigger'; 크다 doesn't change form — you must add 더: 더 커요.","Attaching 보다 to the wrong noun; 보다 marks the standard you compare against ('than X'), so put it on X: 사과가 배보다 더 싸요 = 'apples are cheaper than pears.'","Confusing 더 (more) with 덜 (less) in fast speech; they are exact opposites, so 덜 비싸요 = 'less expensive,' the reverse of 더 비싸요."],conjugationTips:[],usagePhrases:[{ko:"더 주세요.",romanization:"deo juseyo.",en:"Please give me more.",note:"더 before a verb to request a greater amount"},{ko:"더 좋아요.",romanization:"deo joayo.",en:"It is better.",note:"더 + adjective forms the comparative"},{ko:"조금 더",romanization:"jogeum deo",en:"a little more",note:"Pairs with 조금 to soften the increase"},{ko:"더 이상 안 해요.",romanization:"deo isang an haeyo.",en:"I won't do it anymore.",note:"Set phrase 더 이상 + negative = 'no longer'"}],examples:[{ko:"이 가방이 더 비싸요.",romanization:"i gabangi deo bissayo.",en:"This bag is more expensive.",note:"Basic: 더 + adjective makes the comparison"},{ko:"조금 더 먹고 싶어요.",romanization:"jogeum deo meokgo sipeoyo.",en:"I want to eat a little more.",note:"Everyday: 조금 더 softens 'more' politely"},{ko:"어제보다 오늘이 훨씬 더 더워요.",romanization:"eojeboda oneuri hwolssin deo deowoyo.",en:"Today is much hotter than yesterday.",note:"Real situation: 보다 marks the standard, 훨씬 stacks before 더 for 'much more'"}],forms:null,irregular:null,level:"A2",cluster:null,chapters:[7,22]},"됩니다 / 돼요":{ko:"됩니다 / 돼요",romanization:"doemnida / dwaeyo",en:"it's okay / it works / available",pos:"verb",chapter:"7",ex:{ko:"카드 돼요?",en:"Is card okay?",note:"카드 돼요? is a spoken shortcut — grammatically incomplete but perfectly natural in shops"},collocations:["카드 돼요?","현금만 돼요","안 돼요"],nuance:"",explanation:"",shortExplanation:"",commonMistakes:[],conjugationTips:[],usagePhrases:[],examples:[],forms:null,irregular:null,level:"A1",cluster:null,chapters:[7]},"이거 / 이것":{ko:"이거 / 이것",romanization:"igeo / igeot",en:"this (one)",pos:"pronoun",chapter:"7",ex:{ko:"이것도 주세요.",en:"This too, please.",note:"이거 is the spoken form, 이것 is written/formal; both work at a café or shop counter"},collocations:["이거 주세요","이것도 주세요","이것만 주세요"],nuance:"이거 is the casual, mouth-friendly version of 이것 — 'this thing' near the speaker — and it is overwhelmingly the form you HEAR and USE in real life: shopping, ordering food, pointing things out. Meaning is identical to 이것; the only difference is register, with 이거 being conversational and 이것 belonging to writing or formal speech. It contracts naturally with particles into 이게 (subject), 이걸 (object), 이건 (topic), and 이걸로 ('with this'). The number-one English-speaker error is grafting English particle habits onto it: 이거가 sounds clumsy because Koreans fuse it to 이게, and the same goes for 이거를 → 이걸. Like 이것, it cannot sit before a noun (that job belongs to 이: 이 가방), and it should never label a person.",explanation:'이거 (igeo) = "this (thing) — casual". Treat it as a building block that needs a frame: 이거 ("this thing (casual)") shows how it actually behaves. The grammar lives in the particle or ending beside 이거, so notice that piece as you read, not just the dictionary meaning. Begin from a complete sentence about basic everyday communication and swap just one element to make it yours.',shortExplanation:'이거 means "this (thing) — casual" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Saying 이거가 for the subject — Koreans contract 이거 + 가 to 이게.","Writing 이거 in an essay, report, or formal notice where 이것 is expected.","Using 이거 to refer to a person standing nearby; for people use 이분/이 사람, since 거(것) means 'thing.'"],conjugationTips:[],usagePhrases:[{ko:"이거",romanization:"igeo",en:"this thing (casual)",note:"Everyday spoken contraction of 이것. The form you actually use when shopping or chatting."},{ko:"이게",romanization:"ige",en:"this (as subject)",note:"이거 + 가 fused into 이게. You almost never say 이거가."},{ko:"이걸",romanization:"igeol",en:"this (as object)",note:"이거 + 를 fused into 이걸. Smoother than the full 이거를."},{ko:"이거 주세요",romanization:"igeo juseyo",en:"I'll take this",note:"이거 + 주세요. The default way to order or buy a nearby item."}],examples:[{ko:"이거 뭐예요?",romanization:"igeo mwoyeyo?",en:"What's this?",note:"Bare 이거 with no particle — totally natural in casual speech."},{ko:"이거 진짜 맛있어요!",romanization:"igeo jinjja masisseoyo!",en:"This is really tasty!",note:"이거 stands in for 'this dish/thing' right in front of you."},{ko:"이게 더 싸니까 이걸로 할게요.",romanization:"ige deo ssanikka igeollo halgeyo.",en:"This one's cheaper, so I'll go with this.",note:"Shows 이게 (subject) and 이걸로 (이거 + 로, 'with/by this') in one breath."}],forms:null,irregular:null,level:"A2",cluster:null,chapters:[7]},포장:{ko:"포장",romanization:"pojang",en:"takeout / to go",pos:"noun / verb stem",chapter:"7",ex:{ko:"포장해 주세요.",en:"To go, please.",note:"포장 (packing) = takeout in Korean. 포장이요? is how staff ask if you want it to go"},collocations:["포장해 주세요","포장이에요","포장 돼요?"],nuance:"",explanation:"",shortExplanation:"",commonMistakes:[],conjugationTips:[],usagePhrases:[],examples:[],forms:null,irregular:null,level:"A1",cluster:null,chapters:[7]},추천:{ko:"추천",romanization:"chucheon",en:"recommendation",pos:"noun",chapter:"7",ex:{ko:"추천 메뉴가 뭐예요?",en:"What's the recommended menu item?",note:"추천 없어요? or 추천 메뉴요? are very natural ways to ask a café or restaurant what's good"},collocations:["추천하다","추천 메뉴","추천해 주세요"],nuance:"",explanation:"",shortExplanation:"",commonMistakes:[],conjugationTips:[],usagePhrases:[],examples:[],forms:null,irregular:null,level:"A1",cluster:null,chapters:[7]},맵다:{ko:"맵다",romanization:"maepda",en:"spicy / hot (taste)",pos:"adjective",chapter:"7·8·41·52",ex:{ko:"이 음식은 너무 매워서 못 먹어요.",en:"This food is too spicy so I can't eat it.",note:"맵다 is a ㅂ-irregular adjective: 매워서 (not 맵어서) — important for describing food limitations"},collocations:["너무 맵다","맵지 않다","매운 음식","맵게 하다"],nuance:"맵다 is ㅂ irregular: 매워요, 매운 음식. It is especially useful for food restrictions, because 매운 음식은 못 먹어요 is a survival sentence.",explanation:'"to be spicy" is 맵다 (maepda). The word itself is easy; what matters is the company it keeps, like 매워요 ("It is spicy."). Watch the particle attached to 맵다 in each example — that little marker, not the word, tells you whether it is the topic, the subject, the object, or a place. Copy one full sentence about ordering food, explaining food restrictions, and asking what to eat together first, then vary one word.',shortExplanation:'맵다 means "to be spicy" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","맵다 becomes 매워요, not 맵어요."],conjugationTips:[{title:"Describing a noun: ㄴ/은 vs ㄹ/을",body:'To put 맵다 in front of a noun, use the ㄴ/은 form for how something is right now: 매운 것 ("a spicy thing"). The ㄹ/을 form points to something that will or might become that way later. So 뜨거운 물 is water that is hot now, but 뜨거울 물 is water that will be hot — same adjective, different time feeling. For everyday description, reach for the ㄴ/은 form.'},{title:"Irregular stem: ㅂ → 우",body:"맵다 is a ㅂ-irregular word. Before a vowel ending the final ㅂ turns into 우, so the polite form is 매워요 — not a literal ㅂ + 어요. The same change gives the noun-describing form (맵다 → 매운, 쉽다 → 쉬운). Anchor on 매워요 and build the rest from it."}],usagePhrases:[{ko:"매워요",romanization:"maewoyo",en:"It is spicy.",note:"ㅂ irregular."},{ko:"매운 음식",romanization:"maeun eumsik",en:"spicy food.",note:"Before noun."},{ko:"맵지 않아요",romanization:"maepji anayo",en:"It is not spicy.",note:"Careful negative."},{ko:"매운 음식은 못 먹어요",romanization:"maeun eumsigeun mon meogeoyo",en:"I cannot eat spicy food.",note:"Restriction."}],examples:[{ko:"이 음식은 매워요.",romanization:"i eumsigeun maewoyo.",en:"This food is spicy.",note:"Topic."},{ko:"매운 음식은 못 먹어요.",romanization:"maeun eumsigeun mon meogeoyo.",en:"I cannot eat spicy food.",note:"Restriction."},{ko:"맵지 않아요.",romanization:"maepji anayo.",en:"It is not spicy.",note:"Negative."}],forms:null,irregular:"ㅂ irregular",level:"A1",cluster:null,chapters:[7,8,41,52]},하다:{ko:"하다",romanization:"hada",en:"to do",pos:"verb",chapter:"8·17·18·45",ex:{ko:"한국어를 잘하고 싶어요.",en:"I want to get better at Korean.",note:"잘하 + 고 싶어요 — long-term aspiration; note that 못 for 하다 = 못 해요, NOT 못 하해요"},collocations:["하고 싶어요","할 수 있어요","못 해요","잘하다"],nuance:"하다 combines with many nouns: 공부하다, 일하다, 운동하다. It is one of the most important Korean verbs.",explanation:'하다 (hada) means "to do". Start from the polite form 해요 — it is safe with almost anyone, so use it before the dictionary form 하다. A strong first sentence is 숙제를 해요 ("do homework."); once that feels natural, swap the noun, place, or time and reuse the verb everywhere. Korean changes the ending rather than the word, so the same 하다 also becomes 하고 싶어요 (want), 할 수 있어요 (can), and 못 해요 (cannot). Say one true sentence about talking about work, schedules, tasks, and obligations, then bend it.',shortExplanation:'하다 means "to do" and is practiced through polite conversation forms.',commonMistakes:["Do not use the dictionary form 하다 as a complete polite sentence.","Use 해요 as the default until you know the relationship is casual."],conjugationTips:[{title:"ㄹ / 을 — can & will",body:'To say "can" or the future, attach ㄹ/을 to the stem: a vowel-final stem takes ㄹ and a consonant-final stem takes 을. 하다 becomes 할 수 있어요 ("can") and 할 거예요 ("will"). That is why 가다 → 갈 수 있어요 (not 가을), while 먹다 → 먹을 수 있어요. The same ㄹ/을 choice drives 거예요 and the noun-describing form.'}],usagePhrases:[{ko:"해요",romanization:"haeyo",en:"I do.",note:"Safe polite present form."},{ko:"안 해요",romanization:"an haeyo",en:"I do not do.",note:"Short everyday negative."},{ko:"하고 싶어요",romanization:"hago sipeoyo",en:"I want to do.",note:"Useful for choices and plans."},{ko:"할 수 있어요",romanization:"hal su isseoyo",en:"I can do.",note:"Ability or possibility."},{ko:"해야 해요",romanization:"haeya haeyo",en:"I have to do.",note:"Requirement or obligation."},{ko:"숙제를 해요",romanization:"sukjereul haeyo",en:"do homework.",note:"Noun + 하다 pattern."}],examples:[{ko:"지금 해요.",romanization:"jigeum haeyo.",en:"I do it now.",note:"Simple sentence."},{ko:"제가 할 수 있어요.",romanization:"jega hal su isseoyo.",en:"I can do it.",note:"Ability."},{ko:"안 해도 돼요.",romanization:"an haedo dwaeyo.",en:"You do not have to do it.",note:"Very useful permission."}],forms:{dictionary:"하다",casualPresent:"해",politePresent:"해요",formalPresent:"합니다",negative:"안 해요",past:"했어요",future:"할 거예요",want:"하고 싶어요",can:"할 수 있어요",cannot:"못 해요",must:"해야 해요",dontHaveTo:"안 해도 돼요",pleaseDo:"해 주세요",pleaseDont:"하지 마세요",shallWe:"할까요?"},irregular:null,level:"A1",cluster:null,chapters:[8,17,18,45]},"먹을 수 있다":{ko:"먹을 수 있다",romanization:"meogeul su itda",en:"to be able to eat / can eat",pos:"verb phrase",chapter:"8",ex:{ko:"저는 매운 음식을 먹을 수 있어요.",en:"I can eat spicy food.",note:"먹 (consonant ending stem) + 을 수 있어요 — consonant stems take 을 수, vowel stems take ㄹ 수"},collocations:["먹을 수 있다","먹을 수 없다","무엇을 먹을 수 있어요?"],nuance:"",explanation:"",shortExplanation:"",commonMistakes:[],conjugationTips:[],usagePhrases:[],examples:[],forms:null,irregular:null,level:"A1",cluster:null,chapters:[8]},괜찮다:{ko:"괜찮다",romanization:"gwaenchanta",en:"to be okay / fine / alright",pos:"adjective",chapter:"8·11·24·25",ex:{ko:"괜찮으면 같이 가요.",en:"If it's okay with you, let's go together.",note:"괜찮다 (consonant-final 다 after ㅎ drop → 괜찮 + 으면): switch track — only proceed together if condition of okayness is met"},collocations:["괜찮으면 가요","괜찮아요?","다 괜찮아요"],nuance:"괜찮아요 can mean okay, fine, no thanks, or not bad. Context decides.",explanation:'괜찮다 (gwaenchanta) means "to be okay; to be fine". Learn it inside a frame, not as a bare word: a useful first chunk is 괜찮아요. ("It is okay / I am okay."). In Korean the particle or ending next to 괜찮다 signals its job — topic, subject, object, place, time, method, or description — so read the examples for the small piece beside it. Start with one real sentence about basic everyday communication, then change a single part.',shortExplanation:'괜찮다 means "to be okay; to be fine" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Do not assume 괜찮아요 always means yes. After an offer, 아니요, 괜찮아요 can mean no thanks.","For a direct recommendation, use 좋아요 or 추천해요; 괜찮아요 can sound milder, like 'it's okay.'"],conjugationTips:[],usagePhrases:[{ko:"괜찮아요.",romanization:"gwaenchanayo.",en:"It is okay / I am okay.",note:"Common response to offers, suggestions, and concern."},{ko:"이 색 괜찮아요?",romanization:"i saek gwaenchanayo?",en:"Is this color okay?",note:"Useful when trying or choosing."}],examples:[{ko:"사이즈가 괜찮으면 이걸로 할게요.",romanization:"saijeuga gwaenchaneumyeon igeollo halgeyo.",en:"If the size is okay, I will take this one.",note:"Common shop decision frame."}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[8,11,24,25]},알다:{ko:"알다",romanization:"alda",en:"to know",pos:"verb",chapter:"8·41·59·60·61",ex:{ko:"한국어를 조금 알아요.",en:"I know a little Korean.",note:"알다 is ㄹ-irregular: 알 + 아요 = 알아요. For ability: 알 수 있어요 (stem already ends in ㄹ so no extra ㄹ added)"},collocations:["알아요","알 수 있어요","못 알아요","알겠어요"],nuance:"알다 means 'to know / be aware of / be acquainted with' and takes the object marker 을/를: 저 사람을 알아요. It is a ㄹ-irregular verb: the stem ㄹ drops before ㅂ, ㄴ, and the honorific ㅅ, giving 압니다 (not 알습니다) and 아세요 (not 알으세요), but the ㄹ stays before vowel endings, so the everyday polite form is 알아요. Two contrasts are essential. First, its opposite is not the negative 안 알아요 — that is wrong — but the separate verb 모르다, so 'I don't know' is 몰라요. Second, 알다 vs 알겠다: 알아요 claims knowledge you already hold ('I know that'), while 알겠어요 signals you have just understood or accepted something ('I see / got it / will do'), which is why a polite 'understood' is 알겠습니다, never 압니다. The English-speaker pitfall is twofold: forming 'don't know' as 안 알아요 instead of 몰라요, and keeping the ㄹ to say 알습니다 instead of 압니다.",explanation:'"to know" in Korean is 알다 (alda). In real conversation you will lean on the polite form 알아요, so make that your default and leave the bare dictionary form 알다 for study notes. Grow outward from one concrete line — 저 사람을 알아요 ("I know that person") — then reshape the same stem into 알고 싶어요 (desire), 알 수 있어요 (ability), and 모르겠어요 (a real limit) as the moment needs. The stem stays put; only the ending moves.',shortExplanation:'알다 means "to know" and is practiced through polite conversation forms.',commonMistakes:["Do not use the dictionary form 알다 as a complete polite sentence.","Use 알아요 as the default until you know the relationship is casual.","Saying 안 알아요 for 'I don't know' — Korean uses the dedicated verb 모르다, so the correct form is 몰라요.","Keeping the ㄹ before consonant endings and saying 알습니다 / 알으세요 — as a ㄹ-irregular it drops: 압니다 and 아세요.","Using 알아요 to say 'understood/got it' — that claims prior knowledge; to acknowledge something new, say 알겠어요 (formal 알겠습니다)."],conjugationTips:[{title:"ㄹ / 을 — can & will",body:'To say "can" or the future, attach ㄹ/을 to the stem: a vowel-final stem takes ㄹ and a consonant-final stem takes 을. 알다 becomes 알 수 있어요 ("can") and 알 거예요 ("will"). That is why 가다 → 갈 수 있어요 (not 가을), while 먹다 → 먹을 수 있어요. The same ㄹ/을 choice drives 거예요 and the noun-describing form.'},{title:"Irregular stem: ㄹ",body:"알다 is a ㄹ-stem word. The ㄹ drops before ㄴ/ㅂ/ㅅ endings: 살다 → 삽니다 (formal), 사는 (describing a noun), 사세요 (honorific). Before a vowel the ㄹ stays: 알아요."}],usagePhrases:[{ko:"알아요",romanization:"arayo",en:"I know.",note:"Safe polite present form."},{ko:"몰라요",romanization:"mollayo",en:"I do not know.",note:"Short everyday negative."},{ko:"알고 싶어요",romanization:"algo sipeoyo",en:"I want to know.",note:"Useful for choices and plans."},{ko:"알 수 있어요",romanization:"al su isseoyo",en:"I can know.",note:"Ability or possibility."},{ko:"알아야 해요",romanization:"araya haeyo",en:"I have to know.",note:"Requirement or obligation."},{ko:"저 사람을 알아요",romanization:"jeo sarameul arayo",en:"I know that person",note:"the thing/person known takes 을/를"}],examples:[{ko:"저는 그 식당을 잘 알아요.",romanization:"jeoneun geu sikdangeul jal arayo.",en:"I know that restaurant well.",note:"잘 알아요 = solid familiarity; object 를 on 식당"},{ko:"이 단어 뜻을 알아요?",romanization:"i daneo tteuseul arayo?",en:"Do you know what this word means?",note:"rising-intonation question; 뜻을 알다 'know the meaning'"},{ko:"아, 이제 알겠어요. 가르쳐 줘서 고마워요.",romanization:"a, ije algesseoyo. gareuchyeo jwoseo gomawoyo.",en:"Ah, I get it now. Thanks for explaining.",note:"real moment of understanding uses 알겠어요, not 알아요"}],forms:{dictionary:"알다",casualPresent:"알아",politePresent:"알아요",formalPresent:"압니다",negative:"몰라요",past:"알았어요",future:"알 거예요",want:"알고 싶어요",can:"알 수 있어요",cannot:"모르겠어요",must:"알아야 해요",dontHaveTo:"몰라도 돼요",pleaseDo:"알아 주세요",pleaseDont:"알려고 하지 마세요",shallWe:"알까요?"},irregular:"ㄹ irregular",level:"A2",cluster:{title:"알다 vs 알아보다 vs 알아듣다",rule:"알다 is having the information already; 알아보다 is going out to find it (or making out a face you half-recognize); 알아듣다 is catching the words someone just said to you. If your problem is your ears, it's 알아듣다.",members:[{ko:"알다",en:"to know",romanization:"alda",when:"you already have the information",hint:"simply having the information",example:{ko:"저 사람을 알아요.",en:"I know that person."},self:!0},{ko:"알아보다",en:"to look into / recognize",romanization:"araboda",when:"checking something out, recognizing a face",hint:"going to find out, or recognizing by sight",example:{ko:"제가 가격을 알아볼게요.",en:"I'll look into the price."},self:!1},{ko:"알아듣다",en:"to understand (by hearing) / catch what is said",romanization:"aradeutda",when:"you missed what someone said",hint:"catching spoken words by ear",example:{ko:"죄송해요, 못 알아들었어요.",en:"Sorry, I didn't catch that."},self:!1}]},chapters:[8,41,59,60,61]},쉬다:{ko:"쉬다",romanization:"swida",en:"to rest / take a break",pos:"verb",chapter:"8·27·29·48·60",ex:{ko:"오늘은 좀 쉬고 싶어요.",en:"I want to rest a bit today.",note:"쉬 + 고 싶어요 — expressing the very human desire for rest; common in daily conversation"},collocations:["쉬고 싶어요","쉴 수 있어요","잠깐 쉬어요","오늘 쉬어요"],nuance:"쉬다 is used for taking a break, resting, or being off work/school.",explanation:'"to rest" in Korean is 쉬다 (swida). In real conversation you will lean on the polite form 쉬어요, so make that your default and leave the bare dictionary form 쉬다 for study notes. Grow outward from one concrete line — 좀 쉬어요 ("rest a little.") — then reshape the same stem into 쉬고 싶어요 (desire), 쉴 수 있어요 (ability), and 못 쉬어요 (a real limit) as the moment needs. The stem stays put; only the ending moves.',shortExplanation:'쉬다 means "to rest" and is practiced through polite conversation forms.',commonMistakes:["Do not use the dictionary form 쉬다 as a complete polite sentence.","Use 쉬어요 as the default until you know the relationship is casual."],conjugationTips:[{title:"ㄹ / 을 — can & will",body:'To say "can" or the future, attach ㄹ/을 to the stem: a vowel-final stem takes ㄹ and a consonant-final stem takes 을. 쉬다 becomes 쉴 수 있어요 ("can") and 쉴 거예요 ("will"). That is why 가다 → 갈 수 있어요 (not 가을), while 먹다 → 먹을 수 있어요. The same ㄹ/을 choice drives 거예요 and the noun-describing form.'}],usagePhrases:[{ko:"쉬어요",romanization:"swieoyo",en:"I rest.",note:"Safe polite present form."},{ko:"안 쉬어요",romanization:"an swieoyo",en:"I do not rest.",note:"Short everyday negative."},{ko:"쉬고 싶어요",romanization:"swigo sipeoyo",en:"I want to rest.",note:"Useful for choices and plans."},{ko:"쉴 수 있어요",romanization:"swil su isseoyo",en:"I can rest.",note:"Ability or possibility."},{ko:"쉬어야 해요",romanization:"swieoya haeyo",en:"I have to rest.",note:"Requirement or obligation."},{ko:"좀 쉬어요",romanization:"jom swieoyo",en:"rest a little.",note:"Softened with 좀."}],examples:[{ko:"오늘은 좀 쉬고 싶어요.",romanization:"oneureun jom swigo sipeoyo.",en:"I want to rest a little today.",note:"Desire."},{ko:"아프면 쉬어야 해요.",romanization:"apeumyeon swieoya haeyo.",en:"If you are sick, you should rest.",note:"Advice."},{ko:"여기서 쉴 수 있어요?",romanization:"yeogiseo swil su isseoyo?",en:"Can I rest here?",note:"Permission."}],forms:{dictionary:"쉬다",casualPresent:"쉬어",politePresent:"쉬어요",formalPresent:"쉽니다",negative:"안 쉬어요",past:"쉬었어요",future:"쉴 거예요",want:"쉬고 싶어요",can:"쉴 수 있어요",cannot:"못 쉬어요",must:"쉬어야 해요",dontHaveTo:"안 쉬어도 돼요",pleaseDo:"쉬어 주세요",pleaseDont:"쉬지 마세요",shallWe:"쉴까요?"},irregular:null,level:"A1",cluster:null,chapters:[8,27,29,48,60]},바쁘다:{ko:"바쁘다",romanization:"bappuda",en:"to be busy",pos:"adjective",chapter:"8·11·26",ex:{ko:"오늘 너무 바빠서 못 가요.",en:"I'm too busy today so I can't go.",note:"바쁘다 is ㅡ-irregular: 바빠서 (not 바쁘어서). Used constantly as a reason for 못 + verb"},collocations:["너무 바빠요","바빠서 못 해요","요즘 바빠요","바쁘지 않아요"],nuance:"바쁘다 becomes 바빠요 in polite speech. It is a high-frequency reason word because 바빠서 못 가요 politely explains why a plan is impossible.",explanation:'"to be busy" is 바쁘다 (bappeuda). The word itself is easy; what matters is the company it keeps, like 바빠요 ("I am busy."). Watch the particle attached to 바쁘다 in each example — that little marker, not the word, tells you whether it is the topic, the subject, the object, or a place. Copy one full sentence about talking about work, schedules, tasks, and obligations first, then vary one word.',shortExplanation:'바쁘다 means "to be busy" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","바쁘다 becomes 바빠요, not 바쁘어요."],conjugationTips:[{title:"Describing a noun: ㄴ/은 vs ㄹ/을",body:'To put 바쁘다 in front of a noun, use the ㄴ/은 form for how something is right now: 바쁜 것 ("a busy thing"). The ㄹ/을 form points to something that will or might become that way later. So 뜨거운 물 is water that is hot now, but 뜨거울 물 is water that will be hot — same adjective, different time feeling. For everyday description, reach for the ㄴ/은 form.'},{title:"Irregular stem: ㅡ drop",body:"바쁘다 loses its ㅡ vowel before 아/어, giving 바빠요 (the same drop turns 바쁘다 into 바빠요). The ㅡ never takes its own 어요, so don't add 어요 to the bare ㅡ."}],usagePhrases:[{ko:"바빠요",romanization:"bappayo",en:"I am busy.",note:"Polite."},{ko:"오늘 바빠요",romanization:"oneul bappayo",en:"I am busy today.",note:"Time."},{ko:"바빠서 못 가요",romanization:"bappaseo mot gayo",en:"I am busy, so I cannot go.",note:"Reason."},{ko:"바쁘지 않아요",romanization:"bappeuji anayo",en:"I am not busy.",note:"Negative."}],examples:[{ko:"오늘은 바빠요.",romanization:"oneureun bappayo.",en:"I am busy today.",note:"Topic."},{ko:"바빠서 못 가요.",romanization:"bappaseo mot gayo.",en:"I am busy, so I cannot go.",note:"Reason."},{ko:"내일은 바쁘지 않아요.",romanization:"naeireun bappeuji anayo.",en:"I am not busy tomorrow.",note:"Negative."}],forms:null,irregular:"ㅡ contraction",level:"A1",cluster:null,chapters:[8,11,26]},이해하다:{ko:"이해하다",romanization:"ihaehada",en:"to understand",pos:"verb",chapter:"8",ex:{ko:"아직 한국어를 다 이해할 수 없어요.",en:"I can't understand all Korean yet.",note:"이해하다 → 이해할 수 없어요 — a humble and accurate self-assessment for language learners"},collocations:["이해할 수 있어요","이해 못 해요","잘 이해해요","이해했어요"],nuance:"이해하다 is Sino-Korean: 理解 means 'untie/loosen (解) the logic (理)', so it pictures a tangled idea coming apart in your head — it covers both intellectual comprehension AND emotional sympathy ('I understand how you feel'). The dividing line versus 알다 is crucial: 알다 is to KNOW a fact ('I know his name', 이름을 알아요), while 이해하다 is to make sense of WHY or HOW something works. As a 하다-verb it conjugates regularly (이해해요, past 이해했어요). The big English-speaker pitfall is the particle in the negative: 'I don't understand' is almost always 이해가 안 돼요 (subject 가 + 되다, lit. 'understanding doesn't form'), not the literal 이해를 안 해요, which sounds like you're refusing to understand on purpose. Also resist translating 'understand my feelings' as 내 감정 — Koreans say 내 마음을 이해하다.",explanation:'이해하다 (ihaehada) means "to understand". Start from the polite form 이해해요 — it is safe with almost anyone, so use it before the dictionary form 이해하다. A strong first sentence is 이해해요 ("I understand"); once that feels natural, swap the noun, place, or time and reuse the verb everywhere. Korean changes the ending rather than the word, so the same 이해하다 also becomes 이해하고 싶어요 (want), 이해할 수 있어요 (can), and 이해할 수 없어요 (cannot). Say one true sentence about basic everyday communication, then bend it.',shortExplanation:'이해하다 means "to understand" and is practiced through polite conversation forms.',commonMistakes:["Do not use the dictionary form 이해하다 as a complete polite sentence.","Use 이해해요 as the default until you know the relationship is casual.","Saying 알아요 when you mean 'I grasp/follow it' — 알다 is to know a fact, 이해하다 is to comprehend the reasoning; for 'I get why' use 이해해요.","Translating 'I don't understand' literally as 이해를 안 해요. That implies willful refusal. The natural form is 이해가 안 돼요 with 가, treating understanding as something that fails to occur.","Saying 내 감정을 이해해 주세요 for 'understand my feelings'. The idiomatic collocation is 마음 (heart): 내 마음을 이해해 주세요."],conjugationTips:[{title:"ㄹ / 을 — can & will",body:'To say "can" or the future, attach ㄹ/을 to the stem: a vowel-final stem takes ㄹ and a consonant-final stem takes 을. 이해하다 becomes 이해할 수 있어요 ("can") and 이해할 거예요 ("will"). That is why 가다 → 갈 수 있어요 (not 가을), while 먹다 → 먹을 수 있어요. The same ㄹ/을 choice drives 거예요 and the noun-describing form.'}],usagePhrases:[{ko:"이해해요",romanization:"ihaehaeyo",en:"I understand.",note:"Safe polite present form."},{ko:"이해 안 해요",romanization:"ihae an haeyo",en:"I do not understand.",note:"Short everyday negative."},{ko:"이해하고 싶어요",romanization:"ihaehago sipeoyo",en:"I want to understand.",note:"Useful for choices and plans."},{ko:"이해할 수 있어요",romanization:"ihaehal su isseoyo",en:"I can understand.",note:"Ability or possibility."},{ko:"이해해야 해요",romanization:"ihaehaeya haeyo",en:"I have to understand.",note:"Requirement or obligation."},{ko:"이해해요",romanization:"ihaehaeyo",en:"I understand",note:"Warm reassuring reply, like 'I get it, it's okay'"}],examples:[{ko:"선생님 말을 이해했어요",romanization:"seonsaengnim mareul ihaehaesseoyo",en:"I understood the teacher",note:"Object + 를 when YOU actively grasp something"},{ko:"저는 한국어를 조금 이해해요",romanization:"jeoneun hangugeoreul jogeum ihaehaeyo",en:"I understand a little Korean",note:"조금 softens it to 'a bit', very humble and natural"},{ko:"네 마음 충분히 이해해",romanization:"ne maeum chungbunhi ihaehae",en:"I totally understand how you feel",note:"Casual 반말 to a close friend; 마음 = feelings, not 'mind'"}],forms:{dictionary:"이해하다",casualPresent:"이해해",politePresent:"이해해요",formalPresent:"이해합니다",negative:"이해 안 해요",past:"이해했어요",future:"이해할 거예요",want:"이해하고 싶어요",can:"이해할 수 있어요",cannot:"이해할 수 없어요",must:"이해해야 해요",dontHaveTo:"이해 안 해도 돼요",pleaseDo:"이해해 주세요",pleaseDont:"이해하지 마세요",shallWe:"이해할까요?"},irregular:null,level:"A2",cluster:null,chapters:[8]},못:{ko:"못",romanization:"mot",en:"cannot (inability marker, pre-verb)",pos:"adverb",chapter:"8",ex:{ko:"오늘은 못 가요. 다음에 갈 수 있어요.",en:"I can't go today. I can go next time.",note:"못 always goes BEFORE the verb. It's not a sentence ending — it's a pre-verb blocker. 못 가요, 못 먹어요, 못 마셔요."},collocations:["못 가요","못 먹어요","못 해요","못 와요"],nuance:"못은 망치로 벽이나 나무에 두드려 박는 금속 핀입니다. 같은 도구류라도 '못'은 두드려서 고정하고 '나사(screw)'는 돌려서 고정한다는 점이 핵심 차이라, 못에는 '박다/빼다', 나사에는 '조이다/풀다'를 씁니다. 영어 화자가 잘 틀리는 점은 두 가지입니다. 첫째, 'put a nail in'을 직역해 '못을 넣다'라고 하기 쉬운데, 못은 '넣다(put in)'가 아니라 '박다(drive in)'와 어울립니다. 둘째, 부정 부사 '못'(못 가요 = can't go)과 글자가 똑같아 헷갈리지만, 명사 못은 '못이, 못을'처럼 조사가 붙고 부사 못은 동사 앞에 홀로 옵니다. 자주 쓰는 짝은 '못을 박다, 못을 빼다, 못 자국, 못이 박히다(get driven in, 피동)'입니다.",explanation:'못 (mot) means "nail (for hammering)". Learn it inside a frame, not as a bare word: a useful first chunk is 못 ("nail"). In Korean the particle or ending next to 못 signals its job — topic, subject, object, place, time, method, or description — so read the examples for the small piece beside it. Start with one real sentence about daily routines at home, sleep, doors, windows, and simple requests, then change a single part.',shortExplanation:'못 means "nail (for hammering)" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Mixing up the noun 못 (nail) with the adverb 못 used for inability (못 해요 = can't do). The noun takes particles (못을), the adverb sits bare before a verb.","Using 넣다 from English 'put a nail in' — a nail is 박다 (driven in) with force, not just 넣다 (placed in).","Saying 못을 치다 for hammering a nail; the verb is 못을 박다 (the hammer does the 치다, the nail gets 박다)."],conjugationTips:[],usagePhrases:[{ko:"못",romanization:"mot",en:"nail",note:"The metal nail you hammer in; written the same as 못 'cannot' but a separate word."},{ko:"못을 박다",romanization:"moseul bakda",en:"to drive in a nail",note:"박다 = drive/embed; the standard verb that pairs with 못, never 넣다."},{ko:"못을 빼다",romanization:"moseul ppaeda",en:"to pull out a nail",note:"빼다 = pull out; use pliers (펜치) or the claw of a hammer."},{ko:"못 자국",romanization:"mot jaguk",en:"nail mark/hole",note:"The dent or hole left in the wall; too many can mean a deposit deduction."}],examples:[{ko:"여기 못이 있어요.",romanization:"yeogi mosi isseoyo.",en:"There's a nail here.",note:"못 ends in a consonant, so the subject form is 못이, not 못가."},{ko:"전셋집이라 못 박는 거 조심해야 돼요.",romanization:"jeonsetjibira mot bangneun geo josimhaeya dwaeyo.",en:"It's a jeonse place, so I have to be careful about hammering nails.",note:"Here 못 is the noun object of 박다; landlords may deduct from the deposit for wall damage."},{ko:"벽에 못 자국 남으면 보증금에서 깎일 수도 있어요.",romanization:"byeoge mot jagung nameumyeon bojeunggeumeseo kkakkil sudo isseoyo.",en:"If nail marks are left on the wall, it could be deducted from the deposit.",note:"못 자국 = nail marks; 깎이다 = get docked — a real concern in Korean rentals."}],forms:null,irregular:null,level:"A2",cluster:null,chapters:[8]},도와주다:{ko:"도와주다",romanization:"dowajuda",en:"to help",pos:"verb",chapter:"9·10·24",ex:{ko:"도와주세요!",en:"Please help me!",note:"주다 (give) fused into a request — asking someone to give you the action of helping"},collocations:["도와주세요","도와드릴까요?","도움이 필요해요"],nuance:"도와주다 means 'to help (for someone's benefit)' and is built from 돕다 ('to help') + 주다 ('to give'), so the 주다 already bakes in the warm sense of doing the help for another person. The base 돕다 is a ㅂ-irregular (돕 + 아요 → 도와요), which is why the compound surfaces as 도와- and the polite present is 도와줘요, past 도와줬어요. The person helped takes the object marker 을/를: 친구를 도와줘요. The most useful register fact is the request form: because 주다 is inside the verb, 'please help me' is simply 도와주세요 — adding a second giving verb to make 도와줘 주세요 is redundant and wrong. Contrast plain 돕다 (which feels more neutral/written, 어려운 이웃을 돕다 'help a struggling neighbor') with 도와주다 (the warm, conversational everyday form). The English-speaker pitfall is exactly that double 주세요, plus marking the helped person with 에게 by analogy to 'give to' — but help is done to a person directly, so it is 저를 도와줘요, not 저에게 도와줘요.",explanation:'"to help" in Korean is 도와주다 (dowajuda). In real conversation you will lean on the polite form 도와줘요, so make that your default and leave the bare dictionary form 도와주다 for study notes. Grow outward from one concrete line — 친구를 도와줘요 ("I help a friend") — then reshape the same stem into 도와주고 싶어요 (desire), 도와줄 수 있어요 (ability), and 못 도와줘요 (a real limit) as the moment needs. The stem stays put; only the ending moves.',shortExplanation:'도와주다 means "to help" and is practiced through polite conversation forms.',commonMistakes:["Do not use the dictionary form 도와주다 as a complete polite sentence.","Use 도와줘요 as the default until you know the relationship is casual.","Adding a second giving verb and saying 도와줘 주세요 — 주다 is already inside 도와주다, so 'please help me' is just 도와주세요.","Marking the helped person with 에게/한테 (저에게 도와줘요) — the person helped is the direct object: 저를 도와줘요.","Treating the stem as regular — it comes from the ㅂ-irregular 돕다 (돕 + 아 → 도와), so the forms are 도와줘요 / 도와줬어요, not 도우어요-style errors."],conjugationTips:[{title:"ㄹ / 을 — can & will",body:'To say "can" or the future, attach ㄹ/을 to the stem: a vowel-final stem takes ㄹ and a consonant-final stem takes 을. 도와주다 becomes 도와줄 수 있어요 ("can") and 도와줄 거예요 ("will"). That is why 가다 → 갈 수 있어요 (not 가을), while 먹다 → 먹을 수 있어요. The same ㄹ/을 choice drives 거예요 and the noun-describing form.'}],usagePhrases:[{ko:"도와줘요",romanization:"dowajwoyo",en:"I help.",note:"Safe polite present form."},{ko:"안 도와줘요",romanization:"an dowajwoyo",en:"I do not help.",note:"Short everyday negative."},{ko:"도와주고 싶어요",romanization:"dowajugo sipeoyo",en:"I want to help.",note:"Useful for choices and plans."},{ko:"도와줄 수 있어요",romanization:"dowajul su isseoyo",en:"I can help.",note:"Ability or possibility."},{ko:"도와줘야 해요",romanization:"dowajwoya haeyo",en:"I have to help.",note:"Requirement or obligation."},{ko:"친구를 도와줘요",romanization:"chingureul dowajwoyo",en:"I help a friend",note:"the person helped takes the object marker 을/를"}],examples:[{ko:"제가 도와줄게요.",romanization:"jega dowajulgeyo.",en:"I'll help you.",note:"줄게요 = a friendly promise to help; spoken offer"},{ko:"친구가 저를 많이 도와줬어요.",romanization:"chinguga jeoreul mani dowajwosseoyo.",en:"My friend helped me a lot.",note:"past 도와줬어요; the helper takes 이/가, helped person 를"},{ko:"짐이 무거운데 좀 도와주세요.",romanization:"jimi mugeounde jom dowajuseyo.",en:"The luggage is heavy, so please help me.",note:"real request: 는데 gives the reason, 좀 softens it"}],forms:{dictionary:"도와주다",casualPresent:"도와줘",politePresent:"도와줘요",formalPresent:"도와줍니다",negative:"안 도와줘요",past:"도와줬어요",future:"도와줄 거예요",want:"도와주고 싶어요",can:"도와줄 수 있어요",cannot:"못 도와줘요",must:"도와줘야 해요",dontHaveTo:"안 도와줘도 돼요",pleaseDo:"도와주세요",pleaseDont:"도와주지 마세요",shallWe:"도와줄까요?"},irregular:null,level:"A1",cluster:null,chapters:[9,10,24]},찍다:{ko:"찍다",romanization:"jjikda",en:"to take (a photo) / to stamp",pos:"verb",chapter:"9",ex:{ko:"여기서는 사진을 찍지 마세요.",en:"Please do not take photos here.",note:"찍지 마세요 = RED X SIGN — prohibition on the action of taking photos"},collocations:["사진 찍다","사진 찍어 주세요","사진 찍어도 돼요?"],nuance:"",explanation:"",shortExplanation:"",commonMistakes:[],conjugationTips:[],usagePhrases:[],examples:[],forms:null,irregular:null,level:"A1",cluster:null,chapters:[9]},들어가다:{ko:"들어가다",romanization:"deureogada",en:"to go in / enter",pos:"verb",chapter:"9",ex:{ko:"들어가도 돼요?",en:"May I go in?",note:"가 + 아도 → 가도 is absorbed into 들어가도 — entering is checked with permission form"},collocations:["들어가도 돼요?","들어가지 마세요","들어가세요"],nuance:"들어가다 combines 들다 (to enter) + 가다 (to go), so it literally means 'enter-and-go' — to move into an enclosed space in a direction AWAY from where the speaker stands. The crucial paired contrast is 들어가다 vs 들어오다: 들어오다 ('enter-and-come') is the same entering motion but TOWARD the speaker. So if you are inside a room and want someone to come in, you say 들어오세요 (come in), but if you are heading into a room over there, you 들어가요. English 'go in / come in' splits the same way, yet learners default to 들어가다 for both and tell a guest at their own door 들어가세요, which oddly means 'go away in / head on home'. Beyond the literal, 들어가다 idiomatically means to get home (집에 들어가다), to enter a school or job (대학·회사에 들어가다), and even 'to fit' (이 옷이 가방에 안 들어가요). It is a plain native compound, regular, neutral register. The destination takes 에 or 안에 (방에/방 안에 들어가다). Common collocations: 방·집에 들어가다, 학교·회사에 들어가다, 안으로 들어가다, 잘 안 들어가다(won't fit).",explanation:'"to go in" in Korean is 들어가다 (deureogada). In real conversation you will lean on the polite form 들어가요, so make that your default and leave the bare dictionary form 들어가다 for study notes. Grow outward from one concrete line — 방에 들어가다 ("to go into the room") — then reshape the same stem into 들어가고 싶어요 (desire), 들어갈 수 있어요 (ability), and 못 들어가요 (a real limit) as the moment needs. The stem stays put; only the ending moves.',shortExplanation:'들어가다 means "to go in" and is practiced through polite conversation forms.',commonMistakes:["Do not use the dictionary form 들어가다 as a complete polite sentence.","Use 들어가요 as the default until you know the relationship is casual.","Telling a visitor at your door 들어가세요 — that means 'go on in (away from me) / head home'; to welcome them in toward you, say 들어오세요.","Using a 'to' particle like 으로 for the room — the space entered takes 에 (방에 들어가다); 으로 marks only a direction (안으로).","Forgetting the idioms — 'get home' is 집에 들어가다 and 'get into university' is 대학에 들어가다, not 집에 가다 / 대학에 가다 alone, which lose the 'enter' nuance."],conjugationTips:[{title:"ㄹ / 을 — can & will",body:'To say "can" or the future, attach ㄹ/을 to the stem: a vowel-final stem takes ㄹ and a consonant-final stem takes 을. 들어가다 becomes 들어갈 수 있어요 ("can") and 들어갈 거예요 ("will"). That is why 가다 → 갈 수 있어요 (not 가을), while 먹다 → 먹을 수 있어요. The same ㄹ/을 choice drives 거예요 and the noun-describing form.'}],usagePhrases:[{ko:"들어가요",romanization:"deureogayo",en:"I go in.",note:"Safe polite present form."},{ko:"안 들어가요",romanization:"an deureogayo",en:"I do not go in.",note:"Short everyday negative."},{ko:"들어가고 싶어요",romanization:"deureogago sipeoyo",en:"I want to go in.",note:"Useful for choices and plans."},{ko:"들어갈 수 있어요",romanization:"deureogal su isseoyo",en:"I can go in.",note:"Ability or possibility."},{ko:"들어가야 해요",romanization:"deureogaya haeyo",en:"I have to go in.",note:"Requirement or obligation."},{ko:"방에 들어가다",romanization:"bange deureogada",en:"to go into the room",note:"Enter an enclosed space; the place entered takes 에 or 안에."}],examples:[{ko:"안으로 들어가요.",romanization:"aneuro deureogayo.",en:"Go inside.",note:"Simple direction; 안으로 = toward the inside."},{ko:"추우니까 빨리 안으로 들어갑시다.",romanization:"chuunikka ppalli aneuro deureogapsida.",en:"It's cold, so let's go inside quickly.",note:"Everyday suggestion; -읍시다 'let's'."},{ko:"저는 보통 열한 시쯤 집에 들어가요.",romanization:"jeoneun botong yeolhan sijjeum jibe deureogayo.",en:"I usually get home around eleven.",note:"Real routine; the 'get home' idiom of 들어가다."}],forms:{dictionary:"들어가다",casualPresent:"들어가",politePresent:"들어가요",formalPresent:"들어갑니다",negative:"안 들어가요",past:"들어갔어요",future:"들어갈 거예요",want:"들어가고 싶어요",can:"들어갈 수 있어요",cannot:"못 들어가요",must:"들어가야 해요",dontHaveTo:"안 들어가도 돼요",pleaseDo:"들어가 주세요",pleaseDont:"들어가지 마세요",shallWe:"들어갈까요?"},irregular:null,level:"A2",cluster:null,chapters:[9]},열다:{ko:"열다",romanization:"yeolda",en:"to open",pos:"verb",chapter:"9",ex:{ko:"창문 좀 열어 주세요.",en:"Please open the window a bit.",note:"열다 + 어 주세요 — asking someone else to perform the opening action"},collocations:["열어 주세요","열어도 돼요?","열지 마세요"],nuance:"열다 is ㄹ irregular in some formal forms: 엽니다. Memorize 열어요 first.",explanation:`열다 (yeolda) = "to open". Don't try to memorize all fifteen forms at once; anchor on 열어요 plus one useful sentence like 문을 열어요 ("open the door."). After that the endings carry the meaning — 열고 싶어요 for what you want, 열 수 있어요 for what you can, 못 열어요 for what you can't. Keep the stem, change the ending, and one verb gives you a dozen sentences about daily routines at home, sleep, doors, windows, and simple requests.`,shortExplanation:'열다 means "to open" and is practiced through polite conversation forms.',commonMistakes:["Do not use the dictionary form 열다 as a complete polite sentence.","Use 열어요 as the default until you know the relationship is casual."],conjugationTips:[{title:"ㄹ / 을 — can & will",body:'To say "can" or the future, attach ㄹ/을 to the stem: a vowel-final stem takes ㄹ and a consonant-final stem takes 을. 열다 becomes 열 수 있어요 ("can") and 열 거예요 ("will"). That is why 가다 → 갈 수 있어요 (not 가을), while 먹다 → 먹을 수 있어요. The same ㄹ/을 choice drives 거예요 and the noun-describing form.'},{title:"Irregular stem: ㄹ",body:"열다 is a ㄹ-stem word. The ㄹ drops before ㄴ/ㅂ/ㅅ endings: 살다 → 삽니다 (formal), 사는 (describing a noun), 사세요 (honorific). Before a vowel the ㄹ stays: 열어요."}],usagePhrases:[{ko:"열어요",romanization:"yeoreoyo",en:"I open.",note:"Safe polite present form."},{ko:"안 열어요",romanization:"an yeoreoyo",en:"I do not open.",note:"Short everyday negative."},{ko:"열고 싶어요",romanization:"yeolgo sipeoyo",en:"I want to open.",note:"Useful for choices and plans."},{ko:"열 수 있어요",romanization:"yeol su isseoyo",en:"I can open.",note:"Ability or possibility."},{ko:"열어야 해요",romanization:"yeoreoya haeyo",en:"I have to open.",note:"Requirement or obligation."},{ko:"문을 열어요",romanization:"muneul yeoreoyo",en:"open the door.",note:"Common object."}],examples:[{ko:"문을 열어 주세요.",romanization:"muneul yeoreo juseyo.",en:"Please open the door.",note:"Request."},{ko:"창문을 열어도 돼요?",romanization:"changmuneul yeoreodo dwaeyo?",en:"May I open the window?",note:"Permission."},{ko:"아직 열지 마세요.",romanization:"ajik yeolji maseyo.",en:"Please do not open it yet.",note:"Prohibition."}],forms:{dictionary:"열다",casualPresent:"열어",politePresent:"열어요",formalPresent:"엽니다",negative:"안 열어요",past:"열었어요",future:"열 거예요",want:"열고 싶어요",can:"열 수 있어요",cannot:"못 열어요",must:"열어야 해요",dontHaveTo:"안 열어도 돼요",pleaseDo:"열어 주세요",pleaseDont:"열지 마세요",shallWe:"열까요?"},irregular:"ㄹ irregular",level:"A1",cluster:null,chapters:[9]},닫다:{ko:"닫다",romanization:"datda",en:"to close",pos:"verb",chapter:"9·28·44",ex:{ko:"문 닫아 주세요.",en:"Please close the door.",note:"닫다 + 아 주세요 — the ㄷ stem is regular here; asking another person to close it"},collocations:["닫아 주세요","닫아도 돼요?","닫지 마세요"],nuance:"닫다 is the opposite of 열다. Use it for doors, windows, stores, apps, and lids.",explanation:'닫다 (datda) means "to close". Start from the polite form 닫아요 — it is safe with almost anyone, so use it before the dictionary form 닫다. A strong first sentence is 문을 닫아요 ("close the door."); once that feels natural, swap the noun, place, or time and reuse the verb everywhere. Korean changes the ending rather than the word, so the same 닫다 also becomes 닫고 싶어요 (want), 닫을 수 있어요 (can), and 못 닫아요 (cannot). Say one true sentence about daily routines at home, sleep, doors, windows, and simple requests, then bend it.',shortExplanation:'닫다 means "to close" and is practiced through polite conversation forms.',commonMistakes:["Do not use the dictionary form 닫다 as a complete polite sentence.","Use 닫아요 as the default until you know the relationship is casual."],conjugationTips:[{title:"ㄹ / 을 — can & will",body:'To say "can" or the future, attach ㄹ/을 to the stem: a vowel-final stem takes ㄹ and a consonant-final stem takes 을. 닫다 becomes 닫을 수 있어요 ("can") and 닫을 거예요 ("will"). That is why 가다 → 갈 수 있어요 (not 가을), while 먹다 → 먹을 수 있어요. The same ㄹ/을 choice drives 거예요 and the noun-describing form.'}],usagePhrases:[{ko:"닫아요",romanization:"dadayo",en:"I close.",note:"Safe polite present form."},{ko:"안 닫아요",romanization:"an dadayo",en:"I do not close.",note:"Short everyday negative."},{ko:"닫고 싶어요",romanization:"datgo sipeoyo",en:"I want to close.",note:"Useful for choices and plans."},{ko:"닫을 수 있어요",romanization:"dadeul su isseoyo",en:"I can close.",note:"Ability or possibility."},{ko:"닫아야 해요",romanization:"dadaya haeyo",en:"I have to close.",note:"Requirement or obligation."},{ko:"문을 닫아요",romanization:"muneul dadayo",en:"close the door.",note:"Common object."}],examples:[{ko:"문을 닫아 주세요.",romanization:"muneul dada juseyo.",en:"Please close the door.",note:"Request."},{ko:"가게가 닫았어요.",romanization:"gagega dadasseoyo.",en:"The store closed.",note:"Past."},{ko:"아직 닫지 마세요.",romanization:"ajik datji maseyo.",en:"Please do not close it yet.",note:"Prohibition."}],forms:{dictionary:"닫다",casualPresent:"닫아",politePresent:"닫아요",formalPresent:"닫습니다",negative:"안 닫아요",past:"닫았어요",future:"닫을 거예요",want:"닫고 싶어요",can:"닫을 수 있어요",cannot:"못 닫아요",must:"닫아야 해요",dontHaveTo:"안 닫아도 돼요",pleaseDo:"닫아 주세요",pleaseDont:"닫지 마세요",shallWe:"닫을까요?"},irregular:null,level:"A1",cluster:null,chapters:[9,28,44]},뛰다:{ko:"뛰다",romanization:"ttwida",en:"to run",pos:"verb",chapter:"9",ex:{ko:"복도에서 뛰지 마세요.",en:"Please do not run in the hallway.",note:"뛰다 + 지 마세요 — common school/museum prohibition sign"},collocations:["뛰지 마세요","뛰어도 돼요?","뛰지 않아도 돼요"],nuance:"뛰다 is a regular verb whose stem ends in the vowel 위, so it simply adds 어 without contracting: 뛰어요, 뛰었어요. Before the formal ㅂ/ㄴ endings the stem shortens in the usual way to 뜁니다 and 뛸 거예요. Its key synonym is 달리다: 달리다 is the neutral, 'sporty' word for running over distance (마라톤을 달리다, 100미터를 달리다), while 뛰다 is the everyday word for dashing, rushing, or even jumping, so a child rushing across a room 뛰어다녀요 rather than 달려다녀요. Crucially 뛰다 also means 'to jump/leap' (제자리에서 뛰다 = jump in place; 심장이 뛰다 = the heart beats/pounds), so context decides between 'run' and 'jump'. The English-speaker pitfall is spelling: don't confuse 뛰다 (run) with 띄다 ('be visible / catch the eye', as in 눈에 띄다) — they sound close but are different verbs. Also note the polite-warning 뛰지 마세요 is the fixed phrase you'll see posted everywhere.",explanation:'"to run" in Korean is 뛰다 (ttwida). In real conversation you will lean on the polite form 뛰어요, so make that your default and leave the bare dictionary form 뛰다 for study notes. Grow outward from one concrete line — 빨리 뛰어요 ("I run fast") — then reshape the same stem into 뛰고 싶어요 (desire), 뛸 수 있어요 (ability), and 못 뛰어요 (a real limit) as the moment needs. The stem stays put; only the ending moves.',shortExplanation:'뛰다 means "to run" and is practiced through polite conversation forms.',commonMistakes:["Do not use the dictionary form 뛰다 as a complete polite sentence.","Use 뛰어요 as the default until you know the relationship is casual.","Confusing 뛰다 with 띄다 — 띄다 means 'to be noticeable / catch the eye' (눈에 띄다), so writing 눈에 뛰다 is wrong; keep the two verbs separate.","Assuming 뛰다 only means timed/sport running and switching to 달리다 for a quick dash — for rushing to catch a bus or train, natural Korean is 버스를 타려고 뛰었어요, not 달렸어요.","Forgetting the stem-shortening in the formal form and saying 뛰읍니다 — the correct formal present is 뜁니다 (and the future is 뛸 거예요)."],conjugationTips:[{title:"ㄹ / 을 — can & will",body:'To say "can" or the future, attach ㄹ/을 to the stem: a vowel-final stem takes ㄹ and a consonant-final stem takes 을. 뛰다 becomes 뛸 수 있어요 ("can") and 뛸 거예요 ("will"). That is why 가다 → 갈 수 있어요 (not 가을), while 먹다 → 먹을 수 있어요. The same ㄹ/을 choice drives 거예요 and the noun-describing form.'}],usagePhrases:[{ko:"뛰어요",romanization:"ttwieoyo",en:"I run.",note:"Safe polite present form."},{ko:"안 뛰어요",romanization:"an ttwieoyo",en:"I do not run.",note:"Short everyday negative."},{ko:"뛰고 싶어요",romanization:"ttwigo sipeoyo",en:"I want to run.",note:"Useful for choices and plans."},{ko:"뛸 수 있어요",romanization:"ttwil su isseoyo",en:"I can run.",note:"Ability or possibility."},{ko:"뛰어야 해요",romanization:"ttwieoya haeyo",en:"I have to run.",note:"Requirement or obligation."},{ko:"빨리 뛰어요",romanization:"ppalli ttwieoyo",en:"I run fast",note:"뛰다 pairs with speed adverbs 빨리·열심히"}],examples:[{ko:"아이들이 운동장에서 뛰어요.",romanization:"aideuri undongjangeseo ttwieoyo.",en:"The kids run around the playground.",note:"everyday running/dashing about, not timed sport"},{ko:"지각할까 봐 역까지 뛰었어요.",romanization:"jigakalkka bwa yeokkkaji ttwieosseoyo.",en:"I ran to the station because I was afraid of being late.",note:"뛰다 = rushing to make it on time"},{ko:"여기는 병원이니까 뛰지 마세요.",romanization:"yeogineun byeongwoninikka ttwiji maseyo.",en:"This is a hospital, so please don't run.",note:"뛰지 마세요 keeps ㅁ before the consonant ending"}],forms:{dictionary:"뛰다",casualPresent:"뛰어",politePresent:"뛰어요",formalPresent:"뜁니다",negative:"안 뛰어요",past:"뛰었어요",future:"뛸 거예요",want:"뛰고 싶어요",can:"뛸 수 있어요",cannot:"못 뛰어요",must:"뛰어야 해요",dontHaveTo:"안 뛰어도 돼요",pleaseDo:"뛰어 주세요",pleaseDont:"뛰지 마세요",shallWe:"뛸까요?"},irregular:null,level:"A2",cluster:null,chapters:[9]},걱정하다:{ko:"걱정하다",romanization:"geokjeonghada",en:"to worry",pos:"verb",chapter:"9",ex:{ko:"걱정하지 마세요.",en:"Please do not worry.",note:"지 마세요 used not as a rule sign but as warm reassurance between people"},collocations:["걱정하지 마세요","걱정 마세요","걱정하지 않아도 돼요"],nuance:"걱정하다 (걱정 = 'worry/anxiety' + 하다) is the everyday verb for being anxious or concerned about someone or something. Distinguish it sharply from 고민하다: 걱정하다 is feeling ANXIOUS about how things will turn out ('I'm worried about my grades'), whereas 고민하다 is actively DELIBERATING over a hard choice ('I'm agonizing over which job to take'). As a 하다-verb it splits in the negative — 걱정 안 해요 (separating the noun) or 걱정하지 않아요 — and the favor form 걱정해 주다 means 'to worry on someone's behalf', a kind gesture. The natural way to say 'I feel worried' is 걱정이 돼요 (걱정 + 이 + 되다), not 걱정을 해요, which sounds like deliberate worrying. The single most useful phrase in the whole language family is 걱정하지 마세요 ('don't worry') — memorize it. English 'I'm worried about you' is 네가 걱정돼 or 너를 걱정해, not 너에 대해 걱정해.",explanation:`"to worry" in Korean is 걱정하다 (geokjeonghada). In real conversation you will lean on the polite form 걱정해요, so make that your default and leave the bare dictionary form 걱정하다 for study notes. Grow outward from one concrete line — 걱정하지 마세요 ("Don't worry") — then reshape the same stem into 걱정하고 싶어요 (desire), 걱정할 수 있어요 (ability), and 걱정할 수 없어요 (a real limit) as the moment needs. The stem stays put; only the ending moves.`,shortExplanation:'걱정하다 means "to worry" and is practiced through polite conversation forms.',commonMistakes:["Do not use the dictionary form 걱정하다 as a complete polite sentence.","Use 걱정해요 as the default until you know the relationship is casual.","Saying 걱정을 해요 for the feeling 'I'm worried'. Korean prefers 걱정이 돼요 (worry arises) for the spontaneous emotion.","Confusing 걱정하다 (anxious feeling) with 고민하다 (mulling over a decision). 'Worried about the result' = 결과를 걱정해요; 'agonizing over the choice' = 선택을 고민해요.","Over-attaching ~에 대해: 너에 대해 걱정해요. Natural Korean is 너를 걱정해요 or 네가 걱정돼요."],conjugationTips:[{title:"ㄹ / 을 — can & will",body:'To say "can" or the future, attach ㄹ/을 to the stem: a vowel-final stem takes ㄹ and a consonant-final stem takes 을. 걱정하다 becomes 걱정할 수 있어요 ("can") and 걱정할 거예요 ("will"). That is why 가다 → 갈 수 있어요 (not 가을), while 먹다 → 먹을 수 있어요. The same ㄹ/을 choice drives 거예요 and the noun-describing form.'}],usagePhrases:[{ko:"걱정해요",romanization:"geokjeonghaeyo",en:"I worry.",note:"Safe polite present form."},{ko:"걱정 안 해요",romanization:"geokjeong an haeyo",en:"I do not worry.",note:"Short everyday negative."},{ko:"걱정하고 싶어요",romanization:"geokjeonghago sipeoyo",en:"I want to worry.",note:"Useful for choices and plans."},{ko:"걱정할 수 있어요",romanization:"geokjeonghal su isseoyo",en:"I can worry.",note:"Ability or possibility."},{ko:"걱정해야 해요",romanization:"geokjeonghaeya haeyo",en:"I have to worry.",note:"Requirement or obligation."},{ko:"걱정하지 마세요",romanization:"geokjeonghaji maseyo",en:"Don't worry",note:"Extremely common comfort phrase"}],examples:[{ko:"엄마가 저를 걱정해요",romanization:"eommaga jeoreul geokjeonghaeyo",en:"My mom worries about me",note:"Person worried about + 를"},{ko:"시험을 많이 걱정했어요",romanization:"siheomeul mani geokjeonghaesseoyo",en:"I worried a lot about the exam",note:"많이 modifies the worrying; past tense"},{ko:"걱정하지 마, 다 잘될 거야",romanization:"geokjeonghaji ma, da jaldoel geoya",en:"Don't worry, it'll all work out",note:"Casual reassurance pairing the negative with 잘되다"}],forms:{dictionary:"걱정하다",casualPresent:"걱정해",politePresent:"걱정해요",formalPresent:"걱정합니다",negative:"걱정 안 해요",past:"걱정했어요",future:"걱정할 거예요",want:"걱정하고 싶어요",can:"걱정할 수 있어요",cannot:"걱정할 수 없어요",must:"걱정해야 해요",dontHaveTo:"걱정 안 해도 돼요",pleaseDo:"걱정해 주세요",pleaseDont:"걱정하지 마세요",shallWe:"걱정할까요?"},irregular:null,level:"A2",cluster:null,chapters:[9]},"가야 해요":{ko:"가야 해요",romanization:"gaya haeyo",en:"have to go / must go",pos:"pattern",chapter:"9",ex:{ko:"지금 가야 해요. 늦었어요.",en:"I have to go now. I'm late.",note:"가다 + 아야 해요 — MUST-DO CHECKLIST: non-negotiable obligation"},collocations:["가야 해요","가야 돼요","안 가도 돼요?"],nuance:"",explanation:"",shortExplanation:"",commonMistakes:[],conjugationTips:[],usagePhrases:[],examples:[],forms:null,irregular:null,level:"A1",cluster:null,chapters:[9]},죄송하지만:{ko:"죄송하지만",romanization:"joesonghajiman",en:"I'm sorry but / I apologize but",pos:"conjunction",chapter:"9",ex:{ko:"죄송하지만 여기서 음식을 드시면 안 돼요.",en:"I'm sorry but you cannot eat here.",note:"죄송하지만 softens a refusal or prohibition — staff use this before giving bad news"},collocations:["죄송하지만 안 돼요","죄송하지만 지 마세요","죄송합니다"],nuance:"",explanation:"",shortExplanation:"",commonMistakes:[],conjugationTips:[],usagePhrases:[],examples:[],forms:null,irregular:null,level:"A1",cluster:null,chapters:[9]},입장권:{ko:"입장권",romanization:"ipjanggwon",en:"admission ticket",pos:"noun",chapter:"9",ex:{ko:"입장권을 보여줘야 해요.",en:"You have to show your admission ticket.",note:"입장권 + 어야 해요 — obligation before entry at museums and event spaces"},collocations:["입장권을 사다","입장권을 보여주다","입장권이 있어야 해요"],nuance:"입장권 is the ticket that lets you ENTER a venue — a museum, park, exhibition, or show. The hanja 入場券 is 入 (enter) + 場 (place/venue) + 券 (ticket), literally an 'enter-the-venue ticket'. Distinguish it sharply from 표 and 티켓: 표 is the everyday word for transport tickets (기차표 train ticket, 버스표), 티켓 (loanword) is common for concerts and movies, while 입장권 specifically grants entry to a place. The natural verbs are 입장권을 사다 and the idiomatic 입장권을 끊다 ('cut a ticket', a fixed expression for buying one), plus 예매하다 to book ahead. Count them with the flat-object counter 장: 입장권 한 장. English-speaker pitfall: don't default to 표 for a museum entry — a train ticket is 표/기차표, but entrance to a venue is the 입장권.",explanation:'"admission ticket" is 입장권 (ipjanggwon). The word itself is easy; what matters is the company it keeps, like 입장권을 사다 ("to buy an admission ticket"). Watch the particle attached to 입장권 in each example — that little marker, not the word, tells you whether it is the topic, the subject, the object, or a place. Copy one full sentence about getting around, reservations, directions, photos, and emergency help first, then vary one word.',shortExplanation:'입장권 means "admission ticket" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Using 표 for venue entry. 표 is mainly a transport ticket (기차표, 버스표); to get into a museum or exhibition you need an 입장권. Reserve 표 for trains and buses.","Counting tickets with 개 instead of 장. Flat paper items take the counter 장 — '입장권 두 장' (two tickets), not '입장권 두 개', which sounds off for sheet-like tickets."],conjugationTips:[],usagePhrases:[{ko:"입장권을 사다",romanization:"ipjanggwoneul sada",en:"to buy an admission ticket",note:"get one to enter"},{ko:"입장권을 끊다",romanization:"ipjanggwoneul kkeunta",en:"to buy/issue a ticket",note:"the idiomatic 'cut a ticket' verb"},{ko:"입장권을 예매하다",romanization:"ipjanggwoneul yemaehada",en:"to book an admission ticket",note:"reserve in advance"},{ko:"입장권 한 장",romanization:"ipjanggwon han jang",en:"one admission ticket",note:"counting with 장"}],examples:[{ko:"입장권 어디서 사요?",romanization:"ipjanggwon eodiseo sayo?",en:"Where do I buy admission tickets?",note:"입장권을 사다 'buy a ticket'; 어디서 + 사요? asks where to get them."},{ko:"박물관 입장권을 예매했어요.",romanization:"bangmulgwan ipjanggwoneul yemaehaesseoyo.",en:"I booked museum admission tickets in advance.",note:"입장권을 예매하다 = reserve tickets ahead; common for popular sites."},{ko:"입장권 두 장 주세요.",romanization:"ipjanggwon du jang juseyo.",en:"Two admission tickets, please.",note:"장 is the counter for flat tickets; 주세요 'please give' is how you ask at a counter."}],forms:null,irregular:null,level:"A2",cluster:null,chapters:[9]},음식:{ko:"음식",romanization:"eumsik",en:"food",pos:"noun",chapter:"9·22",ex:{ko:"여기서 음식을 먹지 마세요.",en:"Please do not eat food here.",note:"Common museum/gallery prohibition — 지 마세요 as RED X SIGN"},collocations:["음식을 먹다","음식을 가져오다","음식 금지"],nuance:"음식 is the general word for food or cuisine. It combines naturally with Korean, spicy, delicious, and eat.",explanation:'"food" is 음식 (eumsik). The word itself is easy; what matters is the company it keeps, like 음식을 먹어요 ("I eat food."). Watch the particle attached to 음식 in each example — that little marker, not the word, tells you whether it is the topic, the subject, the object, or a place. Copy one full sentence about ordering food, explaining food restrictions, and asking what to eat together first, then vary one word.',shortExplanation:'음식 means "food" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","For a meal, 밥 can also be natural; 음식 is broader."],conjugationTips:[],usagePhrases:[{ko:"음식을 먹어요",romanization:"eumsigeul meogeoyo",en:"I eat food.",note:"Object."},{ko:"매운 음식",romanization:"maeun eumsik",en:"spicy food.",note:"Description."},{ko:"한국 음식",romanization:"hanguk eumsik",en:"Korean food.",note:"Noun phrase."},{ko:"음식이 맛있어요",romanization:"eumsigi masisseoyo",en:"The food is delicious.",note:"Subject."}],examples:[{ko:"한국 음식을 먹고 싶어요.",romanization:"hanguk eumsigeul meokgo sipeoyo.",en:"I want to eat Korean food.",note:"Desire."},{ko:"매운 음식은 못 먹어요.",romanization:"maeun eumsigeun mon meogeoyo.",en:"I cannot eat spicy food.",note:"Restriction."},{ko:"이 음식이 맛있어요.",romanization:"i eumsigi masisseoyo.",en:"This food is delicious.",note:"Subject."}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[9,22]},만지다:{ko:"만지다",romanization:"manjida",en:"to touch",pos:"verb",chapter:"9",ex:{ko:"전시품을 만지지 마세요.",en:"Please do not touch the exhibits.",note:"만지다 + 지 마세요 — classic museum rule you will definitely encounter"},collocations:["만지지 마세요","만져도 돼요?","손대지 마세요"],nuance:"만지다 is the plain verb for touching something with your hand to feel its texture, temperature, or shape; the thing touched takes 을/를 (천을 만지다). The 요-form is regular: stem 만지- + -어요 contracts 지+어 into 져, giving 만져요 / past 만졌어요. The nearest neighbor is 건드리다, but the dividing line is intent: 만지다 is neutral, even affectionate exploration ('feel, handle'), while 건드리다 carries 'mess with / disturb / poke' and often a nuisance nuance (남의 물건을 건드리다 = mess with someone's stuff). The classic English-speaker pitfall is reaching for 'touch' emotionally: 'that movie touched me' is NOT 만지다 but 감동받다 / 감동적이다 — 만지다 is strictly physical contact. Also keep 만지다 (touch) apart from the look-alike 만나다 (meet); they share only the first syllable.",explanation:`만지다 (manji-da) = "to touch". Don't try to memorize all fifteen forms at once; anchor on 만져요 plus one useful sentence like 손으로 만지다 ("to touch with one's hand"). After that the endings carry the meaning — 만지고 싶어요 for what you want, 만질 수 있어요 for what you can, 못 만져요 for what you can't. Keep the stem, change the ending, and one verb gives you a dozen sentences about basic everyday communication.`,shortExplanation:'만지다 means "to touch" and is practiced through polite conversation forms.',commonMistakes:["Do not use the dictionary form 만지다 as a complete polite sentence.","Use 만져요 as the default until you know the relationship is casual.","Using 만지다 for 'be touched/moved' emotionally. 'The story touched me' is 그 이야기에 감동받았어요, not 만졌어요 — 만지다 is only physical hand contact.","Dropping the object particle and saying 천 만져요. A direct object needs 을/를: 천을 만져요 ('I touch the fabric').","Confusing 만지다 with 만나다. 친구를 만지다 means 'touch a friend (physically)', not 'meet a friend' — say 친구를 만나요."],conjugationTips:[{title:"ㄹ / 을 — can & will",body:'To say "can" or the future, attach ㄹ/을 to the stem: a vowel-final stem takes ㄹ and a consonant-final stem takes 을. 만지다 becomes 만질 수 있어요 ("can") and 만질 거예요 ("will"). That is why 가다 → 갈 수 있어요 (not 가을), while 먹다 → 먹을 수 있어요. The same ㄹ/을 choice drives 거예요 and the noun-describing form.'}],usagePhrases:[{ko:"만져요",romanization:"manjyeoyo",en:"I touch.",note:"Safe polite present form."},{ko:"안 만져요",romanization:"an manjyeoyo",en:"I do not touch.",note:"Short everyday negative."},{ko:"만지고 싶어요",romanization:"manjigo sipeoyo",en:"I want to touch.",note:"Useful for choices and plans."},{ko:"만질 수 있어요",romanization:"manjil su isseoyo",en:"I can touch.",note:"Ability or possibility."},{ko:"만져야 해요",romanization:"manjyeoya haeyo",en:"I have to touch.",note:"Requirement or obligation."},{ko:"손으로 만지다",romanization:"soneuro manjida",en:"to touch with one's hand",note:"The default instrument: 손으로 (with the hand) is the most common partner phrase."}],examples:[{ko:"이 천을 한번 만져 보세요.",romanization:"i cheoneul hanbeon manjyeo boseyo.",en:"Try touching this fabric.",note:"만지다 + 보다 = touch to check the texture; 한번 means 'go ahead and give it a try'."},{ko:"강아지를 만져 봐도 돼요?",romanization:"gangajireul manjyeo bwado dwaeyo?",en:"May I try touching the puppy?",note:"-아도 돼요? asks permission; the object 강아지 takes 를."},{ko:"페인트가 안 말라서 만지면 안 돼요.",romanization:"peinteuga an mallaseo manjimyeon an dwaeyo.",en:"The paint is not dry, so you must not touch it.",note:"-(으)면 안 되다 states a prohibition stronger than a gentle warning."}],forms:{dictionary:"만지다",casualPresent:"만져",politePresent:"만져요",formalPresent:"만집니다",negative:"안 만져요",past:"만졌어요",future:"만질 거예요",want:"만지고 싶어요",can:"만질 수 있어요",cannot:"못 만져요",must:"만져야 해요",dontHaveTo:"안 만져도 돼요",pleaseDo:"만져 주세요",pleaseDont:"만지지 마세요",shallWe:"만질까요?"},irregular:null,level:"A2",cluster:null,chapters:[9]},지하철역:{ko:"지하철역",romanization:"jihacheollyeok",en:"subway station",pos:"noun",chapter:"10",ex:{ko:"지하철역까지 얼마나 걸려요?",en:"How long does it take to the subway station?",note:"까지 = as far as / to — the end-point of a distance range"},collocations:["지하철역에 가다","지하철역까지 걷다","지하철역 어디예요?"],nuance:"",explanation:"",shortExplanation:"",commonMistakes:[],conjugationTips:[],usagePhrases:[],examples:[],forms:null,irregular:null,level:"A1",cluster:null,chapters:[10]},출구:{ko:"출구",romanization:"chulgu",en:"exit",pos:"noun",chapter:"10·23",ex:{ko:"몇 번 출구예요?",en:"Which exit number is it?",note:"몇 번 = which number — essential for subway navigation"},collocations:["1번 출구","출구로 나가다","출구 어디예요?"],nuance:"출구 is 出口 — 出 (go out) + 口 (opening), literally the 'exit-mouth', the way you leave a building or station; in the subway each is numbered (몇 번 출구), so 'meet at exit 7' is everyday Korean. It is the exact opposite of 입구 (入口, entrance), and the shared 口 'opening' character ties the 出/入 pair together. Distinguish 출구 from 비상구 (非常口, 'emergency exit'), the marked fire-escape door — a normal way out is a 출구, the emergency one is a 비상구. To leave through it you say 출구로 나가다, where 으로 marks the exit as your route. English speakers blur 출구 and 입구 because both end in 구; fix the memory with 출 = out, 입 = in. And note exits are counted with the native-Sino number + 번 (삼 번 출구), not with English ordinals.",explanation:'"exit" is 출구 (chulgu). The word itself is easy; what matters is the company it keeps, like 역 출구 ("station exit"). Watch the particle attached to 출구 in each example — that little marker, not the word, tells you whether it is the topic, the subject, the object, or a place. Copy one full sentence about getting around, reservations, directions, photos, and emergency help first, then vary one word.',shortExplanation:'출구 means "exit" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Confusing 출구 (exit, 出) with 입구 (entrance, 入) — both end in 口, but 출 = out, 입 = in.","Saying 출구를 나가요 — to mark the route out, use 출구로 나가요.","Using 출구 for a fire escape — the emergency one is specifically 비상구."],conjugationTips:[],usagePhrases:[{ko:"역 출구",romanization:"yeok chulgu",en:"station exit",note:"numbered exits are everywhere in the subway"},{ko:"출구로 나가다",romanization:"chulguro nagada",en:"go out the exit",note:"으로 + 나가다 marks the way out you take"},{ko:"몇 번 출구",romanization:"myeot beon chulgu",en:"which exit number",note:"essential phrase for subway meetups"},{ko:"출구를 찾다",romanization:"chulgureul chatda",en:"find the exit",note:"를 + 찾다, look for the way out"}],examples:[{ko:"삼 번 출구로 나가요.",romanization:"sam beon chulguro nagayo.",en:"Go out exit number three.",note:"으로 marks the exit as the path out; 삼 번 = no. 3"},{ko:"출구가 어디예요?",romanization:"chulguga eodiyeyo?",en:"Where is the exit?",note:"the mirror question to 입구가 어디예요?"},{ko:"저는 칠 번 출구 앞에서 기다릴게요.",romanization:"jeoneun chil beon chulgu apeseo gidarilgeyo.",en:"I'll wait in front of exit 7.",note:"출구 앞 = in front of the exit; -ㄹ게요 = I will"}],forms:null,irregular:null,level:"A2",cluster:null,chapters:[10,23]},안내소:{ko:"안내소",romanization:"annaeso",en:"information desk / help desk",pos:"noun",chapter:"10",ex:{ko:"안내소가 어디예요?",en:"Where is the information desk?",note:"A practical travel question when you need staff help, directions, or opening hours"},collocations:["안내소가 어디예요?","안내소에서 물어보다","안내소는 몇 시까지 열어요?"],nuance:"안내소 is a place, so use 에 for location and 에서 for asking or receiving help there.",explanation:'"information desk / help desk" is 안내소 (annaeso). The word itself is easy; what matters is the company it keeps, like 안내소가 어디예요? ("Where is the information desk?"). Watch the particle attached to 안내소 in each example — that little marker, not the word, tells you whether it is the topic, the subject, the object, or a place. Copy one full sentence about getting around, reservations, directions, photos, and emergency help first, then vary one word.',shortExplanation:'안내소 means "information desk / help desk" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Do not use 안내소부터 when you simply mean 'at the information desk.' Use 안내소에서."],conjugationTips:[],usagePhrases:[{ko:"안내소가 어디예요?",romanization:"annaesoga eodiyeyo?",en:"Where is the information desk?",note:"Ask this when you need a staff desk in a station or museum."},{ko:"안내소에서 물어보세요.",romanization:"annaesoeseo mureoboseyo.",en:"Please ask at the information desk.",note:"에서 marks the place where the asking happens."}],examples:[{ko:"안내소는 오전 9시부터 오후 6시까지 열어요.",romanization:"annaesoneun ojeon 9sibuteo ohu 6sikkaji yeoreoyo.",en:"The information desk is open from 9 a.m. to 6 p.m.",note:"A clean Chapter 10 time-range sentence with 부터/까지."}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[10]},"2호선":{ko:"2호선",romanization:"i hoseon",en:"Line 2 (subway)",pos:"noun",chapter:"10",ex:{ko:"2호선 타는 곳이 어디예요?",en:"Where is the Line 2 boarding area?",note:"타는 곳 = the place where you board; more natural than saying the line itself is an exit"},collocations:["2호선 타는 곳","2호선으로 가다","2호선은 어디예요?"],nuance:"Koreans often give subway directions by line number plus exit number or direction.",explanation:'2호선 (2hoseon) = "Line 2 (subway)". Treat it as a building block that needs a frame: 2호선 타는 곳이 어디예요? ("Where is the place to take Line 2?") shows how it actually behaves. The grammar lives in the particle or ending beside 2호선, so notice that piece as you read, not just the dictionary meaning. Begin from a complete sentence about getting around, reservations, directions, photos, and emergency help and swap just one element to make it yours.',shortExplanation:'2호선 means "Line 2 (subway)" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Do not say 2호선은 5번 출구예요 if you mean the boarding area. Say 2호선 타는 곳은 5번 출구 쪽이에요."],conjugationTips:[],usagePhrases:[{ko:"2호선 타는 곳이 어디예요?",romanization:"2hoseon taneun gosi eodiyeyo?",en:"Where is the place to take Line 2?",note:"타는 곳 = boarding place / platform area."},{ko:"2호선은 몇 번 출구 쪽이에요?",romanization:"2hoseoneun myeot beon chulgu jjogieyo?",en:"Which exit side is Line 2 toward?",note:"Useful in large subway stations with many exits."}],examples:[{ko:"2호선 타는 곳은 5번 출구 쪽이에요.",romanization:"2hoseon taneun goseun 5beon chulgu jjogieyo.",en:"The Line 2 boarding area is toward exit 5.",note:"A natural station-help answer."}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[10]},부터:{ko:"부터",romanization:"buteo",en:"from (starting point)",pos:"particle",chapter:"10",ex:{ko:"오늘부터 열심히 공부할게요.",en:"I'll study hard starting from today.",note:"부터 attaches to the start-point — 오늘부터 means 'from today onward'"},collocations:["지금부터","오늘부터","N시부터","여기부터"],nuance:"",explanation:"",shortExplanation:"",commonMistakes:[],conjugationTips:[],usagePhrases:[],examples:[],forms:null,irregular:null,level:"A1",cluster:null,chapters:[10]},까지:{ko:"까지",romanization:"kkaji",en:"to / until / as far as (end point)",pos:"particle",chapter:"10",ex:{ko:"몇 시까지 열어요?",en:"Until what time are you open?",note:"까지 after a time = 'until' — perfect for asking business hours"},collocations:["N시까지","역까지","몇 시까지?","언제까지?"],nuance:"",explanation:"",shortExplanation:"",commonMistakes:[],conjugationTips:[],usagePhrases:[],examples:[],forms:null,irregular:null,level:"A1",cluster:null,chapters:[10]},모르다:{ko:"모르다",romanization:"moreuda",en:"to not know",pos:"verb",chapter:"10·26·41·61",ex:{ko:"잘 모르겠어요.",en:"I'm not quite sure.",note:"잘 모르겠어요 is softer and more natural than just 몰라요 — 겠 adds an element of 'I think / I guess'"},collocations:["잘 모르겠어요","모르겠어요","길을 모르다"],nuance:"모르다 is the standalone verb 'to not know / be unaware of', the lexical opposite of 알다, and it likewise takes the object marker 을/를: 길을 몰라요. It is a 르-irregular: when an 아/어 ending attaches, the 르 stem doubles the ㄹ and the vowel drops, so 모르 + 아요 → 몰라요 (never 모르아요) and the past is 몰랐어요. The crucial register tool is 겠: 잘 모르겠어요 ('I'm not quite sure') is markedly softer and more natural than a blunt 몰라요, which can sound curt or even dismissive depending on tone, so Koreans lean on the 겠 form constantly when admitting ignorance politely. Compare 모르다 with 헷갈리다 ('to be confused / mix things up'): 모르다 is having no information at all, while 헷갈리다 is having information but getting it tangled. The English-speaker pitfall is the conjugation — applying a regular pattern to get 모르아요 instead of the irregular 몰라요 — and forgetting that the smooth, courteous version is 잘 모르겠어요.",explanation:`모르다 (moreuda) = "to not know". Don't try to memorize all fifteen forms at once; anchor on 몰라요 plus one useful sentence like 길을 몰라요 ("I don't know the way"). After that the endings carry the meaning — 모르고 싶어요 for what you want, 모를 수 있어요 for what you can, 알아요 for what you can't. Keep the stem, change the ending, and one verb gives you a dozen sentences about basic everyday communication.`,shortExplanation:'모르다 means "to not know" and is practiced through polite conversation forms.',commonMistakes:["Do not use the dictionary form 모르다 as a complete polite sentence.","Use 몰라요 as the default until you know the relationship is casual.","Conjugating it regularly as 모르아요 — 모르다 is a 르-irregular, so 모르 + 아요 becomes 몰라요 (past 몰랐어요).","Blurting a bare 몰라요 when asked something — it can sound curt; soften with 잘 모르겠어요 to stay polite.","Using 모르다 when you mean you mixed two things up — that is 헷갈리다 (e.g. 이름이 헷갈려요 'I keep confusing the names'), not 몰라요."],conjugationTips:[{title:"ㄹ / 을 — can & will",body:'To say "can" or the future, attach ㄹ/을 to the stem: a vowel-final stem takes ㄹ and a consonant-final stem takes 을. 모르다 becomes 모를 수 있어요 ("can") and 모를 거예요 ("will"). That is why 가다 → 갈 수 있어요 (not 가을), while 먹다 → 먹을 수 있어요. The same ㄹ/을 choice drives 거예요 and the noun-describing form.'},{title:"Irregular stem",body:"모르다 has an irregular stem (르 irregular). Memorize its polite form 몰라요 as the anchor and build the other forms from there."}],usagePhrases:[{ko:"몰라요",romanization:"mollayo",en:"I not know.",note:"Safe polite present form."},{ko:"알아요",romanization:"arayo",en:"I do not not know.",note:"Short everyday negative."},{ko:"모르고 싶어요",romanization:"moreugo sipeoyo",en:"I want to not know.",note:"Useful for choices and plans."},{ko:"모를 수 있어요",romanization:"moreul su isseoyo",en:"I can not know.",note:"Ability or possibility."},{ko:"몰라야 해요",romanization:"mollaya haeyo",en:"I have to not know.",note:"Requirement or obligation."},{ko:"길을 몰라요",romanization:"gireul mollayo",en:"I don't know the way",note:"the thing not known takes 을/를, like 알다"}],examples:[{ko:"죄송해요, 저는 길을 잘 몰라요.",romanization:"joesonghaeyo, jeoneun gireul jal mollayo.",en:"Sorry, I don't really know the way.",note:"polite apology + 잘 몰라요 to be gentle"},{ko:"그 사람 이름을 몰랐어요.",romanization:"geu saram ireumeul mollasseoyo.",en:"I didn't know that person's name.",note:"past 몰랐어요 from the 르-irregular stem"},{ko:"글쎄요, 저도 잘 모르겠어요. 같이 찾아볼까요?",romanization:"geulsseyo, jeodo jal moreugesseoyo. gachi chajabolkkayo?",en:"Hmm, I'm not sure either. Shall we look it up together?",note:"real fumble: 모르겠어요 sounds far softer than a flat 몰라요"}],forms:{dictionary:"모르다",casualPresent:"몰라",politePresent:"몰라요",formalPresent:"모릅니다",negative:"알아요",past:"몰랐어요",future:"모를 거예요",want:"모르고 싶어요",can:"모를 수 있어요",cannot:"알아요",must:"몰라야 해요",dontHaveTo:"몰라도 돼요",pleaseDo:"모른 척해 주세요",pleaseDont:"모르지 마세요",shallWe:"모를까요?"},irregular:"르 irregular",level:"A2",cluster:null,chapters:[10,26,41,61]},걸리다:{ko:"걸리다",romanization:"geollida",en:"to take (time) / to be required",pos:"verb",chapter:"10",ex:{ko:"버스로 30분 걸려요.",en:"It takes 30 minutes by bus.",note:"얼마나 걸려요? (How long does it take?) is a must-know travel question — 걸리다 expresses time cost"},collocations:["얼마나 걸려요?","N분 걸려요","시간이 걸리다"],nuance:"걸리다 is a high-frequency verb that fans out into three everyday senses learners meet fast: (1) time being needed — 시간이 걸리다; (2) catching an illness — 감기에 걸리다; and (3) getting caught/busted — 경찰한테 걸리다, 거짓말이 걸리다. The thread linking them is its origin as the passive of 걸다 ('to hang/hook'): something gets hooked — by time, by sickness, by the law — so 벽에 그림이 걸려 있어요 ('a picture is hung on the wall') is the same word. The number-one English-speaker pitfall is the subject/particle: for 'take time' the *time* is the subject (시간이 걸려요), never 시간을 걸려요; and for illness you must use 에 (감기에 걸리다), not the object 를. Compare 걸리다 ('take/require time') with 들다, which is used for cost/effort/money (돈이 들다) — 시간이 걸리다 vs 돈이 들다 is a pairing Koreans keep distinct. It is a regular ㅣ-stem verb: 걸리 + 어 contracts to 걸려요.",explanation:'걸리다 (geollida) means "to take (time) / to get caught". Start from the polite form 걸려요 — it is safe with almost anyone, so use it before the dictionary form 걸리다. A strong first sentence is 시간이 얼마나 걸려요? ("How long does it take?"); once that feels natural, swap the noun, place, or time and reuse the verb everywhere. Korean changes the ending rather than the word, so the same 걸리다 also becomes 걸리고 싶어요 (want), 걸릴 수 있어요 (can), and 걸릴 수 없어요 (cannot). Say one true sentence about basic everyday communication, then bend it.',shortExplanation:'걸리다 means "to take (time) / to get caught" and is practiced through polite conversation forms.',commonMistakes:["Do not use the dictionary form 걸리다 as a complete polite sentence.","Use 걸려요 as the default until you know the relationship is casual.","For 'how long does it take', the time is the subject: 시간이 얼마나 걸려요?, never 시간을 걸려요.","To catch a cold, use the particle 에 (감기에 걸리다), not 를 — 감기를 걸렸어요 is wrong."],conjugationTips:[{title:"ㄹ / 을 — can & will",body:'To say "can" or the future, attach ㄹ/을 to the stem: a vowel-final stem takes ㄹ and a consonant-final stem takes 을. 걸리다 becomes 걸릴 수 있어요 ("can") and 걸릴 거예요 ("will"). That is why 가다 → 갈 수 있어요 (not 가을), while 먹다 → 먹을 수 있어요. The same ㄹ/을 choice drives 거예요 and the noun-describing form.'}],usagePhrases:[{ko:"걸려요",romanization:"geollyeoyo",en:"I take (time) / to get caught.",note:"Safe polite present form."},{ko:"안 걸려요",romanization:"an geollyeoyo",en:"I do not take (time) / to get caught.",note:"Short everyday negative."},{ko:"걸리고 싶어요",romanization:"geolligo sipeoyo",en:"I want to take (time) / to get caught.",note:"Useful for choices and plans."},{ko:"걸릴 수 있어요",romanization:"geollil su isseoyo",en:"I can take (time) / to get caught.",note:"Ability or possibility."},{ko:"걸려야 해요",romanization:"geollyeoya haeyo",en:"I have to take (time) / to get caught.",note:"Requirement or obligation."},{ko:"시간이 얼마나 걸려요?",romanization:"sigani eolmana geollyeoyo?",en:"How long does it take?",note:"걸리다 with 시간 is THE way to ask about duration; the time, not you, is the subject."}],examples:[{ko:"집까지 한 시간 걸려요",romanization:"jipkkaji han sigan geollyeoyo",en:"It takes an hour to get home",note:"Travel time: the duration is the subject — 한 시간이 걸려요."},{ko:"또 감기에 걸렸어요",romanization:"tto gamgie geollyeosseoyo",en:"I caught a cold again",note:"A fixed expression every beginner needs; note the 에 particle."},{ko:"과속하다가 경찰한테 걸렸어요",romanization:"gwasokadaga gyeongchalhante geollyeosseoyo",en:"I was speeding and got caught by the police",note:"The 'get busted' sense, with the catcher marked by 한테."}],forms:{dictionary:"걸리다",casualPresent:"걸려",politePresent:"걸려요",formalPresent:"걸립니다",negative:"안 걸려요",past:"걸렸어요",future:"걸릴 거예요",want:"걸리고 싶어요",can:"걸릴 수 있어요",cannot:"걸릴 수 없어요",must:"걸려야 해요",dontHaveTo:"걸리지 않아도 돼요",pleaseDo:"걸리세요",pleaseDont:"걸리지 마세요",shallWe:"걸릴까요?"},irregular:null,level:"A2",cluster:null,chapters:[10]},찾다:{ko:"찾다",romanization:"chatda",en:"to look for / find",pos:"verb",chapter:"10",ex:{ko:"지하철역을 찾고 있어요.",en:"I'm looking for the subway station.",note:"찾고 있어요 = currently searching (ongoing action) — useful when you're lost and need help"},collocations:["N을/를 찾다","길을 찾다","찾고 있어요"],nuance:"찾다 can mean find or look for. 찾고 있어요 often means “I am looking for.”",explanation:`찾다 (chatda) = "to find / look for". Don't try to memorize all fifteen forms at once; anchor on 찾아요 plus one useful sentence like 길을 찾아요 ("find the way."). After that the endings carry the meaning — 찾고 싶어요 for what you want, 찾을 수 있어요 for what you can, 못 찾아요 for what you can't. Keep the stem, change the ending, and one verb gives you a dozen sentences about getting around, reservations, directions, photos, and emergency help.`,shortExplanation:'찾다 means "to find / look for" and is practiced through polite conversation forms.',commonMistakes:["Do not use the dictionary form 찾다 as a complete polite sentence.","Use 찾아요 as the default until you know the relationship is casual."],conjugationTips:[{title:"ㄹ / 을 — can & will",body:'To say "can" or the future, attach ㄹ/을 to the stem: a vowel-final stem takes ㄹ and a consonant-final stem takes 을. 찾다 becomes 찾을 수 있어요 ("can") and 찾을 거예요 ("will"). That is why 가다 → 갈 수 있어요 (not 가을), while 먹다 → 먹을 수 있어요. The same ㄹ/을 choice drives 거예요 and the noun-describing form.'}],usagePhrases:[{ko:"찾아요",romanization:"chajayo",en:"I find / look for.",note:"Safe polite present form."},{ko:"안 찾아요",romanization:"an chajayo",en:"I do not find / look for.",note:"Short everyday negative."},{ko:"찾고 싶어요",romanization:"chatgo sipeoyo",en:"I want to find / look for.",note:"Useful for choices and plans."},{ko:"찾을 수 있어요",romanization:"chajeul su isseoyo",en:"I can find / look for.",note:"Ability or possibility."},{ko:"찾아야 해요",romanization:"chajaya haeyo",en:"I have to find / look for.",note:"Requirement or obligation."},{ko:"길을 찾아요",romanization:"gireul chajayo",en:"find the way.",note:"Travel phrase."}],examples:[{ko:"화장실을 찾고 있어요.",romanization:"hwajangsireul chatgo isseoyo.",en:"I am looking for the bathroom.",note:"Progressive."},{ko:"길을 못 찾겠어요.",romanization:"gireul mot chatgesseoyo.",en:"I cannot find the way.",note:"Travel trouble."},{ko:"같이 찾을까요?",romanization:"gachi chajeulkkayo?",en:"Shall we look together?",note:"Suggestion."}],forms:{dictionary:"찾다",casualPresent:"찾아",politePresent:"찾아요",formalPresent:"찾습니다",negative:"안 찾아요",past:"찾았어요",future:"찾을 거예요",want:"찾고 싶어요",can:"찾을 수 있어요",cannot:"못 찾아요",must:"찾아야 해요",dontHaveTo:"안 찾아도 돼요",pleaseDo:"찾아 주세요",pleaseDont:"찾지 마세요",shallWe:"찾을까요?"},irregular:null,level:"A1",cluster:null,chapters:[10]},여기:{ko:"여기",romanization:"yeogi",en:"here (this place)",pos:"pronoun",chapter:"10",ex:{ko:"여기부터 역까지 걸어서 10분이에요.",en:"It's a 10-minute walk from here to the station.",note:"여기부터 = starting from here — pairs naturally with 까지 for distance ranges"},collocations:["여기서","여기에","여기부터","여기 있어요"],nuance:"여기 changes with particles: 여기에 location, 여기서 action place, 여기로 direction.",explanation:'여기 (yeogi) means "here". Learn it inside a frame, not as a bare word: a useful first chunk is 여기에 있어요 ("It is here."). In Korean the particle or ending next to 여기 signals its job — topic, subject, object, place, time, method, or description — so read the examples for the small piece beside it. Start with one real sentence about getting around, reservations, directions, photos, and emergency help, then change a single part.',shortExplanation:'여기 means "here" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","여기 and 여기서 are not always interchangeable."],conjugationTips:[],usagePhrases:[{ko:"여기에 있어요",romanization:"yeogie isseoyo",en:"It is here.",note:"Location."},{ko:"여기서 기다려요",romanization:"yeogiseo gidaryeoyo",en:"I wait here.",note:"Action place."},{ko:"여기 앉아도 돼요?",romanization:"yeogi anjado dwaeyo?",en:"May I sit here?",note:"Permission."},{ko:"여기로 와 주세요",romanization:"yeogiro wa juseyo",en:"Please come here.",note:"Direction."}],examples:[{ko:"여기서 기다려 주세요.",romanization:"yeogiseo gidaryeo juseyo.",en:"Please wait here.",note:"Action place."},{ko:"여기 앉아도 돼요?",romanization:"yeogi anjado dwaeyo?",en:"May I sit here?",note:"Permission."},{ko:"여기에 있어요.",romanization:"yeogie isseoyo.",en:"It is here.",note:"Location."}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[10]},저기:{ko:"저기",romanization:"jeogi",en:"over there (that place in the distance)",pos:"pronoun",chapter:"10",ex:{ko:"화장실은 저기에 있어요.",en:"The bathroom is over there.",note:"저기 = yonder/over there (visible but farther away). 여기 = here, 거기 = there, 저기 = over there"},collocations:["저기에 있다","저기서","저기 보이다"],nuance:"저기 is the 'place' member of the 이/그/저 family — 'over there,' far from both people — completing 여기 (here) / 거기 (there, by you) / 저기 (yonder). Beyond location it has two social jobs English keeps separate: 저기요 is the go-to polite 'excuse me' for hailing a stranger or a waiter when you don't know their name, and a sentence-opening 저기… works like 'um / you know,' softening the ground before a request or bad news. The synonym to separate is 저거 — 저기 is a SPOT, 저거 is a THING, so 저기 뭐 있어요? ('what's over there?') versus 저거 뭐예요? ('what is that object?'). One register caution: in a restaurant, 저기요 is gentler and safer than the blunter 여기요, and calling a stranger 아저씨/아주머니 can sound abrupt, so 저기요 is the diplomatic choice.",explanation:'저기 (jeogi) = "over there; um, excuse me". Treat it as a building block that needs a frame: 저기 ("over there") shows how it actually behaves. The grammar lives in the particle or ending beside 저기, so notice that piece as you read, not just the dictionary meaning. Begin from a complete sentence about basic everyday communication and swap just one element to make it yours.',shortExplanation:'저기 means "over there; um, excuse me" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Using 저기 for a place near the listener — that spot is 거기 (여기/거기/저기 track distance).","Confusing 저기 (a place) with 저거 (a thing): 저기 있어요 'it's over there' vs 저거예요 'it's that one.'","Saying just 여기 to flag a server when 저기요 would sound more polite and natural."],conjugationTips:[],usagePhrases:[{ko:"저기",romanization:"jeogi",en:"over there",note:"A place far from both speaker and listener (여기/거기/저기 = here/there/yonder)."},{ko:"저기에",romanization:"jeogie",en:"at/to over there",note:"저기 + 에 for a static location or a destination."},{ko:"저기요",romanization:"jeogiyo",en:"excuse me",note:"Politely flags down a stranger or server without knowing their name."},{ko:"저기 있잖아",romanization:"jeogi itjana",en:"you know, um...",note:"Soft conversational opener / hesitation filler before a delicate topic."}],examples:[{ko:"화장실이 저기 있어요.",romanization:"hwajangsiri jeogi isseoyo.",en:"The restroom is over there.",note:"저기 names a spot far from both of you; pair with 있어요 to locate things."},{ko:"저기요, 메뉴판 좀 주세요.",romanization:"jeogiyo, menyupan jom juseyo.",en:"Excuse me, could I get a menu?",note:"저기요 is the standard polite way to call a server."},{ko:"저기… 잠깐 얘기 좀 할 수 있을까요?",romanization:"jeogi… jamkkan yaegi jom hal su isseulkkayo?",en:"Um... could we talk for a moment?",note:"Sentence-initial 저기 cushions a hesitant or awkward request."}],forms:null,irregular:null,level:"A2",cluster:null,chapters:[10]},왼쪽:{ko:"왼쪽",romanization:"oenjjok",en:"left side",pos:"noun",chapter:"10·23",ex:{ko:"왼쪽으로 가세요.",en:"Go to the left.",note:"으로 = direction marker (go via/toward). 왼쪽으로 가다 = go left"},collocations:["왼쪽으로 가다","왼쪽에 있다","왼쪽 출구"],nuance:"왼쪽 is the native compound noun for the left side or leftward direction, built from 왼- ('left') + 쪽 ('side/direction'); it attaches to a noun (문 왼쪽) or stands with a direction particle for movement (왼쪽으로 = to the left). The -쪽 element is the same one in 위쪽/아래쪽/앞쪽, marking 'the ~ side'. Its direct opposite is 오른쪽 (right), and confusing the two is the single most common error when giving directions — practice the pair until 왼 reliably means left. Note also the more formal/literary 좌 (左, Sino-Korean) seen in 좌회전 (left turn, on road signs) versus everyday spoken 왼쪽. Register: 왼쪽 is the normal conversational word; 좌 appears in fixed/official terms. English-speaker pitfalls: (1) 왼쪽에서 있어요 for existence instead of 왼쪽에 있어요; (2) swapping 왼쪽 and 오른쪽 under pressure; and (3) using 왼쪽 alone for 'turn left' (왼쪽 도세요 is incomplete) — you need the direction particle: 왼쪽으로 도세요 / 왼쪽으로 가세요.",explanation:'왼쪽 (oenjjok) = "left side". Treat it as a building block that needs a frame: 문 왼쪽에 ("to the left of the door") shows how it actually behaves. The grammar lives in the particle or ending beside 왼쪽, so notice that piece as you read, not just the dictionary meaning. Begin from a complete sentence about getting around, reservations, directions, photos, and emergency help and swap just one element to make it yours.',shortExplanation:'왼쪽 means "left side" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Saying 왼쪽에서 있어요 for 'it is on the left' — existence takes 에 (왼쪽에 있어요); 에서 marks where an action happens.","Swapping 왼쪽 (left) and 오른쪽 (right) when giving directions — drill the pair so 왼 always cues 'left'.","Saying 왼쪽 도세요 for 'turn left' — add the direction particle: 왼쪽으로 도세요 / 왼쪽으로 가세요."],conjugationTips:[],usagePhrases:[{ko:"문 왼쪽에",romanization:"mun oenjjoge",en:"to the left of the door",note:"왼쪽 + 에 marks the location"},{ko:"은행 왼쪽에 있어요",romanization:"eunhaeng oenjjoge isseoyo",en:"it is to the left of the bank",note:"existence verb 있다"},{ko:"역 왼쪽에서 만나요",romanization:"yeok oenjjogeseo mannayo",en:"I meet on the left of the station",note:"action place 에서 + verb"},{ko:"왼쪽으로 도세요",romanization:"oenjjogeuro doseyo",en:"turn to the left",note:"direction 으로 + motion verb"}],examples:[{ko:"문 왼쪽에 거울이 있어요.",romanization:"mun oenjjoge geouri isseoyo.",en:"There is a mirror to the left of the door.",note:"Basic frame: noun 왼쪽에 + 있다 places the mirror."},{ko:"가게 왼쪽에서 버스를 타요.",romanization:"gage oenjjogeseo beoseureul tayo.",en:"I catch the bus to the left of the shop.",note:"에서 because catching the bus is an action done at that spot."},{ko:"사거리에서 왼쪽으로 가세요.",romanization:"sageorieseo oenjjogeuro gaseyo.",en:"Turn left at the intersection.",note:"왼쪽으로 with 으로 gives real walking/driving directions."}],forms:null,irregular:null,level:"A2",cluster:null,chapters:[10,23]},오른쪽:{ko:"오른쪽",romanization:"oreunjjok",en:"right side",pos:"noun",chapter:"10·23",ex:{ko:"오른쪽에 편의점이 있어요.",en:"There's a convenience store on the right.",note:"에 있다 = something exists in that location — combine direction + 에 있다 to describe where things are"},collocations:["오른쪽으로 가다","오른쪽에 있다","오른쪽 출구"],nuance:"오른쪽 is the native compound noun for the right side or rightward direction, from 오른- ('right') + 쪽 ('side/direction'); it attaches to a noun (문 오른쪽) or pairs with a direction particle for motion (오른쪽으로 = to the right). The -쪽 piece is shared with 왼쪽/위쪽/앞쪽, all meaning 'the ~ side'. Its opposite is 왼쪽 (left), and mixing the two is the top direction-giving mistake — anchor 오른 firmly to 'right'. The formal/Sino-Korean counterpart is 우 (右), found in signage like 우회전 (right turn) and the set phrase 좌우 (左右, left-and-right), while 오른쪽 is the everyday spoken form. Register: 오른쪽 is conversational, 우 is official/written. English-speaker pitfalls: (1) 오른쪽에서 있어요 for existence instead of 오른쪽에 있어요; (2) confusing 오른쪽 with 왼쪽; and (3) using 오른쪽 by itself for 'turn right' — the direction particle is required: 오른쪽으로 도세요 / 오른쪽으로 가세요, not 오른쪽 도세요.",explanation:'오른쪽 (oreunjjok) means "right side". Learn it inside a frame, not as a bare word: a useful first chunk is 문 오른쪽에 ("to the right of the door"). In Korean the particle or ending next to 오른쪽 signals its job — topic, subject, object, place, time, method, or description — so read the examples for the small piece beside it. Start with one real sentence about getting around, reservations, directions, photos, and emergency help, then change a single part.',shortExplanation:'오른쪽 means "right side" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Saying 오른쪽에서 있어요 for 'it is on the right' — existence needs 에 (오른쪽에 있어요); 에서 marks the place of an action.","Mixing up 오른쪽 (right) and 왼쪽 (left) when giving directions — drill the pair so 오른 always cues 'right'.","Saying 오른쪽 도세요 for 'turn right' — include the direction particle: 오른쪽으로 도세요 / 오른쪽으로 가세요."],conjugationTips:[],usagePhrases:[{ko:"문 오른쪽에",romanization:"mun oreunjjoge",en:"to the right of the door",note:"오른쪽 + 에 marks the location"},{ko:"카페 오른쪽에 있어요",romanization:"kape oreunjjoge isseoyo",en:"it is to the right of the cafe",note:"existence verb 있다"},{ko:"역 오른쪽에서 기다려요",romanization:"yeok oreunjjogeseo gidaryeoyo",en:"I wait on the right of the station",note:"action place 에서 + verb"},{ko:"오른쪽으로 도세요",romanization:"oreunjjogeuro doseyo",en:"turn to the right",note:"direction 으로 + motion verb"}],examples:[{ko:"카페 오른쪽에 은행이 있어요.",romanization:"kape oreunjjoge eunhaengi isseoyo.",en:"There is a bank to the right of the cafe.",note:"Basic frame: noun 오른쪽에 + 있다 places the bank."},{ko:"건물 오른쪽에서 친구를 만나요.",romanization:"geonmul oreunjjogeseo chingureul mannayo.",en:"I meet my friend to the right of the building.",note:"에서 because meeting is an action done at that spot."},{ko:"다음 신호에서 오른쪽으로 가세요.",romanization:"daeum sinhoeseo oreunjjogeuro gaseyo.",en:"Go right at the next light.",note:"오른쪽으로 with 으로 is how real directions are spoken."}],forms:null,irregular:null,level:"A2",cluster:null,chapters:[10,23]},비싸다:{ko:"비싸다",romanization:"bissada",en:"to be expensive",pos:"adjective",chapter:"11·25",ex:{ko:"비싸면 안 사요.",en:"If it's expensive, I don't buy it.",note:"면 (condition/switch): buying decision depends on the price condition being met"},collocations:["비싸서 안 사요","너무 비싸다","비싸고 좋다"],nuance:"비싸요 is useful for shopping but can sound blunt if said directly to staff.",explanation:'"to be expensive" is 비싸다 (bissada). The word itself is easy; what matters is the company it keeps, like 비싸요 ("It is expensive."). Watch the particle attached to 비싸다 in each example — that little marker, not the word, tells you whether it is the topic, the subject, the object, or a place. Copy one full sentence about buying things, checking prices, quantities, and payment options first, then vary one word.',shortExplanation:'비싸다 means "to be expensive" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Use 너무 비싸요 carefully; it can sound like a complaint."],conjugationTips:[{title:"Describing a noun: ㄴ/은 vs ㄹ/을",body:'To put 비싸다 in front of a noun, use the ㄴ/은 form for how something is right now: 비싼 것 ("a expensive thing"). The ㄹ/을 form points to something that will or might become that way later. So 뜨거운 물 is water that is hot now, but 뜨거울 물 is water that will be hot — same adjective, different time feeling. For everyday description, reach for the ㄴ/은 form.'}],usagePhrases:[{ko:"비싸요",romanization:"bissayo",en:"It is expensive.",note:"Polite."},{ko:"너무 비싸요",romanization:"neomu bissayo",en:"It is too expensive.",note:"Shopping."},{ko:"비싸면 안 사요",romanization:"bissamyeon an sayo",en:"If it is expensive, I do not buy it.",note:"Condition."},{ko:"비싸지 않아요",romanization:"bissaji anayo",en:"It is not expensive.",note:"Careful negative."}],examples:[{ko:"이거 비싸요?",romanization:"igeo bissayo?",en:"Is this expensive?",note:"Question."},{ko:"너무 비싸서 안 사요.",romanization:"neomu bissaseo an sayo.",en:"It is too expensive, so I will not buy it.",note:"Reason."},{ko:"비싸면 안 사요.",romanization:"bissamyeon an sayo.",en:"If it is expensive, I do not buy it.",note:"Condition."}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[11,25]},싸다:{ko:"싸다",romanization:"ssada",en:"to be cheap / inexpensive",pos:"adjective",chapter:"11·25",ex:{ko:"이 식당은 싸고 맛있어요.",en:"This restaurant is cheap and delicious.",note:"고 as coupling hook between two adjectives — just linking, no causal relationship between them"},collocations:["싸고 좋다","값이 싸다","싸게 사다"],nuance:"싸다 can also mean “to wrap” in other contexts, but 싸요 in shopping usually means cheap.",explanation:'싸다 (ssada) = "to be cheap". Treat it as a building block that needs a frame: 싸요 ("It is cheap.") shows how it actually behaves. The grammar lives in the particle or ending beside 싸다, so notice that piece as you read, not just the dictionary meaning. Begin from a complete sentence about buying things, checking prices, quantities, and payment options and swap just one element to make it yours.',shortExplanation:'싸다 means "to be cheap" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Context matters: 싸요 can mean cheap or wraps, but shopping context makes it clear."],conjugationTips:[{title:"Describing a noun: ㄴ/은 vs ㄹ/을",body:'To put 싸다 in front of a noun, use the ㄴ/은 form for how something is right now: 싼 것 ("a cheap thing"). The ㄹ/을 form points to something that will or might become that way later. So 뜨거운 물 is water that is hot now, but 뜨거울 물 is water that will be hot — same adjective, different time feeling. For everyday description, reach for the ㄴ/은 form.'}],usagePhrases:[{ko:"싸요",romanization:"ssayo",en:"It is cheap.",note:"Polite."},{ko:"싸고 좋아요",romanization:"ssago joayo",en:"It is cheap and good.",note:"Connector."},{ko:"더 싼 거 있어요?",romanization:"deo ssan geo isseoyo?",en:"Do you have a cheaper one?",note:"Shopping."},{ko:"싸지 않아요",romanization:"ssaji anayo",en:"It is not cheap.",note:"Careful negative."}],examples:[{ko:"이거 싸요.",romanization:"igeo ssayo.",en:"This is cheap.",note:"Shopping."},{ko:"싸고 좋아요.",romanization:"ssago joayo.",en:"It is cheap and good.",note:"Connector."},{ko:"더 싼 거 있어요?",romanization:"deo ssan geo isseoyo?",en:"Do you have a cheaper one?",note:"Shopping."}],forms:null,irregular:null,level:"A1",cluster:null,chapters:[11,25]},연락하다:{ko:"연락하다",romanization:"yeollakada",en:"to contact / get in touch",pos:"verb",chapter:"11",ex:{ko:"도착하면 연락할게요.",en:"When I arrive, I'll contact you.",note:"면 (when/if condition) + 할게요 (speaker's promise): the connector and promise form working together"},collocations:["연락할게요","연락해 주세요","연락이 안 돼요"],nuance:"",explanation:"",shortExplanation:"",commonMistakes:[],conjugationTips:[],usagePhrases:[],examples:[],forms:null,irregular:null,level:"A1",cluster:null,chapters:[11]},약속:{ko:"약속",romanization:"yakssok",en:"appointment / promise / plans",pos:"noun",chapter:"11·18·30",ex:{ko:"약속이 있어서 일찍 가야 해요.",en:"I have plans, so I have to leave early.",note:"있어서 reason: having plans (약속) is the cause for needing to leave early"},collocations:["약속이 있어서","약속을 지키다","약속을 잡다"],nuance:"약속(約束, literally 'bind + tie' — a tying-together of words) carries two English senses Koreans treat as one: a PROMISE (a verbal commitment) and an APPOINTMENT/plans to meet someone. So 약속이 있어요 almost always means 'I have plans (to meet a person),' which surprises English speakers expecting 'I have a promise.' The signature collocations come as an opposed pair: 약속을 지키다 (keep a promise, lit. 'protect') vs 약속을 어기다 (break it, lit. 'violate'). Contrast 약속 with 예약 豫約 (a RESERVATION/booking for a restaurant, hotel, or hospital — 식당 예약), which is institutional, and with 계획 (your own plan, no other party). The English-speaker pitfalls: the 하다 particle slip 약속이 해요 (use 약속을 해요); using 약속 for a restaurant booking (that is 예약); and saying 약속을 깨다 — while understood, the idiomatic 'break a promise' is 약속을 어기다, whereas 깨다 ('shatter') fits cancelling an appointment (약속을 깨다 = bail on plans).",explanation:'약속 (yaksok) means "promise; appointment". Learn it inside a frame, not as a bare word: a useful first chunk is 약속을 해요 ("I make a promise"). In Korean the particle or ending next to 약속 signals its job — topic, subject, object, place, time, method, or description — so read the examples for the small piece beside it. Start with one real sentence about basic everyday communication, then change a single part.',shortExplanation:'약속 means "promise; appointment" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Saying 약속이 해요. Making a promise is transitive — say 약속을 해요 (or the verb 약속해요).","Using 약속 for a restaurant/hotel booking. A reservation is 예약 (식당을 예약했어요); 약속 is a promise or plans with a person.","Saying 약속을 안 지켜요 is fine, but the natural antonym verb for breaking a vow is 어기다 — 약속을 어겼어요."],conjugationTips:[],usagePhrases:[{ko:"약속을 해요",romanization:"yaksogeul haeyo",en:"I make a promise",note:"약속하다 = to promise; object 을"},{ko:"약속이 있어요",romanization:"yaksogi isseoyo",en:"I have plans (to meet someone)",note:"있다 = have; subject 이"},{ko:"약속을 지켜요",romanization:"yaksogeul jikyeoyo",en:"I keep my promise",note:"지키다 = keep/protect; object 을"},{ko:"약속을 어겨요",romanization:"yaksogeul eogyeoyo",en:"I break my promise",note:"어기다 = break/violate; the opposite of 지키다"}],examples:[{ko:"우리 내일 만나기로 약속했어요.",romanization:"uri naeil mannagiro yaksokaesseoyo.",en:"We promised to meet tomorrow.",note:"Simple: -기로 약속하다 = promise to do something."},{ko:"오늘 저녁에 친구하고 약속이 있어요.",romanization:"oneul jeonyeoge chinguhago yaksogi isseoyo.",en:"I have plans with a friend tonight.",note:"Everyday: 약속이 있다 — note this means an appointment, not a vow."},{ko:"약속을 꼭 지킬게요. 걱정 마세요.",romanization:"yaksogeul kkok jikilgeyo. geokjeong maseyo.",en:"I'll definitely keep my promise. Don't worry.",note:"Real situation: 약속을 지키다 + -ㄹ게요 commitment, reassuring tone."}],forms:null,irregular:null,level:"A2",cluster:null,chapters:[11,18,30]},나중에:{ko:"나중에",romanization:"najunge",en:"later",pos:"adverb",chapter:"11",ex:{ko:"나중에 전화할게요.",en:"I'll call later.",note:"나중에 + ㄹ게요: a complete speaker's promise anchored in time; this exact phrase appears in the chapter dialogue"},collocations:["나중에 전화할게요","나중에 만나요","나중에 얘기해요"],nuance:"나중에 means 'later' at some vague, unspecified future point — possibly today, possibly next week, the time is deliberately left open. That open-endedness is exactly why it's so handy for politely putting things off (나중에 할게요 'I'll do it later'). The sharp contrast to learn is 나중에 vs 이따가: 이따가 means 'a little later but still TODAY', whereas 나중에 carries no same-day promise and can mean any future time. Don't reach for English 'after' here — 나중에 is a standalone time adverb, not the connector '-(으)ㄴ 후에/다음에' you use to say 'after doing X'. Note the fixed 에 is baked in: the word is 나중에, and bare 나중 sounds incomplete in speech. It naturally collocates with 봐요, 연락하다, 다시, and 후회하다, and its opposite pole is 먼저/지금 (first/now).",explanation:'나중에 (najunge) = "later". Treat it as a building block that needs a frame: 나중에 봐요 ("see you later") shows how it actually behaves. The grammar lives in the particle or ending beside 나중에, so notice that piece as you read, not just the dictionary meaning. Begin from a complete sentence about basic everyday communication and swap just one element to make it yours.',shortExplanation:'나중에 means "later" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Using 나중에 for 'in a little while today', e.g. ✗ 나중에 점심 먹어요 meaning soon. For same-day soon use 이따가 점심 먹어요.","Dropping the 에 and saying just 나중 — the adverb is 나중에. Bare 나중 only survives in compounds like 나중 일 (a later matter).","Translating English 'after' with 나중에, e.g. ✗ 밥을 먹고 나중에 for 'after eating'. 'After doing X' is 밥을 먹은 후에 / 먹고 나서; 나중에 is just 'later' on its own."],conjugationTips:[],usagePhrases:[{ko:"나중에 봐요",romanization:"najunge bwayo",en:"see you later",note:"Standard friendly sign-off when you'll meet again at no fixed time."},{ko:"나중에 연락할게요",romanization:"najunge yeollakalgeyo",en:"I'll contact you later",note:"Polite way to defer without committing to when; 연락하다 = to get in touch."},{ko:"나중에 다시",romanization:"najunge dasi",en:"later, again",note:"Frequently paired with 다시 (again) for 'I'll try again later'."},{ko:"나중에 후회해요",romanization:"najunge huhoehaeyo",en:"you'll regret it later",note:"Common warning frame: 나중에 + a future consequence."}],examples:[{ko:"그건 나중에 이야기해요.",romanization:"geugeon najunge iyagihaeyo.",en:"Let's talk about that later.",note:"Gently deferring a topic right now; 나중에 before the verb."},{ko:"지금 바쁘니까 나중에 다시 전화할게요.",romanization:"jigeum bappeunikka najunge dasi jeonhwahalgeyo.",en:"I'm busy now, so I'll call back later.",note:"Pairs 지금 (now) against 나중에 (later) — the contrast that defines the word."},{ko:"이거 지금 안 하면 나중에 후회할 거예요.",romanization:"igeo jigeum an hamyeon najunge huhoehal geoyeyo.",en:"If you don't do this now, you'll regret it later.",note:"Real-situation warning; shows 나중에 reaching into an indefinite future."}],forms:null,irregular:null,level:"A2",cluster:{title:"곧 vs 이따가 vs 나중에",rule:"How far away is it? 곧 is minutes from now, 이따가 is later but still today, and 나중에 is an open, unpromised future — which is why 나중에 is the polite way to put something off.",members:[{ko:"곧",en:"soon, shortly, before long",romanization:"got",when:"about to happen, any minute",hint:'the "any minute now" soon',example:{ko:"버스가 곧 와요.",en:"The bus is coming soon."},self:!1},{ko:"이따가",en:"in a bit (later today)",romanization:"ittaga",when:"later the same day",hint:"later today, hours away at most",example:{ko:"이따가 다시 전화할게요.",en:"I'll call you again later today."},self:!1},{ko:"나중에",en:"later",romanization:"najunge",when:"putting something off",hint:"a vague later — maybe another day",example:{ko:"그건 나중에 얘기해요.",en:"Let's talk about that later."},self:!0}]},chapters:[11]},먼저:{ko:"먼저",romanization:"meonjeo",en:"first / ahead",pos:"adverb",chapter:"11·24·28·62",ex:{ko:"저는 먼저 갈게요.",en:"I'll go first.",note:"먼저 + 갈게요: classic speaker's promise/decision — the engineer announces departure first"},collocations:["먼저 갈게요","먼저 드세요","먼저 해요"],nuance:"먼저 means 'first / beforehand / ahead (of others)' — it ranks one action or person EARLIER in a sequence or in time. The key contrast is 먼저 vs 처음: 먼저 is relative ('before the other thing/person', e.g. 먼저 가요 'go ahead of you'), while 처음 means 'the first time ever / the beginning' (처음 만나요 'meeting for the first time'). So 먼저 봤어요 = 'I saw it first (before you)', but 처음 봤어요 = 'I saw it for the first time'. 먼저 is also a courtesy word: 먼저 가세요 / 먼저 하세요 ('go ahead, you first') is everyday politeness, and 먼저 갈게요 / 먼저 들어가겠습니다 softens leaving before others. Register-neutral. The English-speaker pitfall is mapping every 'first' to one word — choose 먼저 for order-relative 'first/ahead', but 처음 for 'first-ever/at first', and keep 먼저 before the verb.",explanation:`먼저 (meonjeo) means "first". Learn it inside a frame, not as a bare word: a useful first chunk is 먼저 가요 ("I'll go first / ahead"). In Korean the particle or ending next to 먼저 signals its job — topic, subject, object, place, time, method, or description — so read the examples for the small piece beside it. Start with one real sentence about basic everyday communication, then change a single part.`,shortExplanation:'먼저 means "first" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Using 처음 to mean 'go ahead of someone'. 처음 갈게요 sounds like 'I'll go for the first time'; to mean 'I'll go first (before you)' say 먼저 갈게요.","Conversely, using 먼저 for 'the first time'. 먼저 만나요 means 'meet first (before others)'; 'meet for the first time' is 처음 만나요.","Placing it after the verb. English 'you go first' tempts 가요 먼저; Korean order is 먼저 가요 (or politely 먼저 가세요)."],conjugationTips:[],usagePhrases:[{ko:"먼저 가요",romanization:"meonjeo gayo",en:"I'll go first / ahead",note:"leaving before others"},{ko:"먼저 하세요",romanization:"meonjeo haseyo",en:"please go ahead / do it first",note:"yielding politely"},{ko:"먼저 씻어요",romanization:"meonjeo ssiseoyo",en:"I wash up first",note:"earlier in a sequence"},{ko:"먼저 연락할게요",romanization:"meonjeo yeollakalgeyo",en:"I'll contact you first",note:"taking the initiative"}],examples:[{ko:"저 먼저 갈게요.",romanization:"jeo meonjeo galgeyo.",en:"I'll head off first.",note:"Simple: 먼저 = ahead of others in time/order, before 갈게요."},{ko:"손을 먼저 씻고 밥을 먹어요.",romanization:"soneul meonjeo ssitgo babeul meogeoyo.",en:"Wash your hands first, then eat.",note:"Everyday: 먼저 marks step one of a sequence (먼저 A 하고 B)."},{ko:"먼저 들어가 보겠습니다.",romanization:"meonjeo deureoga bogetseumnida.",en:"I'll be heading in/out first (leaving before you).",note:"Real situation: a polite set phrase to excuse yourself before colleagues — 'I'll go ahead.'"}],forms:null,irregular:null,level:"A2",cluster:{title:"먼저 vs 우선 vs 일단",rule:`먼저 is plain order — this action or person comes before that one. 우선 and 일단 both mean "first, before anything else" and often swap in speech; they differ in what they lean on: 우선 points at what matters most ("first and foremost"), 일단 at what's provisional ("let's do this much for now and sort out the rest later").`,members:[{ko:"먼저",en:"first",romanization:"meonjeo",when:"plain sequence, ahead of others",hint:'plain "before the other thing or person"',example:{ko:"먼저 손을 씻어요.",en:"I wash my hands first."},self:!0},{ko:"우선",en:"first of all, first and foremost, to begin with",romanization:"useon",when:"what matters most, do it first",hint:'"first and foremost" — or just "to begin with"',example:{ko:"우선 건강이 중요해요.",en:"Health comes first."},self:!1},{ko:"일단",en:"for now, first (before deciding the rest), once",romanization:"ildan",when:"a provisional first move",hint:'"for now" — decide the rest later',example:{ko:"일단 밥부터 먹어요.",en:"Let's eat first, for now."},self:!1}]},chapters:[11,24,28,62]},그럼:{ko:"그럼",romanization:"geureom",en:"then / in that case / well then",pos:"conjunction",chapter:"11",ex:{ko:"그럼 내일 만나면 얘기할게요.",en:"Well then, if we meet tomorrow, I'll talk about it.",note:"그럼 as discourse opener + 면 condition + 게요 promise: three connective tools in one natural sentence"},collocations:["그럼 갈게요","그럼 나중에요","그럼 됐어요"],nuance:"",explanation:"",shortExplanation:"",commonMistakes:[],conjugationTips:[],usagePhrases:[],examples:[],forms:null,irregular:null,level:"A1",cluster:null,chapters:[11]},문자:{ko:"문자",romanization:"munja",en:"text message",pos:"noun",chapter:"11·29·62",ex:{ko:"전화 못 하면 문자 보낼게요.",en:"If I can't call, I'll send a text.",note:"못 하면 (못 + 하다 + 면): double negative condition — the inability to call triggers the text promise"},collocations:["문자 보내다","문자 받다","문자 확인하다"],nuance:"문자 (文字, 'written character/letter') in daily speech is the everyday word for an SMS text message — short for 문자 메시지. The pitfall is its double life: literally 문자 means written characters/letters (e.g. 한글은 한국의 문자예요, 'Hangul is Korea's writing system'), so context decides. Crucially, 문자 is NOT a paper letter in the mail — that is 편지 (便紙). The near-synonym 카톡 (a KakaoTalk message) is what most people actually send now; 문자 specifically implies the carrier SMS (often bank/official notices), while a casual chat is 카톡 or 메시지. Register is neutral. Habitual collocations: 문자를 보내다/받다, 문자가 오다, 문자를 확인하다, 문자로 연락하다, and the source pattern 은행/회사에서 문자가 오다. Particle traps: 'by text' is 문자로 (means); the sender/source is marked 에서 for organizations (은행에서) or 한테서/에게서 for people. English speakers often want 'text' as a verb — Korean splits it into 문자를 보내다 (send a text).",explanation:'문자 (munja) means "text message". Learn it inside a frame, not as a bare word: a useful first chunk is 문자로 연락하다 ("to contact by text"). In Korean the particle or ending next to 문자 signals its job — topic, subject, object, place, time, method, or description — so read the examples for the small piece beside it. Start with one real sentence about basic everyday communication, then change a single part.',shortExplanation:'문자 means "text message" and is learned through practical beginner sentence frames.',commonMistakes:["Do not memorize this only as an English translation; memorize one Korean sentence frame.","Using 문자 for a posted letter. A physical mailed letter is 편지; 문자 is an SMS text (or, literally, written characters).","Saying 문자를 받았어요 when announcing an arrival. To say 'a text just came', Koreans say 문자가 왔어요 (오다). 받다 is fine for 'I received it', but the natural alert is 왔어요.","Forgetting 문자 needs a verb for 'to text'. There is no single verb; say 문자를 보내다 (send a text) or 문자로 연락하다 (contact by text)."],conjugationTips:[],usagePhrases:[{ko:"문자로 연락하다",romanization:"munjaro yeollakada",en:"to contact by text",note:"연락(連絡)하다 'get in touch'; 문자로 = by text. After a vowel the means particle is plain 로, and 문자 ends in the vowel ㅏ, so 문자로, never 문자으로."},{ko:"문자가 오다",romanization:"munjaga oda",en:"a text comes in",note:"오다 'come' is the natural verb for an incoming message; 문자가 왔어요 = a text arrived."},{ko:"문자를 보내다",romanization:"munjareul bonaeda",en:"to send a text",note:"보내다 'send'; the send/receive pair is 보내다 / 받다, and incoming ones 오다."},{ko:"문자를 확인하다",romanization:"munjareul hwaginhada",en:"to check a text",note:"확인(確認)하다 'confirm/check'; you 확인하다 a message you received."}],examples:[{ko:"문자가 왔어요.",romanization:"munjaga wasseoyo.",en:"A text came in.",note:"Incoming messages use 오다 (come), not 받다, in this announcing sense: 문자가 왔어요."},{ko:"은행에서 문자가 왔어요.",romanization:"eunhaengeseo munjaga wasseoyo.",en:"A text came from the bank.",note:"에서 marks the source 'from' (an organization); the bank as origin of the text."},{ko:"주소를 문자로 보내 주세요.",romanization:"jusoreul munjaro bonae juseyo.",en:"Please send the address by text.",note:"Means 문자로 'by text'; -아/어 주세요 for a polite request."}],forms:null,irregular:null,level:"A2",cluster:null,chapters:[11,29,62]},설명하다:{ko:"설명하다",romanization:"seolmyeonghada",en:"to explain",pos:"verb",chapter:"11·35",ex:{ko:"나중에 만나면 제가 설명할게요.",en:"If we meet later, I'll explain it.",note:"면 condition + 제가 설명할게요 (first-person promise): the engineer announces what they'll do when the switch is set"},collocations:["설명할게요","설명해 주세요","설명이 필요해요"],nuance:"설명하다 is 說明(설명)하다, hanja 說 'speak' + 明 'bright/clear', so it literally means to 'speak something into clarity' — you talk about a thing so the listener understands it. The dividing line against 설득하다 and 말하다 matters: 설명하다 is to make something UNDERSTOOD (neutral, informational), 설득하다 is to PERSUADE (change someone's mind), and 말하다 is just to 'say/tell' without the goal of clarifying. So '설명해 주세요' = 'help me understand,' which is far more specific than '말해 주세요' = 'just tell me.' The thing explained takes 을/를 (이유를 설명하다), and for a broad topic Koreans add -에 대해(서): 그 사건에 대해 설명했어요. Natural adverbs are 자세히 (in detail), 쉽게 (simply), 간단히 (briefly). The English-speaker pitfall is the construction 'explain me' / 'explain to me' — Korean attaches the listener with 에게/한테, not the object slot, and very often just uses 설명해 주다 (explain as a favor) to imply the listener. It is a regular 하다 verb: 설명 + 해요, negating as 설명 안 해요 / 설명 못 해요.",explanation:'"to explain" in Korean is 설명하다 (seolmyeonghada). In real conversation you will lean on the polite form 설명해요, so make that your default and leave the bare dictionary form 설명하다 for study notes. Grow outward from one concrete line — 이유를 설명하다 ("explain the reason") — then reshape the same stem into 설명하고 싶어요 (desire), 설명할 수 있어요 (ability), and 설명 못 해요 (a real limit) as the moment needs. The stem stays put; only the ending moves.',shortExplanation:'설명하다 means "to explain" and is practiced through polite conversation forms.',commonMistakes:["Do not use the dictionary form 설명하다 as a complete polite sentence.","Use 설명해요 as the default until you know the relationship is casual.","Mapping 'explain me' onto 저를 설명해요 (which means 'describe me as a person'). To explain TO me, use 저에게 설명해 주세요 or just 설명해 주세요.","Using 말하다 when you mean make-it-clear. 말하다 is merely 'say'; to clarify so someone understands, use 설명하다.","Confusing 설명하다 (explain) with 설득하다 (persuade) — explaining shares information; persuading changes a decision."],conjugationTips:[{title:"ㄹ / 을 — can & will",body:'To say "can" or the future, attach ㄹ/을 to the stem: a vowel-final stem takes ㄹ and a consonant-final stem takes 을. 설명하다 becomes 설명할 수 있어요 ("can") and 설명할 거예요 ("will"). That is why 가다 → 갈 수 있어요 (not 가을), while 먹다 → 먹을 수 있어요. The same ㄹ/을 choice drives 거예요 and the noun-describing form.'}],usagePhrases:[{ko:"설명해요",romanization:"seolmyeonghaeyo",en:"I explain.",note:"Safe polite present form."},{ko:"설명 안 해요",romanization:"seolmyeong an haeyo",en:"I do not explain.",note:"Short everyday negative."},{ko:"설명하고 싶어요",romanization:"seolmyeonghago sipeoyo",en:"I want to explain.",note:"Useful for choices and plans."},{ko:"설명할 수 있어요",romanization:"seolmyeonghal su isseoyo",en:"I can explain.",note:"Ability or possibility."},{ko:"설명해야 해요",romanization:"seolmyeonghaeya haeyo",en:"I have to explain.",note:"Requirement or obligation."},{ko:"이유를 설명하다",romanization:"iyureul seolmyeonghada",en:"explain the reason",note:"The thing explained takes 을/를: 이유를 설명해요"}],examples:[{ko:"이거 어떻게 해요? 설명해 줘.",romanization:"igeo eotteoke haeyo? seolmyeonghae jwo.",en:"How do I do this? Explain it to me.",note:"Simple: casual 설명해 줘 — asking a friend to walk you through something"},{ko:"선생님이 문법을 쉽게 설명해 주셨어요.",romanization:"seonsaengnimi munbeobeul swipge seolmyeonghae jusyeosseoyo.",en:"The teacher explained the grammar to us simply.",note:"Everyday: -아 주시다 shows the explaining was done as a favor by a senior"},{ko:"왜 늦었는지 자세히 설명해 주시겠어요?",romanization:"wae neujeonneunji jasehi seolmyeonghae jusigesseoyo?",en:"Could you explain in detail why you were late?",note:"Real situation: -는지 embeds the question being explained; 자세히 = in detail"}],forms:{dictionary:"설명하다",casualPresent:"설명해",politePresent:"설명해요",formalPresent:"설명합니다",negative:"설명 안 해요",past:"설명했어요",future:"설명할 거예요",want:"설명하고 싶어요",can:"설명할 수 있어요",cannot:"설명 못 해요",must:"설명해야 해요",dontHaveTo:"설명 안 해도 돼요",pleaseDo:"설명해 주세요",pleaseDont:"설명하지 마세요",shallWe:"설명할까요?"},irregular:null,level:"B1",cluster:null,chapters:[11,35]}};export{e as default};
